-- Russian choose_if + faq UPDATE — generated by gen_tool_choose_faq_ru.py
BEGIN;
UPDATE tools SET choose_if = $t1ci$["✅ Создаёте рекламные баннеры в больших объёмах для Facebook, Google и других платформ", "✅ Нужна ИИ-оценка эффективности рекламы до публикации (Score)", "✅ Хотите автоматически генерировать сотни вариантов рекламы для A/B-тестирования", "✅ Работаете в e-commerce и нужна продуктовая реклама с высоким CTR"]$t1ci$::JSONB, faq = $t1fq$[{"q": "AdCreative.ai vs Canva — для чего каждый?", "a": "AdCreative.ai специализируется на рекламе: генерирует баннеры, оценивает их эффективность и оптимизирует под конкретные платформы. Canva — универсальный дизайн для любого контента. Для профессиональной рекламы AdCreative точнее, для всего остального — Canva."}, {"q": "AdCreative.ai бесплатный?", "a": "AdCreative.ai не предлагает постоянного бесплатного плана — только пробный период. Starter — $21/мес (10 кредитов). Canva бесплатен с базовыми функциями; Canva Pro — $15/мес."}, {"q": "Насколько лучше реклама от AdCreative.ai?", "a": "AdCreative.ai утверждает, что их ИИ-баннеры превосходят человеческие дизайны по CTR. Платформа обучена на миллионах рекламных объявлений с данными о производительности. Реальные результаты варьируются в зависимости от ниши и качества исходного материала."}, {"q": "Canva подходит для создания рекламы?", "a": "Да. Canva имеет шаблоны для Facebook Ads, Google Display, Instagram и других платформ. Canva Pro добавляет удаление фона и Brand Kit. Для высоких объёмов и оптимизации CTR AdCreative.ai предлагает больше специализированных функций."}]$t1fq$::JSONB WHERE slug = 'adcreative-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t2ci$["✅ Нужны изображения без риска авторских прав — Firefly обучен на лицензированном контенте Adobe Stock", "✅ Вы уже используете Adobe Creative Cloud (Photoshop, Illustrator) — Firefly встроен в экосистему", "✅ Ваш проект — продуктовый или брендинговый визуал, где важна юридическая чистота", "✅ Хотите создавать видео и изображения в едином рабочем процессе Adobe"]$t2ci$::JSONB, faq = $t2fq$[{"q": "Безопасен ли Adobe Firefly в плане авторских прав?", "a": "Да. Adobe Firefly обучен исключительно на изображениях Adobe Stock, контенте с открытыми лицензиями и материалах общественного достояния. Созданные изображения можно использовать коммерчески без риска нарушения авторских прав — в отличие от большинства других генераторов."}, {"q": "Качество Midjourney выше, чем у Adobe Firefly?", "a": "По художественному и эстетическому качеству Midjourney, как правило, выдаёт более выразительные результаты. Firefly превосходит его в фотореалистичных снимках продуктов и брендинговом визуале. С выходом Firefly 3 (2025) разрыв существенно сократился."}, {"q": "Может ли Adobe Firefly генерировать видео?", "a": "Да. Видеомодель Adobe Firefly (запущена в 2024 году) создаёт короткие видеоклипы по текстовым запросам и интегрирована в Adobe Premiere Pro. Фокус — на коммерчески чистых видеоматериалах для профессионального производства."}, {"q": "Есть ли у Midjourney бесплатный план?", "a": "Нет. По состоянию на 2025 год Midjourney больше не предлагает бесплатного пробного периода. Самый дешёвый тариф — Basic за $10/мес (~200 генераций изображений в месяц)."}]$t2fq$::JSONB WHERE slug = 'adobe-firefly' AND lang = 'ru';
UPDATE tools SET choose_if = $t3ci$["✅ Нужно конкретно улучшение качества аудио с помощью ИИ — Enhance Speech замечательно удаляет фоновый шум", "✅ Записываете в шумном месте и хотите звучать как в студии", "✅ Вы подкастер, сосредоточенный именно на качестве аудио, а не видео", "✅ Уже используете Adobe Creative Cloud — Podcast интегрируется с Audition и Premiere"]$t3ci$::JSONB, faq = $t3fq$[{"q": "Для чего используется Descript?", "a": "Descript — редактор аудио и видео, где монтаж ведётся через текстовый транскрипт. Используется для подкастов, видеоконтента и записей экрана. Ключевые функции: автоматическое транскрибирование, удаление слов-паразитов, Overdub (клонирование голоса ИИ) и запись экрана."}, {"q": "Adobe Podcast бесплатный?", "a": "Adobe Podcast (теперь интегрированный в Adobe Firefly и Adobe Express) предлагает функцию Enhance Speech бесплатно с бесплатным аккаунтом Adobe. Расширенные функции требуют подписки Adobe Creative Cloud."}, {"q": "Может ли Descript удалять фоновый шум?", "a": "У Descript есть Studio Sound — ИИ-функция для снижения фонового шума и улучшения качества аудио. Работает хорошо, но Enhance Speech от Adobe Podcast в целом считается более мощным для очистки аудио."}, {"q": "Есть ли у Descript клонирование голоса ИИ?", "a": "Да. Функция Overdub в Descript создаёт ИИ-клон голоса из вашей записи. Можно вводить новые слова и озвучивать их своим голосом — полезно для исправления аудио без перезаписи."}]$t3fq$::JSONB WHERE slug = 'adobe-podcast' AND lang = 'ru';
UPDATE tools SET choose_if = $t4ci$["✅ Работаете в терминале и хотите автономного редактирования нескольких файлов с автоматическими git-коммитами", "✅ Хотите использовать собственный API-ключ (Claude, GPT-4, Gemini) — полная гибкость в выборе модели", "✅ Выполняете масштабный рефакторинг, где ИИ должен вносить изменения сразу в много файлов", "✅ Предпочитаете open-source инструменты с полной прозрачностью"]$t4ci$::JSONB, faq = $t4fq$[{"q": "Что такое Aider?", "a": "Aider — это open-source ИИ-ассистент для написания кода, работающий в терминале. Он подключается к ИИ-моделям (Claude, GPT-4, Gemini) и может редактировать несколько файлов одновременно, автоматически фиксируя изменения в git после каждого шага."}, {"q": "Aider лучше GitHub Copilot?", "a": "Они подходят для разных задач. Aider лучше для автономного рефакторинга нескольких файлов из командной строки. Copilot лучше для встроенных подсказок в реальном времени внутри IDE. Многие разработчики используют оба инструмента."}, {"q": "Aider бесплатный?", "a": "Aider как инструмент бесплатен и открыт. Вы платите за API-модель — расходы на Claude или GPT-4 API считаются по использованным токенам."}, {"q": "Работает ли GitHub Copilot без GitHub?", "a": "GitHub Copilot требует аккаунт GitHub, но работает в VS Code, JetBrains, Neovim и Visual Studio независимо от того, где хранится ваш код. Пушить код на GitHub для использования Copilot не обязательно."}]$t4fq$::JSONB WHERE slug = 'aider' AND lang = 'ru';
UPDATE tools SET choose_if = $t5ci$["✅ Нужны предиктивные модели машинного обучения без написания кода: прогноз оттока, скоринг лидов", "✅ Работаете в продажах или маркетинге и хотите ИИ-прогнозы на своих данных", "✅ Нужен ИИ для обработки данных с автоматическими рабочими процессами", "✅ Хотите встроить предиктивный ИИ в отчёты или CRM без привлечения дата-сайентиста"]$t5ci$::JSONB, faq = $t5fq$[{"q": "Akkio vs Julius AI — в чём разница?", "a": "Akkio строит предиктивные ML-модели (прогнозирование) по вашим данным. Julius AI анализирует данные через диалог: задаёте вопрос — получаете визуализацию. Akkio для прогностики, Julius для исследовательского анализа."}, {"q": "Akkio бесплатный?", "a": "Akkio предлагает бесплатный пробный период. Платные планы от $50/мес. Julius AI предлагает ограниченный бесплатный план; Pro — $20/мес."}, {"q": "Julius AI лучше ChatGPT для анализа данных?", "a": "Julius AI специализирован для анализа данных с сильным акцентом на визуализацию и статистику. ChatGPT с Code Interpreter также мощен, но Julius AI оптимизирован именно для датасетов и предлагает более чистый рабочий процесс."}, {"q": "Akkio требует знания ML?", "a": "Нет. Akkio позиционируется как no-code ML-платформа. Вы загружаете данные, выбираете целевую переменную и Akkio строит предиктивную модель. Экспертиза в машинном обучении не требуется."}]$t5fq$::JSONB WHERE slug = 'akkio' AND lang = 'ru';
UPDATE tools SET choose_if = $t6ci$["✅ Работаете с AWS-инфраструктурой — Q Developer понимает сервисы, IAM-политики и CloudFormation", "✅ Нужна помощь с миграцией Java-кода или устаревших приложений на AWS", "✅ Хотите ИИ-ассистента прямо в AWS Console и IDE с пониманием облачного контекста", "✅ Команда уже использует AWS и нужен ИИ, оптимизированный для облачной разработки"]$t6ci$::JSONB, faq = $t6fq$[{"q": "Amazon Q Developer vs GitHub Copilot — в чём разница?", "a": "Amazon Q Developer специализируется на разработке в AWS: помогает с CloudFormation, CDK, IAM и AWS-сервисами. GitHub Copilot — универсальный ИИ-ассистент для кодирования в любой среде. Q Developer для AWS-разработчиков, Copilot для всех."}, {"q": "Amazon Q Developer бесплатный?", "a": "Да. Amazon Q Developer имеет бесплатный уровень для индивидуальных разработчиков с базовыми функциями. Pro — $19/пользователь/мес с расширенными возможностями и командными функциями. GitHub Copilot Individual — $10/мес."}, {"q": "Может ли Amazon Q Developer помочь с миграцией кода?", "a": "Да. Q Developer имеет специализированную функцию трансформации кода: автоматически обновляет Java 8/11 приложения до Java 17 и помогает мигрировать VMware-рабочие нагрузки на AWS."}, {"q": "Интегрируется ли Q Developer с VS Code?", "a": "Да. Amazon Q Developer доступен как расширение для VS Code, JetBrains IDE, Visual Studio и AWS Cloud9. Также встроен прямо в AWS Console для помощи с облачными ресурсами."}]$t6fq$::JSONB WHERE slug = 'amazon-q-developer' AND lang = 'ru';
UPDATE tools SET choose_if = $t7ci$["✅ Хотите open-source ИИ-агент с полным контролем и возможностью локального запуска", "✅ Разработчик, которому нужна настраиваемая агентная основа для собственных задач", "✅ Хотите изучить основы ИИ-агентов через один из первых open-source проектов", "✅ Нужен агент, интегрирующийся с вашими инструментами и API через кастомный код"]$t7ci$::JSONB, faq = $t7fq$[{"q": "AutoGPT vs Manus — в чём разница?", "a": "AutoGPT — один из первых open-source ИИ-агентов, ориентированный на разработчиков и кастомизацию. Manus — коммерческий ИИ-агент общего назначения, ориентированный на конечных пользователей. AutoGPT для тех, кто хочет строить, Manus для тех, кто хочет использовать."}, {"q": "AutoGPT ещё актуален?", "a": "AutoGPT был пионером концепции ИИ-агентов в 2023 году. Сейчас более мощные альтернативы (Claude Code, Manus, Devin) превзошли его по качеству. Однако AutoGPT остаётся ценным open-source проектом для обучения и кастомизации."}, {"q": "Manus бесплатный?", "a": "Manus предлагает ограниченный бесплатный доступ для тестирования. Полный функционал требует подписки. AutoGPT с открытым кодом бесплатен, но платите за API-токены модели."}, {"q": "AutoGPT работает локально?", "a": "Да. AutoGPT можно запустить локально — код открыт. Для запуска нужен Python, Docker и API-ключ (OpenAI, Anthropic или другой). Это главное преимущество перед Manus для пользователей, заботящихся о конфиденциальности."}]$t7fq$::JSONB WHERE slug = 'autogpt' AND lang = 'ru';
UPDATE tools SET choose_if = $t8ci$["✅ Предпочитаете PowerPoint-подобный контроль слайдов с умными слайдами, автоформатирующимися при наборе", "✅ Нужны слайды, которые чисто экспортируются в PowerPoint для клиентов или презентаций", "✅ Создаёте традиционные бизнес-презентации со стандартной структурой слайдов", "✅ Хотите более привычный опыт редактора слайдов с помощью ИИ, а не полную генерацию ИИ"]$t8ci$::JSONB, faq = $t8fq$[{"q": "Что такое Gamma AI?", "a": "Gamma — инструмент для презентаций с ИИ, который создаёт полноценные спроектированные презентации из текстового запроса. В отличие от традиционных конструкторов слайдов, Gamma создаёт карточные веб-презентации, которыми делятся по ссылкам. Генерирует контент, макет и визуальное оформление одновременно за секунды."}, {"q": "Gamma бесплатный?", "a": "У Gamma есть бесплатный план с 400 кредитами ИИ (достаточно для нескольких полных презентаций). Plus — $10/мес, Pro — $20/мес для неограниченной генерации, собственных доменов и аналитики."}, {"q": "Может ли Beautiful.ai экспортировать в PowerPoint?", "a": "Да. Beautiful.ai может экспортировать презентации в формат PowerPoint (.pptx). Полезно, когда нужно делиться файлами с людьми, ожидающими традиционные форматы слайдов. Веб-нативный формат Gamma не экспортируется в PowerPoint так же чисто."}, {"q": "Что лучше для бизнес-презентаций — Gamma или Beautiful.ai?", "a": "Для быстрых ИИ-сгенерированных презентаций, которыми делятся в цифровом виде, Gamma быстрее и современнее. Для традиционных бизнес-презентаций, которые могут потребовать экспорта PowerPoint, Beautiful.ai даёт больше контроля. Оба производят профессиональные результаты."}]$t8fq$::JSONB WHERE slug = 'beautiful-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t9ci$["✅ Вы не разработчик или дизайнер, который хочет создать рабочее веб-приложение из текстового запроса", "✅ Нужна ссылка на готовое живое приложение за несколько минут без открытия терминала", "✅ Быстро прототипируете идею и вам не нужна локальная среда разработки", "✅ Хотите мгновенно опубликовать в интернете без знаний DevOps"]$t9ci$::JSONB, faq = $t9fq$[{"q": "Что такое Bolt.new?", "a": "Bolt.new — браузерный конструктор ИИ-приложений от StackBlitz. Опишите задачу на обычном языке, и он создаст полноценное веб-приложение с фронтендом, бэкендом и базой данных прямо в браузере без какой-либо локальной настройки."}, {"q": "Bolt.new лучше Cursor?", "a": "Они ориентированы на разных пользователей. Bolt.new — для быстрого прототипирования и не-разработчиков. Cursor — для профессиональных разработчиков с ИИ-помощью в локальной среде. Многие используют Bolt для прототипов, а Cursor — для продакшн-разработки."}, {"q": "Можно ли создать в Bolt.new настоящее продакшн-приложение?", "a": "Bolt.new может создавать готовый к продакшну код для небольших приложений. Для сложных приложений с нестандартной инфраструктурой разработчики обычно экспортируют код и продолжают в локальной IDE."}, {"q": "Сколько стоит Cursor?", "a": "Cursor предлагает бесплатный план Hobby с ограниченными запросами. Plan Pro — $20/мес с неограниченными автодополнениями и 500 быстрыми запросами. Business — $40/пользователь/мес с командными функциями и SSO."}]$t9fq$::JSONB WHERE slug = 'bolt-new' AND lang = 'ru';
UPDATE tools SET choose_if = $t10ci$["✅ Создаёте веб-приложение со сложной логикой: базы данных, авторизация, рабочие процессы", "✅ Нужен полноценный бэкенд: хранилище данных, API, бизнес-логика — без написания кода", "✅ Строите SaaS-продукт, маркетплейс или приложение, где пользователи взаимодействуют с данными", "✅ Нужны сложные пользовательские потоки, права доступа и кастомная логика"]$t10ci$::JSONB, faq = $t10fq$[{"q": "В чём разница между Bubble и Webflow?", "a": "Bubble — конструктор no-code приложений: для создания веб-приложений с базами данных, логикой и пользовательскими взаимодействиями. Webflow — конструктор сайтов с фокусом на дизайн и CMS. Bubble строит приложения, Webflow строит сайты."}, {"q": "Bubble подходит для SaaS?", "a": "Да. Bubble — одна из самых популярных платформ для создания SaaS-продуктов без кода. Он управляет авторизацией пользователей, базами данных, рабочими процессами и интеграцией API. Многие финансируемые стартапы используют Bubble как основную платформу."}, {"q": "Есть ли у Webflow база данных?", "a": "У Webflow есть CMS для структурированного контента (статьи блога, каталог товаров). Это не полноценная база данных приложения — для пользовательских данных, транзакций или сложной логики нужен Bubble или собственный бэкенд."}, {"q": "Что дешевле — Bubble или Webflow?", "a": "Стартовый план Webflow бесплатный. У Bubble тоже есть бесплатный план. Платные планы сопоставимы: Webflow Core от $29/мес, Bubble Starter от $32/мес. Стоимость масштабируется по-разному."}]$t10fq$::JSONB WHERE slug = 'bubble' AND lang = 'ru';
UPDATE tools SET choose_if = $t11ci$["✅ Вы маркетолог, SMM-менеджер или создатель контента — не дизайнер", "✅ Нужно быстро создавать публикации для соцсетей, презентации и маркетинговые материалы", "✅ Хотите Magic Media, Magic Write и 100+ ИИ-инструментов на одной платформе", "✅ В команде есть не-дизайнеры, которым нужно самостоятельно создавать брендированный контент"]$t11ci$::JSONB, faq = $t11fq$[{"q": "Canva AI бесплатный?", "a": "Canva предлагает бесплатный план с ограниченными ИИ-функциями. Canva Pro ($15/мес) открывает Magic Media, Magic Write, удаление фона и другие ИИ-инструменты."}, {"q": "Какие ИИ-функции есть у Figma?", "a": "Figma AI (запущен в 2024 году) включает генерацию макетов по текстовым запросам, умное переименование слоёв, создание прототипов и визуальный поиск. Доступен всем пользователям платных планов."}, {"q": "Может ли Canva заменить Figma?", "a": "Нет. Canva и Figma решают разные задачи. Canva — для создания маркетингового контента и презентаций. Figma — для проектирования UI/UX-интерфейсов и прототипов продуктов. Дизайнеры используют Figma, создатели контента — Canva."}, {"q": "Что лучше для начинающих — Canva или Figma?", "a": "Canva значительно проще для новичков — разработана для не-дизайнеров с простым drag-and-drop интерфейсом. Figma имеет более крутой порог вхождения и предназначена для профессиональных дизайнеров. Для быстрой графики начинайте с Canva."}]$t11fq$::JSONB WHERE slug = 'canva-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t12ci$["✅ Редактируете готовые видео для TikTok, Instagram Reels или YouTube Shorts", "✅ Нужны автосубтитры, переходы и синхронизация с музыкой для контента в соцсетях", "✅ Вы создатель контента, которому нужен быстрый мобильный видеоредактор", "✅ Хотите редактировать реальные видеоклипы, а не генерировать видео с нуля"]$t12ci$::JSONB, faq = $t12fq$[{"q": "В чём разница между CapCut и Kling AI?", "a": "CapCut — видеоредактор: вы импортируете готовые клипы и монтируете их. Kling AI — видеогенератор: создаёт видео из текстовых запросов или изображений. CapCut — для монтажа, Kling — для генерации."}, {"q": "Kling AI бесплатный?", "a": "Да. Kling AI предлагает бесплатный уровень с 66 ежедневными кредитами — самый щедрый среди качественных ИИ-генераторов видео. Plan Pro начинается от $6.99/мес."}, {"q": "Может ли CapCut генерировать ИИ-видео?", "a": "У CapCut есть некоторые функции генерации ИИ (Dream), но основная сила — монтаж готовых материалов. Для полноценной генерации видео из текстовых запросов Kling AI, Runway или Pika значительно мощнее."}, {"q": "CapCut бесплатный?", "a": "CapCut бесплатен с широким набором функций. CapCut Pro ($7.99/мес) добавляет удаление водяного знака, больше ИИ-функций и облачное хранилище. Бесплатная версия достаточна для большинства задач в соцсетях."}]$t12fq$::JSONB WHERE slug = 'capcut' AND lang = 'ru';
UPDATE tools SET choose_if = $t13ci$["✅ Хотите общаться с ИИ-персонажами: вымышленными героями, историческими личностями или кастомными ботами", "✅ Интересует развлечение, ролевые игры или опыт общения с компаньоном ИИ", "✅ Хотите создавать и делиться собственными ИИ-персонажами с сообществом", "✅ Вы писатель, использующий ИИ-персонажей для исследования диалогов и сценариев"]$t13ci$::JSONB, faq = $t13fq$[{"q": "Для чего используется Character.AI?", "a": "Character.AI используется для ролевых разговоров с ИИ-персонажами. Пользователи общаются с ИИ-версиями знаменитостей, вымышленных героев, исторических личностей или кастомными ботами. Прежде всего — для развлечения и творческого письма, не для рабочих задач."}, {"q": "Character.AI безопасен?", "a": "У Character.AI есть фильтры контента и верификация возраста. Однако платформа подвергалась критике из-за неприемлемых разговоров с несовершеннолетними. Родителям рекомендуется следить за использованием. После инцидентов 2024 года добавлены новые функции безопасности."}, {"q": "Поможет ли Character.AI с домашним заданием?", "a": "Character.AI может вести образовательные беседы, но часто ставит пребывание в образе выше точности фактов. Для домашних заданий ChatGPT, Claude или Khanmigo значительно надёжнее."}, {"q": "ChatGPT лучше Character.AI?", "a": "Для работы, исследований и реальных задач — да, ChatGPT значительно мощнее. Для развлечения, ролевых игр и разговоров с персонажами Character.AI создан специально и имеет большое сообщество. Они служат совершенно разным целям."}]$t13fq$::JSONB WHERE slug = 'character-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t14ci$["✅ Нужна самая широкая экосистема: генерация изображений (DALL-E), просмотр веб, интерпретатор кода, плагины", "✅ Нужен GPT-4o для мультимодальных задач: анализ изображений, голосовые разговоры, взаимодействие в реальном времени", "✅ Разрабатываете с OpenAI API — крупнейшая экосистема разработчиков", "✅ Нужен ИИ-ассистент с наиболее широкой интеграцией в сторонние приложения"]$t14ci$::JSONB, faq = $t14fq$[{"q": "Claude лучше ChatGPT?", "a": "Зависит от задачи. Claude в целом лучше справляется с длинными текстами и точнее обрабатывает большие документы. У ChatGPT больше функций (генерация изображений, голос, плагины) и более крупная экосистема. По бенчмаркам кода они конкурируют — Claude 3.7 лидирует во многих."}, {"q": "Что бесплатно — ChatGPT или Claude?", "a": "Оба имеют бесплатные планы. ChatGPT Free использует GPT-4o mini с ограниченным доступом к GPT-4o. Claude Free использует Claude 3.5 Haiku с ограниченным Claude 3.5 Sonnet. Оба платных плана ($20/мес) открывают лучшие модели с более высокими лимитами."}, {"q": "Может ли ChatGPT генерировать изображения?", "a": "Да. Планы ChatGPT Plus и выше включают генерацию изображений DALL-E 3. Claude не генерирует изображения — только текст и код."}, {"q": "Какой ИИ лучше для кода — ChatGPT или Claude?", "a": "Оба отличные. Claude 3.7 Sonnet с расширенным мышлением показывает лучшие результаты на SWE-bench (реальные задачи разработки) по состоянию на 2025 год. Claude Code специально создан для сложных рабочих процессов кодирования. ChatGPT с интерпретатором кода превосходит в анализе данных."}]$t14fq$::JSONB WHERE slug = 'chatgpt' AND lang = 'ru';
UPDATE tools SET choose_if = $t15ci$["✅ Хотите генерировать изображения прямо в ChatGPT в ходе разговора без смены инструмента", "✅ Нужна итеративная генерация через диалог: «сделай более синим», «добавь кота» — и изображение обновляется", "✅ Интегрируете генерацию изображений с текстовыми задачами ИИ (анализ + создание)", "✅ Используете ChatGPT Pro/Plus и хотите изображения как часть рабочего процесса"]$t15ci$::JSONB, faq = $t15fq$[{"q": "ChatGPT Images vs Adobe Firefly — что выбрать?", "a": "ChatGPT Images (powered by DALL-E 3/GPT-5.5) удобен для итеративной генерации в диалоге. Firefly безопаснее для коммерческого использования — обучен на лицензированном контенте. Для коммерческого контента — Firefly, для личного использования — ChatGPT Images."}, {"q": "Безопасно ли коммерчески использовать изображения ChatGPT?", "a": "По условиям OpenAI пользователи владеют созданным контентом. Однако Firefly имеет явную корпоративную защиту от претензий по авторским правам, поскольку обучен на лицензированных данных. Для критически важных коммерческих материалов Firefly безопаснее."}, {"q": "ChatGPT может редактировать существующие изображения?", "a": "Да. ChatGPT поддерживает загрузку изображений и их редактирование по инструкциям. Photoshop с Firefly предлагает более профессиональное редактирование с Generative Fill и Generative Expand."}, {"q": "Adobe Firefly доступен без Creative Cloud?", "a": "Да. Firefly.adobe.com предлагает веб-интерфейс с бесплатным планом (25 генераций/мес). Полный функционал внутри Photoshop и Illustrator требует подписки Creative Cloud."}]$t15fq$::JSONB WHERE slug = 'chatgpt-images' AND lang = 'ru';
UPDATE tools SET choose_if = $t16ci$["✅ Нужно самое длинное контекстное окно для анализа больших документов, кодовых баз или исследовательских работ", "✅ Задачи требуют точного и нюансированного написания текстов — качество прозы Claude стабильно выше", "✅ Выполняете агентные задачи: Claude 3.7 с расширенным мышлением глубже рассуждает о сложных проблемах", "✅ Приоритет — безопасность и тщательное рассуждение: Claude чаще честно признаёт незнание"]$t16ci$::JSONB, faq = $t16fq$[{"q": "Claude лучше ChatGPT?", "a": "Зависит от задачи. Claude в целом лучше справляется с длинными текстами и точнее обрабатывает большие документы. У ChatGPT больше функций (генерация изображений, голос, плагины) и более крупная экосистема. По бенчмаркам кода они конкурируют — Claude 3.7 лидирует во многих."}, {"q": "Что бесплатно — ChatGPT или Claude?", "a": "Оба имеют бесплатные планы. ChatGPT Free использует GPT-4o mini с ограниченным доступом к GPT-4o. Claude Free использует Claude 3.5 Haiku с ограниченным Claude 3.5 Sonnet. Оба платных плана ($20/мес) открывают лучшие модели с более высокими лимитами."}, {"q": "Может ли ChatGPT генерировать изображения?", "a": "Да. Планы ChatGPT Plus и выше включают генерацию изображений DALL-E 3. Claude не генерирует изображения — только текст и код."}, {"q": "Какой ИИ лучше для кода — ChatGPT или Claude?", "a": "Оба отличные. Claude 3.7 Sonnet с расширенным мышлением показывает лучшие результаты на SWE-bench (реальные задачи разработки) по состоянию на 2025 год. Claude Code специально создан для сложных рабочих процессов кодирования. ChatGPT с интерпретатором кода превосходит в анализе данных."}]$t16fq$::JSONB WHERE slug = 'claude' AND lang = 'ru';
UPDATE tools SET choose_if = $t17ci$["✅ Нужен рефакторинг, отладка или разработка по всей кодовой базе — не просто автодополнение", "✅ Работаете в терминале и хотите автономного агента, который планирует и выполняет многошаговые задачи", "✅ Занимаетесь сложной архитектурной работой, где ИИ нужно глубокое понимание проекта", "✅ Хотите наиболее мощную модель (Claude 3.7) для сложных инженерных задач"]$t17ci$::JSONB, faq = $t17fq$[{"q": "Что такое Claude Code?", "a": "Claude Code — агентный CLI-инструмент Anthropic для разработки ПО. В отличие от Copilot, который предлагает отдельные строки, Claude Code может планировать и выполнять многошаговые задачи по всей кодовой базе — редактировать файлы, запускать тесты и коммитить изменения автономно."}, {"q": "Claude Code лучше GitHub Copilot?", "a": "Для сложных многофайловых задач и автономных рабочих процессов Claude Code мощнее. Для встроенных подсказок в реальном времени Copilot удобнее. Многие разработчики используют оба: Copilot для ежедневного кодирования, Claude Code для крупных задач."}, {"q": "Сколько стоит Claude Code?", "a": "Claude Code требует подписки Claude Pro ($20/мес) или выше. Использует Claude 3.7 Sonnet, стоимость включена в подписку в рамках лимитов использования, с дополнительными расходами за превышение."}, {"q": "GitHub Copilot использует Claude?", "a": "GitHub Copilot использует преимущественно модели OpenAI. GitHub объявил о поддержке нескольких моделей, включая Claude и Gemini, что позволяет корпоративным пользователям выбирать предпочтительную модель с 2025 года."}]$t17fq$::JSONB WHERE slug = 'claude-code' AND lang = 'ru';
UPDATE tools SET choose_if = $t18ci$["✅ Хотите генерировать и итерировать UI-дизайны через диалог с Claude без открытия Figma", "✅ Создаёте быстрые концепции интерфейсов из описания для обсуждения с командой", "✅ Нужно быстрое прототипирование без глубоких навыков Figma", "✅ Работаете с Claude и хотите визуальные результаты прямо в разговоре"]$t18ci$::JSONB, faq = $t18fq$[{"q": "Что такое Claude Design?", "a": "Claude Design — функция генерации UI-дизайнов в Claude, позволяющая описать интерфейс текстом и получить визуальный результат. Это более экспериментальная функция для быстрого прототипирования, не замена профессиональному дизайн-инструменту."}, {"q": "Claude Design заменяет Figma?", "a": "Нет. Claude Design — для быстрой генерации концепций. Figma — для производственного дизайна с компонентами, токенами и handoff. Figma AI улучшает существующий дизайн-рабочий процесс, Claude Design — для итеративного исследования идей."}, {"q": "Figma AI бесплатный?", "a": "Figma AI включён в платные планы Figma (Professional от $15/мес/редактор). Claude бесплатен с ограниченными сообщениями; Pro — $20/мес."}, {"q": "Может ли Claude Code генерировать UI-компоненты?", "a": "Да. Claude Code может генерировать React, Vue или HTML/CSS-компоненты из описания. Это более мощный подход, чем Claude Design, — вы получаете рабочий код, а не только визуальный макет."}]$t18fq$::JSONB WHERE slug = 'claude-design' AND lang = 'ru';
UPDATE tools SET choose_if = $t19ci$["✅ Фокус на глубине контента и охвате темы — система оценки Clearscope более детализирована", "✅ Работаете с командой контента и нужны чёткие, общедоступные брифы", "✅ Пишете длинный контент, требующий комплексного исследования темы", "✅ Нужна интеграция с Google Docs и WordPress для плавного рабочего процесса"]$t19ci$::JSONB, faq = $t19fq$[{"q": "В чём разница между Clearscope и SurferSEO?", "a": "Оба — ИИ-инструменты оптимизации контента, но с разными сильными сторонами. Clearscope превосходит в оценке контента и анализе глубины темы. SurferSEO предлагает более полную платформу с редактором в реальном времени, исследованием ключевых слов и ИИ-написанием."}, {"q": "SurferSEO стоит своих денег?", "a": "Для контент-маркетологов, публикующих регулярно, SurferSEO за $99/мес обычно окупается. Он значительно сокращает время оптимизации контента, а его рекомендации хорошо коррелируют с улучшением позиций."}, {"q": "Есть ли у Clearscope ИИ-написание?", "a": "Clearscope фокусируется на анализе и оптимизации контента, а не на ИИ-написании. Он оценивает ваш контент и предлагает термины для включения. Для генерации контента лучше подходят SurferSEO (с Surfer AI) или Jasper."}, {"q": "Сколько стоит Clearscope?", "a": "Clearscope начинается от $189/мес за план Essentials — значительно дороже SurferSEO ($99/мес). Clearscope ориентирован на корпоративные контент-команды, SurferSEO охватывает более широкий спектр бюджетов."}]$t19fq$::JSONB WHERE slug = 'clearscope' AND lang = 'ru';
UPDATE tools SET choose_if = $t20ci$["✅ Нужен автономный ИИ-агент внутри VS Code, который планирует и выполняет многофайловые задачи", "✅ Используете собственный API-ключ (Claude, GPT-4, Gemini) и хотите полную гибкость в выборе модели", "✅ Выполняете сложный рефакторинг, где ИИ должен последовательно редактировать множество файлов", "✅ Предпочитаете open-source инструменты с полной прозрачностью действий ИИ"]$t20ci$::JSONB, faq = $t20fq$[{"q": "Что такое Cline?", "a": "Cline — open-source ИИ-агент для кодирования, работающий внутри VS Code. В отличие от Copilot, который предлагает отдельные строки, Cline может планировать и выполнять сложные многошаговые задачи — создавать файлы, выполнять команды и вносить изменения по всей кодовой базе автономно."}, {"q": "Cline бесплатный?", "a": "Cline сам по себе бесплатен и открыт. Вы платите только за API-модель — Claude, GPT-4 или Gemini. Интенсивное использование может стоить $10-50/мес в зависимости от выбранной модели."}, {"q": "Cline против Cursor — в чём разница?", "a": "Оба — ИИ-инструменты для кодирования, но Cline — расширение VS Code (вы сохраняете свой редактор), а Cursor — полный форк VS Code с более глубокой интеграцией ИИ. Cline использует ваш собственный API-ключ, Cursor включает доступ к модели в подписке. У Cursor более полированный опыт, у Cline — больше гибкости."}, {"q": "Работает ли GitHub Copilot вне GitHub?", "a": "GitHub Copilot работает в VS Code, JetBrains, Neovim, Visual Studio и других IDE независимо от того, где хранится ваш код. Нужен аккаунт GitHub, но использовать GitHub для контроля версий для получения подсказок Copilot не обязательно."}]$t20fq$::JSONB WHERE slug = 'cline' AND lang = 'ru';
UPDATE tools SET choose_if = $t21ci$["✅ Хотите максимальный контроль над пайплайном генерации через визуальные нодовые потоки", "✅ Создаёте кастомные рабочие процессы: ControlNet + LoRA + Upscaler в одной схеме", "✅ Нужна эффективная работа с памятью — ComfyUI лучше управляет VRAM", "✅ Строите автоматизированные пайплайны генерации изображений через API"]$t21ci$::JSONB, faq = $t21fq$[{"q": "ComfyUI vs Automatic1111 — в чём разница?", "a": "ComfyUI — нодовый редактор для создания кастомных пайплайнов генерации. Automatic1111 (WebUI) — традиционный веб-интерфейс для Stable Diffusion. ComfyUI мощнее для сложных рабочих процессов, Automatic1111 проще для начинающих."}, {"q": "ComfyUI быстрее Automatic1111?", "a": "Как правило — да. ComfyUI более эффективно управляет памятью GPU и может быть значительно быстрее для сложных задач. Для простой генерации разница небольшая."}, {"q": "ComfyUI сложно освоить?", "a": "Да. Нодовый интерфейс требует понимания пайплайна SD: сэмплеры, энкодеры, декодеры, VAE. Для начинающих Automatic1111 или Invoke AI более дружественны. Но ComfyUI стоит изучить для продвинутых рабочих процессов."}, {"q": "Работает ли ComfyUI с FLUX?", "a": "Да. ComfyUI отлично работает с FLUX.1 [schnell] и [dev]. Многие сложные FLUX-рабочие процессы (LoRA, ControlNet) созданы именно в ComfyUI."}]$t21fq$::JSONB WHERE slug = 'comfyui' AND lang = 'ru';
UPDATE tools SET choose_if = $t22ci$["✅ Нужны быстрые ответы на понятном языке, подкреплённые рецензируемыми статьями", "✅ Нужны счётчики консенсуса, показывающие, сколько исследований согласны или не согласны с утверждением", "✅ Вы студент, клиницист или специалист по политике, которому нужны быстрые ответы на основе доказательств", "✅ Нужен более простой интерфейс для поиска научного консенсуса без извлечения данных"]$t22ci$::JSONB, faq = $t22fq$[{"q": "Что такое Elicit?", "a": "Elicit — ИИ-ассистент для исследований, разработанный для систематических обзоров литературы. Ищет в академических базах данных, отбирает статьи по релевантности и извлекает структурированные данные в таблицы — автоматизируя наиболее трудоёмкие части академических исследований."}, {"q": "В чём разница между Elicit и Consensus?", "a": "Elicit создан для систематических обзоров — извлекает структурированные данные из статей для мета-анализа. Consensus создан для быстрых вопросов и ответов — синтезирует выводы в ответы на понятном языке со счётчиком консенсуса. Elicit — для глубоких рабочих процессов, Consensus — для быстрых ответов."}, {"q": "Elicit бесплатный?", "a": "У Elicit есть бесплатный план с 5000 кредитами в месяц (примерно 500 сводок статей). Elicit Plus — $12/мес для 15 000 кредитов, доступны более высокие уровни для команд и учреждений."}, {"q": "Может ли Elicit заменить исследовательского ассистента?", "a": "Elicit может выполнять механические части систематических обзоров: отбор статей, извлечение данных и суммирование. Он значительно сокращает часы работы ассистента для обзоров литературы. Однако экспертная оценка качества и интерпретация выводов по-прежнему требуют исследователей-людей."}]$t22fq$::JSONB WHERE slug = 'consensus' AND lang = 'ru';
UPDATE tools SET choose_if = $t23ci$["✅ Хотите open-source ИИ-помощника кода с возможностью выбора любой модели (Claude, GPT, Llama)", "✅ Нужен полный контроль: свои модели, локальный запуск через Ollama без отправки кода в облако", "✅ Хотите кастомизировать ИИ-опыт под свой стек и предпочтения", "✅ Ищете бесплатную альтернативу Copilot с похожим функционалом"]$t23ci$::JSONB, faq = $t23fq$[{"q": "Что такое Continue.dev?", "a": "Continue.dev — open-source плагин для VS Code и JetBrains, добавляющий ИИ-функции: автодополнение, чат и редактирование. Уникальная особенность — поддержка любой модели: Claude, GPT-4, Gemini или локальные через Ollama."}, {"q": "Continue.dev бесплатный?", "a": "Continue.dev как плагин бесплатен с открытым исходным кодом. Стоимость зависит от выбранной модели: локальные (Ollama, LM Studio) — бесплатно, Claude/GPT-4 — по тарифам API. GitHub Copilot — $10/мес."}, {"q": "Continue.dev работает офлайн?", "a": "Да, при использовании локальных моделей через Ollama. Настройте Ollama с Code Llama или Mistral — Continue.dev работает без интернета и не отправляет код в облако."}, {"q": "Continue.dev так же хорош, как Copilot?", "a": "С сильными моделями (Claude Sonnet 4.6, GPT-5.5) — качество сравнимо. Copilot более отполирован и прост в использовании. Continue.dev выигрывает в гибкости и стоимости при использовании локальных моделей."}]$t23fq$::JSONB WHERE slug = 'continue-dev' AND lang = 'ru';
UPDATE tools SET choose_if = $t24ci$["✅ Нужен ИИ-генератор текста: рекламные объявления, посты, письма, описания товаров", "✅ Создаёте большие объёмы маркетингового контента быстро и дёшево", "✅ Хотите автоматизировать написание контента для команды с помощью ИИ-рабочих процессов", "✅ Ограниченный бюджет — Copy.ai значительно дешевле Semrush"]$t24ci$::JSONB, faq = $t24fq$[{"q": "Semrush vs Copy.ai — это сравнение разных инструментов?", "a": "Да. Semrush — SEO-платформа для анализа данных, исследования ключевых слов и аудита сайтов. Copy.ai — ИИ-генератор контента для написания текстов. Они решают разные задачи, хотя оба используются в контент-маркетинге."}, {"q": "Semrush бесплатный?", "a": "Semrush предлагает ограниченный бесплатный план (10 запросов в день). Pro план — от $139.95/мес. Copy.ai бесплатен с ограниченными словами; платные планы от $49/мес."}, {"q": "Нужны ли оба инструмента?", "a": "Для контент-маркетинга — да: Semrush находит ключевые слова и темы для контента, Copy.ai помогает его написать быстро. Многие маркетинговые команды используют оба в связке."}, {"q": "Есть ли у Semrush функции ИИ-написания?", "a": "Да. Semrush добавил ContentShake AI — инструмент для написания SEO-статей, который использует данные ключевых слов Semrush. Это более специализированный инструмент, чем Copy.ai, но дороже."}]$t24fq$::JSONB WHERE slug = 'copy-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t25ci$["✅ Проходите курсы на Coursera и хотите ИИ-помощника прямо в учебном процессе", "✅ Нужна помощь с профессиональными сертификациями (Google, IBM, Meta) на Coursera", "✅ Хотите объяснения сложных тем из конкретного курса, который вы проходите", "✅ Учитесь для карьерного роста и нужен ИИ, понимающий контекст профессиональных курсов"]$t25ci$::JSONB, faq = $t25fq$[{"q": "Coursera Coach vs Khanmigo — для кого?", "a": "Coursera Coach встроен в Coursera и помогает с профессиональными онлайн-курсами. Khanmigo — ИИ-репетитор Khan Academy для школьников и студентов по общеобразовательным предметам. Разные платформы, разные аудитории."}, {"q": "Coursera Coach бесплатный?", "a": "Coursera Coach включён в Coursera Plus ($59/мес или $399/год). Отдельной подписки на Coach нет. Khanmigo — $9/мес как дополнение к бесплатной Khan Academy."}, {"q": "Coursera Coach заменяет живого преподавателя?", "a": "Нет, но снижает потребность в нём для многих задач. Coach отвечает на вопросы по материалу курса, объясняет концепции и помогает с заданиями 24/7. Для сложных вопросов форумы с живыми преподавателями по-прежнему ценнее."}, {"q": "Работает ли Khanmigo на английском только?", "a": "Khanmigo работает преимущественно на английском. Khan Academy активно расширяет поддержку других языков, но нативная поддержка пока ограничена. Coursera Coach поддерживает языки курсов на платформе."}]$t25fq$::JSONB WHERE slug = 'coursera-coach' AND lang = 'ru';
UPDATE tools SET choose_if = $t26ci$["✅ Нужна полноценная IDE, созданная вокруг ИИ — не просто автодополнение в существующем редакторе", "✅ Нужно, чтобы ИИ понимал контекст всей кодовой базы для точных подсказок", "✅ Нужны Composer (многофайловое редактирование) и чат с полным знанием кодовой базы", "✅ Продвинутый пользователь, которому нужен лучший доступный опыт ИИ-кодирования"]$t26ci$::JSONB, faq = $t26fq$[{"q": "Cursor лучше GitHub Copilot?", "a": "Cursor в целом обеспечивает более мощную ИИ-помощь — контекст всей кодовой базы и многофайловое редактирование в Composer мощнее встроенных подсказок Copilot. Но Copilot поддерживает больше IDE и имеет корпоративные функции. Cursor — выбор для индивидуальных разработчиков, которые хотят лучший ИИ-опыт."}, {"q": "Cursor бесплатный?", "a": "Cursor имеет бесплатный план Hobby с ограниченными запросами (2000 дополнений/мес). Plan Pro — $20/мес с неограниченными дополнениями и 500 быстрыми запросами Claude/GPT-4. Business — $40/пользователь/мес."}, {"q": "Cursor использует Claude или GPT-4?", "a": "Cursor поддерживает несколько ИИ-моделей: Claude 3.5 Sonnet, GPT-4o и собственные дообученные модели Cursor. Пользователи Pro могут выбирать модель. Claude 3.5 Sonnet обычно рекомендуется для сложных задач кодирования."}, {"q": "Можно использовать GitHub Copilot и Cursor вместе?", "a": "Да, но они будут значительно перекрываться. Большинство разработчиков выбирают один основной инструмент. Cursor обычно предпочтителен за более мощные функции, а Copilot остаётся для команд с корпоративными рабочими процессами GitHub."}]$t26fq$::JSONB WHERE slug = 'cursor' AND lang = 'ru';
UPDATE tools SET choose_if = $t27ci$["✅ Профессионально переводите документы между языками — качество DeepL лучшее в своём классе", "✅ Нужен массовый перевод документов (PDF, Word, PowerPoint) с сохранением форматирования", "✅ Работаете в многоязычной команде или общаетесь с международными клиентами", "✅ Нужен глоссарий для обеспечения единой терминологии в переводах"]$t27ci$::JSONB, faq = $t27fq$[{"q": "Может ли DeepL улучшить мои тексты?", "a": "DeepL Write (отдельный инструмент от DeepL Translate) улучшает тексты на английском и немецком, переформулируя предложения для ясности и стиля. Менее комплексен, чем Grammarly для проверки грамматики, но силён в переформулировках."}, {"q": "Grammarly хорош для перевода?", "a": "Grammarly не переводит между языками — работает только с текстами на английском (и базовая проверка для некоторых других языков). Для перевода подходит DeepL."}, {"q": "DeepL бесплатный?", "a": "DeepL предлагает бесплатный план с переводом текста до 5000 символов за запрос и 3 переводами документов в месяц. DeepL Pro начинается от $8.74/мес для неограниченного перевода текста."}, {"q": "Что точнее — DeepL или Google Переводчик?", "a": "DeepL стабильно превосходит Google Переводчик по точности и естественности, особенно для европейских языков. Google Переводчик поддерживает больше языков (100+ против 31 у DeepL), но качество DeepL для поддерживаемых языков выше."}]$t27fq$::JSONB WHERE slug = 'deepl' AND lang = 'ru';
UPDATE tools SET choose_if = $t28ci$["✅ Нужен лучший бесплатный ИИ для рассуждений и математики — DeepSeek R1 конкурирует с o1 по нулевой цене", "✅ Разработчик, которому нужен очень дешёвый доступ к API — API DeepSeek в 20-40 раз дешевле GPT-4", "✅ Работаете над кодом и техническими задачами, где полезно цепочное рассуждение", "✅ Не нужны генерация изображений или голос, и хотите максимальную ценность рассуждений бесплатно"]$t28ci$::JSONB, faq = $t28fq$[{"q": "DeepSeek лучше ChatGPT?", "a": "DeepSeek R1 соответствует или превосходит GPT-o1 по бенчмаркам рассуждений и математики — за долю стоимости. Для чистого текстового рассуждения и кода DeepSeek конкурентоспособен с лучшими моделями. У ChatGPT больше функций (изображения, голос, плагины) и лучшая экосистема."}, {"q": "DeepSeek безопасен для использования?", "a": "DeepSeek — китайская компания. Некоторые организации опасаются конфиденциальности данных по китайскому законодательству. Веса модели открыты и могут запускаться локально. Государственные органы США и некоторые компании ограничили его использование."}, {"q": "DeepSeek бесплатный?", "a": "Да. DeepSeek на chat.deepseek.com бесплатен без ограничений использования через веб-интерфейс. API также очень дёшев — около $0.14 за миллион входных токенов для DeepSeek V3, против $2.50 для GPT-4o mini."}, {"q": "Что такое DeepSeek R1?", "a": "DeepSeek R1 — модель рассуждений DeepSeek, выпущенная в январе 2025 года. Использует цепочное рассуждение, аналогичное OpenAI o1, и достигла сопоставимых бенчмарков. Она потрясла индустрию ИИ, показав производительность фронтирных моделей при значительно меньших затратах."}]$t28fq$::JSONB WHERE slug = 'deepseek' AND lang = 'ru';
UPDATE tools SET choose_if = $t29ci$["✅ Редактируете подкасты или видео, редактируя транскрипт — самый интуитивный рабочий процесс", "✅ Хотите удалить слова-паразиты (э-э, ну) одним кликом по всей записи", "✅ Нужна запись экрана, редактирование видео и производство подкастов в одном инструменте", "✅ Создаёте YouTube-контент и нужно редактирование и видео, и аудио в одном месте"]$t29ci$::JSONB, faq = $t29fq$[{"q": "Для чего используется Descript?", "a": "Descript — редактор аудио и видео, где монтаж ведётся через текстовый транскрипт. Используется для подкастов, видеоконтента и записей экрана. Ключевые функции: автоматическое транскрибирование, удаление слов-паразитов, Overdub (клонирование голоса ИИ) и запись экрана."}, {"q": "Adobe Podcast бесплатный?", "a": "Adobe Podcast (теперь интегрированный в Adobe Firefly и Adobe Express) предлагает функцию Enhance Speech бесплатно с бесплатным аккаунтом Adobe. Расширенные функции требуют подписки Adobe Creative Cloud."}, {"q": "Может ли Descript удалять фоновый шум?", "a": "У Descript есть Studio Sound — ИИ-функция для снижения фонового шума и улучшения качества аудио. Работает хорошо, но Enhance Speech от Adobe Podcast в целом считается более мощным для очистки аудио."}, {"q": "Есть ли у Descript клонирование голоса ИИ?", "a": "Да. Функция Overdub в Descript создаёт ИИ-клон голоса из вашей записи. Можно вводить новые слова и озвучивать их своим голосом — полезно для исправления аудио без перезаписи."}]$t29fq$::JSONB WHERE slug = 'descript' AND lang = 'ru';
UPDATE tools SET choose_if = $t30ci$["✅ Нужен автономный ИИ-инженер по ПО, который может планировать и выполнять целые проекты кодирования", "✅ Нужен ИИ, работающий в собственной среде — браузер, терминал, редактор — для выполнения задач кодирования", "✅ Есть чётко определённые инженерные задачи: исправление ошибок, реализация функций, написание тестов", "✅ Вы команда, желающая масштабировать инженерный вывод без найма новых разработчиков"]$t30ci$::JSONB, faq = $t30fq$[{"q": "Что такое Devin AI?", "a": "Devin — автономный ИИ-инженер по ПО от Cognition AI. Работает в собственной изолированной среде с браузером, терминалом и редактором кода и может выполнять многошаговые инженерные задачи — планирование, реализацию, тестирование и отладку — с минимальным участием человека."}, {"q": "Сколько стоит Devin?", "a": "Devin доступен как корпоративный продукт. Цены не публикуются публично и требуют контакта с Cognition AI. Версия Teams для небольших организаций была анонсирована в 2025 году. Разработан для инженерных команд, не для отдельных разработчиков."}, {"q": "Devin лучше GitHub Copilot?", "a": "Они служат разным целям. Devin — автономный агент, выполняющий целые задачи. Copilot — ассистент, помогающий разработчикам при написании кода. Devin заменяет инженерные усилия на определённых задачах, Copilot усиливает продуктивность разработчика. Оба могут использоваться вместе."}, {"q": "Что может создать Copilot Studio?", "a": "Copilot Studio может создавать чатботы клиентского сервиса, HR-ассистентов, IT-помощников, внутренние базы знаний с вопросами и ответами, а также автоматизированные рабочие процессы, подключённые к данным Microsoft 365. Разработан для бизнес-сценариев, а не для автоматизации разработки ПО."}]$t30fq$::JSONB WHERE slug = 'devin' AND lang = 'ru';
UPDATE tools SET choose_if = $t31ci$["✅ Изучаете иностранный язык и хотите разговорную практику с ИИ-преподавателем", "✅ Хотите объяснения ответов в Duolingo и ролевые сценарии с ИИ", "✅ Нужна геймифицированная языковая практика с дополнительными ИИ-функциями", "✅ Учите один из 40 языков и хотите прогресс в игровом формате"]$t31ci$::JSONB, faq = $t31fq$[{"q": "Photomath vs Duolingo Max — это разные инструменты?", "a": "Да, полностью разные. Photomath — решатель математических задач по фото. Duolingo Max — премиум-уровень языкового приложения с ИИ. Photomath для математики, Duolingo для языков."}, {"q": "Photomath бесплатный?", "a": "Photomath бесплатен с базовыми решениями. Photomath Plus ($9.99/мес или $59.99/год) добавляет анимированные пошаговые объяснения. Duolingo Max — $30/мес или $168/год."}, {"q": "Duolingo Max стоит своих денег?", "a": "Duolingo Max добавляет Roleplay (ролевые сценарии с ИИ) и Explain My Answer (объяснения ошибок). Для серьёзного изучения языка — хорошее дополнение. Базовый Duolingo бесплатен и эффективен для начального уровня."}, {"q": "Что точнее — Photomath или ChatGPT для математики?", "a": "Оба хороши, но по-разному. Photomath специализируется на математике и пошаговых решениях — очень точен для школьного уровня. ChatGPT охватывает более широкий математический контекст, но может ошибаться в сложных задачах."}]$t31fq$::JSONB WHERE slug = 'duolingo-max' AND lang = 'ru';
UPDATE tools SET choose_if = $t32ci$["✅ Создаёте аудиоконтент, нарративные видео или подкасты с реалистичными голосами", "✅ Нужен клон вашего голоса для профессионального озвучивания", "✅ Строите продукт с TTS-API — ElevenLabs предлагает лучший в классе синтез речи", "✅ Нужны многоязычные дубляж или синтез эмоциональной речи"]$t32ci$::JSONB, faq = $t32fq$[{"q": "Speechify vs ElevenLabs — в чём разница?", "a": "Speechify — читалка вслух: для личного потребления контента. ElevenLabs — студия синтеза речи: для создания аудиоконтента и разработки приложений. Speechify слушает чужой контент, ElevenLabs создаёт свой."}, {"q": "Speechify бесплатный?", "a": "Speechify предлагает бесплатный план с базовыми голосами. Premium ($139/год) открывает лучшие голоса и более высокую скорость. ElevenLabs бесплатен с 10 000 символов в месяц."}, {"q": "ElevenLabs лучше Speechify для создания подкастов?", "a": "Для создания подкастов — ElevenLabs. Для прослушивания подкастов и статей — Speechify. ElevenLabs создаёт реалистичный синтез для производства, Speechify воспроизводит контент для личного потребления."}, {"q": "Может ли Speechify клонировать голос?", "a": "Да. Speechify Voice Studio включает клонирование голоса. Однако ElevenLabs предлагает лучшее качество клонирования с меньшим количеством образцов и более естественным результатом."}]$t32fq$::JSONB WHERE slug = 'elevenlabs' AND lang = 'ru';
UPDATE tools SET choose_if = $t33ci$["✅ Проводите систематические обзоры литературы и нужно извлечение структурированных данных из многих статей", "✅ Хотите автоматизировать фазу отбора и извлечения данных в академических исследованиях", "✅ Нужны таблицы с конкретными полями (размер выборки, методология, результаты) по разным исследованиям", "✅ Вы исследователь, проводящий мета-анализ и обрабатывающий десятки или сотни статей"]$t33ci$::JSONB, faq = $t33fq$[{"q": "Что такое Elicit?", "a": "Elicit — ИИ-ассистент для исследований, разработанный для систематических обзоров литературы. Ищет в академических базах данных, отбирает статьи по релевантности и извлекает структурированные данные в таблицы — автоматизируя наиболее трудоёмкие части академических исследований."}, {"q": "В чём разница между Elicit и Consensus?", "a": "Elicit создан для систематических обзоров — извлекает структурированные данные из статей для мета-анализа. Consensus создан для быстрых вопросов и ответов — синтезирует выводы в ответы на понятном языке со счётчиком консенсуса. Elicit — для глубоких рабочих процессов, Consensus — для быстрых ответов."}, {"q": "Elicit бесплатный?", "a": "У Elicit есть бесплатный план с 5000 кредитами в месяц (примерно 500 сводок статей). Elicit Plus — $12/мес для 15 000 кредитов, доступны более высокие уровни для команд и учреждений."}, {"q": "Может ли Elicit заменить исследовательского ассистента?", "a": "Elicit может выполнять механические части систематических обзоров: отбор статей, извлечение данных и суммирование. Он значительно сокращает часы работы ассистента для обзоров литературы. Однако экспертная оценка качества и интерпретация выводов по-прежнему требуют исследователей-людей."}]$t33fq$::JSONB WHERE slug = 'elicit' AND lang = 'ru';
UPDATE tools SET choose_if = $t34ci$["✅ Вы UI/UX дизайнер, создающий интерфейсы продуктов и интерактивные прототипы", "✅ Команда использует Figma для передачи макетов разработчикам — ИИ-функции уже встроены", "✅ Нужен ИИ для создания компонентов, автоматической раскладки и работы с дизайн-системой", "✅ Нужен точный контроль над дизайном с переменными, ограничениями и инспектом для разработчиков"]$t34ci$::JSONB, faq = $t34fq$[{"q": "Canva AI бесплатный?", "a": "Canva предлагает бесплатный план с ограниченными ИИ-функциями. Canva Pro ($15/мес) открывает Magic Media, Magic Write, удаление фона и другие ИИ-инструменты."}, {"q": "Какие ИИ-функции есть у Figma?", "a": "Figma AI (запущен в 2024 году) включает генерацию макетов по текстовым запросам, умное переименование слоёв, создание прототипов и визуальный поиск. Доступен всем пользователям платных планов."}, {"q": "Может ли Canva заменить Figma?", "a": "Нет. Canva и Figma решают разные задачи. Canva — для создания маркетингового контента и презентаций. Figma — для проектирования UI/UX-интерфейсов и прототипов продуктов. Дизайнеры используют Figma, создатели контента — Canva."}, {"q": "Что лучше для начинающих — Canva или Figma?", "a": "Canva значительно проще для новичков — разработана для не-дизайнеров с простым drag-and-drop интерфейсом. Figma имеет более крутой порог вхождения и предназначена для профессиональных дизайнеров. Для быстрой графики начинайте с Canva."}]$t34fq$::JSONB WHERE slug = 'figma-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t35ci$["✅ Нужен ИИ-ассистент для анализа финансовых отчётов, 10-K и данных о компаниях", "✅ Фундаментальный инвестор, которому нужны данные KPI, мультипликаторы и сравнения сегментов", "✅ Хотите задавать вопросы о компаниях на естественном языке и получать данные из отчётности", "✅ Исследуете 750 000+ финансовых KPI компаний для инвестиционного анализа"]$t35ci$::JSONB, faq = $t35fq$[{"q": "TradingView vs Finchat — для кого каждый?", "a": "TradingView — для технических трейдеров и тех, кто анализирует графики. Finchat — для фундаментальных инвесторов, изучающих финансовую отчётность компаний. Это разные инструменты для разных стилей инвестирования."}, {"q": "TradingView бесплатный?", "a": "TradingView имеет бесплатный план с ограниченными индикаторами и алертами. Essential — $12.95/мес, Plus — $24.95/мес, Premium — $49.95/мес. Finchat предлагает бесплатный план с базовыми данными; Pro — $22/мес."}, {"q": "Что такое Finchat?", "a": "Finchat — ИИ-финансовый аналитик с доступом к 750 000+ KPI из отчётности публичных компаний. Задайте вопрос на естественном языке — получите данные из 10-K, 10-Q и звонков с аналитиками с ссылками на источники."}, {"q": "Можно ли торговать через TradingView?", "a": "Да. TradingView интегрируется с рядом брокеров (Interactive Brokers, Alpaca и другими), позволяя торговать прямо из интерфейса. Это уникальная функция, которой нет у большинства чисто аналитических платформ."}]$t35fq$::JSONB WHERE slug = 'finchat' AND lang = 'ru';
UPDATE tools SET choose_if = $t36ci$["✅ Нужен универсальный бот для встреч, который автоматически заходит в любой звонок", "✅ Нужны расшифровки на 60+ языках с автоопределением языка", "✅ Хотите анализировать настроение разговора и отслеживать темы по множеству встреч", "✅ Нужна интеграция с большим количеством CRM и рабочих инструментов"]$t36ci$::JSONB, faq = $t36fq$[{"q": "Otter.ai vs Fireflies.ai — в чём разница?", "a": "Оба транскрибируют встречи, но с разными акцентами. Otter.ai известен высокой точностью транскрипции в реальном времени и интеграцией с Salesforce. Fireflies.ai предлагает более широкую языковую поддержку, аналитику разговоров и больше CRM-интеграций."}, {"q": "Otter.ai бесплатный?", "a": "Да. Otter.ai предлагает бесплатный план с 600 минутами транскрипции в месяц и 3 импортами. Pro — $17/мес. Fireflies.ai также имеет бесплатный план с ограниченным хранилищем транскрипций."}, {"q": "Работает ли Otter.ai в Google Meet?", "a": "Да. Otter.ai интегрируется с Google Meet, Zoom и Teams. Автоматически входит в запланированные встречи и начинает транскрипцию."}, {"q": "Точность Fireflies.ai хороша?", "a": "Fireflies.ai обеспечивает хорошую точность транскрипции для большинства языков. Otter.ai традиционно лидирует по точности для английского языка. На акцентах и технической лексике оба могут ошибаться."}]$t36fq$::JSONB WHERE slug = 'fireflies-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t37ci$["✅ Создаёте нативные приложения для iOS и Android — не просто веб-приложения", "✅ Хотите генерировать продакшн-код Flutter/Dart, который можно экспортировать и которым владеете", "✅ Нужна работа в офлайне, нативные функции устройства (камера, GPS, push-уведомления)", "✅ Нужен визуальный конструктор, компилирующийся в настоящий нативный мобильный код"]$t37ci$::JSONB, faq = $t37fq$[{"q": "В чём разница между FlutterFlow и Bubble?", "a": "FlutterFlow создаёт нативные мобильные приложения (iOS и Android) на Flutter — выводит настоящий Flutter-код. Bubble создаёт веб-приложения со сложной логикой и базами данных, доступные через браузер. FlutterFlow — для мобильных, Bubble — для веб-приложений."}, {"q": "Может ли FlutterFlow экспортировать код?", "a": "Да. FlutterFlow может экспортировать готовый к продакшну код Flutter/Dart на GitHub или скачать локально. Можно начать визуально и продолжить разработку в коде — вы не привязаны к платформе."}, {"q": "Bubble хорош для мобильных устройств?", "a": "Bubble создаёт веб-приложения, работающие в мобильных браузерах, но не нативные приложения iOS/Android. Для настоящих нативных мобильных приложений лучше подходят FlutterFlow или React Native. Сила Bubble — логика веб-приложений, а не нативные мобильные функции."}, {"q": "Сколько стоит FlutterFlow?", "a": "Бесплатный план FlutterFlow поддерживает базовые приложения. Standard plan — $30/мес, Pro — $70/мес. Для совместной работы доступен план Teams. Экспорт кода требует платного плана."}]$t37fq$::JSONB WHERE slug = 'flutterflow' AND lang = 'ru';
UPDATE tools SET choose_if = $t38ci$["✅ Нужна open-source модель, которую можно запустить локально или через API", "✅ Хотите бесплатное использование: FLUX.1 [schnell] доступен с открытой лицензией", "✅ Нужен высокий реализм фотографий и точное следование промпту", "✅ Строите продукт и нужна ИИ-генерация изображений через API без ограничений"]$t38ci$::JSONB, faq = $t38fq$[{"q": "Flux vs Midjourney — что лучше?", "a": "Midjourney V7 превосходит по художественному качеству и эстетике. Flux (FLUX.1) превосходит по реализму фотографий, точному следованию тексту в изображении и возможности локального запуска. Выбор зависит от задачи: Midjourney для арта, Flux для реалистичного контента."}, {"q": "Flux бесплатный?", "a": "FLUX.1 [schnell] — самая быстрая версия — доступна бесплатно с открытой лицензией через Hugging Face и ComfyUI. FLUX.1 [dev] — для некоммерческого использования. FLUX.1 [pro] — через API с оплатой за использование."}, {"q": "Можно ли запустить Flux локально?", "a": "Да. Flux (от Black Forest Labs) — open-source модель, которую можно запустить локально через ComfyUI, Automatic1111 или Ollama. Требует мощной видеокарты (минимум 8GB VRAM для schnell)."}, {"q": "Midjourney имеет бесплатный план?", "a": "Нет. Midjourney убрал бесплатный пробный период. Минимальный план Basic — $10/мес (~200 изображений). Flux в версии schnell — бесплатен."}]$t38fq$::JSONB WHERE slug = 'flux' AND lang = 'ru';
UPDATE tools SET choose_if = $t39ci$["✅ Хотите опубликовать полноценный живой сайт — не просто создать графику", "✅ Нужно профессиональное веб-присутствие с собственным доменом, анимациями и CMS", "✅ Нужен ИИ, который создаёт полный сайт из текстового описания для редактирования и публикации", "✅ Вы дизайнер или стартап, создающий лендинг или портфолио, который должен выйти в онлайн"]$t39ci$::JSONB, faq = $t39fq$[{"q": "Что такое Framer AI?", "a": "Framer AI — конструктор сайтов, где вы описываете свой сайт в тексте, и ИИ создаёт полноценный, стилизованный сайт. Затем можно редактировать дизайн визуально, добавлять CMS-контент и публиковать на живой URL с собственным доменом."}, {"q": "Может ли Canva создать сайт?", "a": "У Canva есть базовая функция конструктора сайтов, но она ограничена по сравнению с Framer или Webflow. Сайтам Canva не хватает продвинутых анимаций, функциональности CMS и контроля дизайна. Canva — для графики, Framer — для настоящих сайтов."}, {"q": "Framer AI бесплатный?", "a": "У Framer есть бесплатный план для одного сайта с поддоменом framer.app. Mini plan — $5/мес, Basic — $15/мес, Pro — $30/мес — все с поддержкой собственного домена. Генерация сайта с помощью ИИ включена в бесплатный план."}, {"q": "Framer лучше Webflow?", "a": "Framer быстрее в использовании и имеет лучшую генерацию ИИ. Webflow имеет более продвинутые возможности CMS, более сложную электронную коммерцию и более крупную экосистему фрилансеров. Framer подходит дизайнерам, которые хотят скорости, Webflow — агентствам для сложных клиентских сайтов."}]$t39fq$::JSONB WHERE slug = 'framer-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t40ci$["✅ Создаёте SEO-контент и хотите, чтобы ИИ исследовал, структурировал и оптимизировал статьи в одном рабочем процессе", "✅ Хотите анализировать, что покрывают топ-страницы в выдаче, и быстро создавать лучшие брифы", "✅ Вы контент-маркетолог, которому нужна помощь ИИ при написании наряду с SEO-оптимизацией", "✅ Основная потребность — создание контента и on-page оптимизация, а не полноценная SEO-стратегия"]$t40ci$::JSONB, faq = $t40fq$[{"q": "Что такое Frase IO?", "a": "Frase — SEO-инструмент для контента на базе ИИ, который помогает исследовать, писать и оптимизировать статьи для поиска. Анализирует топ-страницы для целевого ключевого слова, извлекает ключевые темы и помогает создавать брифы и контент, соответствующий поисковому намерению."}, {"q": "SEMrush стоит своих денег?", "a": "Для серьёзных SEO-специалистов и агентств SEMrush за $139-449/мес обычно оправдывает себя. Заменяет несколько отдельных инструментов (исследование ключевых слов, проверка ссылок, аудит сайта, отслеживание позиций). Для малого бизнеса с базовым SEO более дешёвые альтернативы могут быть достаточны."}, {"q": "Может ли Frase заменить SEMrush?", "a": "Нет. Frase фокусируется на оптимизации контента — не делает полного исследования ключевых слов, анализа ссылок или технических SEO-аудитов, как SEMrush. Frase часто используется вместе с SEMrush: SEMrush для стратегии, Frase для создания контента."}, {"q": "Сколько стоит Frase?", "a": "Plan Solo Frase — $15/мес (1 пользователь, 4 статьи/мес). Basic — $45/мес (1 пользователь, 30 статей). Team — $115/мес (3 пользователя, неограниченные статьи). Дополнение Frase Pro ($35/мес) добавляет неограниченное написание ИИ."}]$t40fq$::JSONB WHERE slug = 'frase' AND lang = 'ru';
UPDATE tools SET choose_if = $t41ci$["✅ Нужно создать презентацию, колоду или визуальный документ — не текстовую заметку", "✅ Нужен ИИ для создания полной визуальной презентации из текстового запроса за секунды", "✅ Делитесь работой по живым ссылкам и хотите аналитику просмотров и встроенные медиа", "✅ Результат должен выглядеть как спроектированная презентация, а не текстовый документ"]$t41ci$::JSONB, faq = $t41fq$[{"q": "В чём разница между Gamma и Notion AI?", "a": "Gamma — генератор презентаций: создаёт визуальные слайд-колоды из текстовых запросов. Notion AI — ассистент внутри Notion для написания, суммирования и запросов к документам. Gamma создаёт презентации, Notion AI улучшает ведение заметок и управление знаниями."}, {"q": "Может ли Notion AI создавать презентации?", "a": "Notion AI может создавать структурированные документы и схемы, похожие на контент презентации, но не производит спроектированные слайды или визуальные презентации. Для настоящих презентаций подходят Gamma, Beautiful.ai или Pitch."}, {"q": "Notion AI стоит своих денег?", "a": "Для активных пользователей Notion, которые часто пишут, Notion AI ($10/мес дополнительно) полезен для черновиков, суммирования, перевода и вопросов. Если вам нужен ИИ вне Notion, Claude или ChatGPT предлагают больше гибкости за ту же цену."}, {"q": "Gamma подходит для бизнеса?", "a": "Да. Gamma используется для продажных колод, клиентских презентаций, питчей инвесторам, внутренних отчётов и обучающих материалов. Аналитика просмотров (кто открыл колоду, сколько времени провёл на каждой карточке) особенно полезна для продаж."}]$t41fq$::JSONB WHERE slug = 'gamma' AND lang = 'ru';
UPDATE tools SET choose_if = $t42ci$["✅ Глубоко интегрированы в Google Workspace — Gemini работает внутри Gmail, Docs, Sheets, Slides", "✅ Нужна лучшая интеграция с Google Поиском и актуальная веб-информация", "✅ Используете Android или хотите лучший мобильный ИИ-ассистент в экосистеме Google", "✅ Нужен мультимодальный анализ сложных документов с файлами Google Workspace"]$t42ci$::JSONB, faq = $t42fq$[{"q": "Gemini лучше ChatGPT в 2026 году?", "a": "На задачах Google Workspace Gemini Ultra — лучший выбор. По общим бенчмаркам GPT-4o и Gemini 2.0 Ultra конкурируют. У ChatGPT больше функций (генерация изображений, голос, интерпретатор кода) и более крупная сторонняя экосистема. Gemini побеждает для пользователей Google, ChatGPT — для общего использования."}, {"q": "Gemini бесплатный?", "a": "Да. Gemini бесплатен с доступом к Gemini 1.5 Flash. Google AI Pro ($19.99/мес) открывает Gemini 2.0 Ultra и интеграцию с Google Workspace."}, {"q": "Может ли Gemini генерировать изображения?", "a": "Да. Gemini может генерировать изображения с помощью модели Imagen от Google. Качество конкурентоспособно, но в целом оценивается ниже Midjourney или DALL-E 3 для художественного вывода."}, {"q": "В чём разница между Gemini и Google Bard?", "a": "Bard — исходное название ИИ-чатбота Google, переименованного в Gemini в феврале 2024 года. Это один и тот же продукт — ребрендинг сопровождался значительным улучшением возможностей модели."}]$t42fq$::JSONB WHERE slug = 'gemini' AND lang = 'ru';
UPDATE tools SET choose_if = $t43ci$["✅ Уже используете VS Code, JetBrains или Visual Studio и не хотите переключаться", "✅ Команда использует GitHub для всего — Copilot нативно интегрирован", "✅ Нужны безопасность, соответствие требованиям и функции аудита для корпоративного использования", "✅ Предпочитаете оплату за место в команде с единым опытом во всех редакторах"]$t43ci$::JSONB, faq = $t43fq$[{"q": "Cursor лучше GitHub Copilot?", "a": "Cursor в целом обеспечивает более мощную ИИ-помощь — контекст всей кодовой базы и многофайловое редактирование в Composer мощнее встроенных подсказок Copilot. Но Copilot поддерживает больше IDE и имеет корпоративные функции. Cursor — выбор для индивидуальных разработчиков, которые хотят лучший ИИ-опыт."}, {"q": "Cursor бесплатный?", "a": "Cursor имеет бесплатный план Hobby с ограниченными запросами (2000 дополнений/мес). Plan Pro — $20/мес с неограниченными дополнениями и 500 быстрыми запросами Claude/GPT-4. Business — $40/пользователь/мес."}, {"q": "Cursor использует Claude или GPT-4?", "a": "Cursor поддерживает несколько ИИ-моделей: Claude 3.5 Sonnet, GPT-4o и собственные дообученные модели Cursor. Пользователи Pro могут выбирать модель. Claude 3.5 Sonnet обычно рекомендуется для сложных задач кодирования."}, {"q": "Можно использовать GitHub Copilot и Cursor вместе?", "a": "Да, но они будут значительно перекрываться. Большинство разработчиков выбирают один основной инструмент. Cursor обычно предпочтителен за более мощные функции, а Copilot остаётся для команд с корпоративными рабочими процессами GitHub."}]$t43fq$::JSONB WHERE slug = 'github-copilot' AND lang = 'ru';
UPDATE tools SET choose_if = $t44ci$["✅ Хотите создать простое мобильное приложение из данных, уже находящихся в Google Sheets или Airtable", "✅ Ваш сценарий — директория, портал или внутренний инструмент с простым отображением данных", "✅ Вы нетехнический пользователь, которому нужно приложение за часы, а не недели", "✅ Нужен самый быстрый путь от данных в таблице до работающего мобильного приложения"]$t44ci$::JSONB, faq = $t44fq$[{"q": "Что такое Glide?", "a": "Glide — no-code платформа, которая превращает Google Sheets, Excel или Airtable данные в мобильные приложения. Подключаете таблицу, выбираете макет и получаете рабочее приложение без кода. Предназначена для простых сценариев: директорий, порталов, трекеров инвентаря и внутренних инструментов."}, {"q": "В чём разница между Glide и Bubble?", "a": "Glide быстро превращает таблицы в простые приложения и предназначен для нетехнических пользователей. Bubble — полноценный конструктор no-code веб-приложений, обрабатывающий сложную логику, базы данных и рабочие процессы. Glide быстрее для простых приложений, Bubble мощнее для сложных продуктов."}, {"q": "Glide бесплатный?", "a": "У Glide есть бесплатный план для простых приложений с брендингом Glide и ограниченными функциями. Plan Maker — $49/мес, Team — $99/мес. Бизнес-планы варьируются в зависимости от использования данных и числа пользователей."}, {"q": "Может ли Glide создавать сложные приложения?", "a": "Glide хорошо работает для приложений умеренной сложности — несколько таблиц, роли пользователей, базовая логика. Для SaaS-продуктов, маркетплейсов или приложений со сложной условной логикой Bubble значительно мощнее. Многие пользователи начинают с Glide и переходят на Bubble по мере роста потребностей."}]$t44fq$::JSONB WHERE slug = 'glide' AND lang = 'ru';
UPDATE tools SET choose_if = $t45ci$["✅ Хотите генерировать UI-дизайны из текста или скетча с помощью Gemini", "✅ Нужен инструмент Google для быстрого создания прототипов без регистрации в Figma", "✅ Интегрируетесь с другими инструментами Google Workspace", "✅ Исследуете новые ИИ-инструменты прямо от Google для дизайна интерфейсов"]$t45ci$::JSONB, faq = $t45fq$[{"q": "Что такое Google Stitch?", "a": "Google Stitch — экспериментальный ИИ-инструмент от Google для генерации UI-дизайнов из текстовых описаний или скетчей. Использует Gemini для интерпретации запросов и создания интерфейсов. Доступен в Google Labs как превью-версия."}, {"q": "Google Stitch доступен всем?", "a": "Google Stitch запущен в ограниченном доступе через Google Labs. Полная публичная доступность зависит от этапа развития продукта. Следите за обновлениями на labs.google."}, {"q": "Figma AI или Google Stitch — что зрелее?", "a": "Figma AI значительно зрелее и встроен в производственный рабочий процесс миллионов дизайнеров. Google Stitch — экспериментальный инструмент, находящийся в ранней стадии разработки. Для профессиональных проектов выбирайте Figma AI."}, {"q": "Экспортирует ли Google Stitch в Figma?", "a": "Google Stitch может экспортировать дизайны для дальнейшего редактирования. Конкретные форматы экспорта зависят от текущей версии инструмента, находящегося в активной разработке."}]$t45fq$::JSONB WHERE slug = 'google-stitch' AND lang = 'ru';
UPDATE tools SET choose_if = $t46ci$["✅ Нужно наивысшее качество ИИ-видео с нативной генерацией аудио (диалог, звуковые эффекты, музыка)", "✅ Работаете в экосистеме Google и хотите доступ через Google AI Ultra или Gemini", "✅ Нужен кинематографический реализм с синхронизированным аудио в одном шаге генерации", "✅ Нужна последняя фронтирная видеомодель — Veo 3 лидирует по бенчмаркам качества в 2025 году"]$t46ci$::JSONB, faq = $t46fq$[{"q": "Что такое Google Veo 3?", "a": "Google Veo 3 — последняя модель генерации ИИ-видео от Google, представленная на Google I/O 2025. Создаёт высококачественное видео с синхронизированным нативным аудио — диалогом, фоновыми звуками и музыкой — из текстовых запросов. Доступна через подписку Google AI Ultra и инструмент VideoFX."}, {"q": "Сколько стоит Google Veo 3?", "a": "Veo 3 доступна через Google AI Ultra ($249.99/мес), включающий также последние модели Gemini и Google Workspace AI. Доступ через VideoFX (labs.google/fx) предлагался в ограниченном предварительном просмотре. API-цены для разработчиков отдельные."}, {"q": "Runway Gen-4.5 лучше Veo 3?", "a": "Veo 3 лидирует по общему реализму и нативной генерации аудио. Runway Gen-4.5 занимает первое место на сторонних рейтингах по визуальному качеству и согласованности персонажей. Для производственных рабочих процессов полный набор функций Runway имеет преимущества перед Veo 3 как отдельным генератором."}, {"q": "Может ли Runway генерировать аудио вместе с видео?", "a": "Runway может генерировать видео и имеет некоторые аудиофункции, но нативная синхронизированная генерация аудио — не его основная сила. Одновременная аудиовизуальная генерация Veo 3 (диалог, звуковые эффекты, музыка) более продвинута по состоянию на 2025 год."}]$t46fq$::JSONB WHERE slug = 'google-veo-3' AND lang = 'ru';
UPDATE tools SET choose_if = $t47ci$["✅ Пишете на русском или английском и хотите исправление грамматики, стиля и тона в реальном времени", "✅ Нужно расширение для браузера, работающее в Gmail, Docs, Slack и любом текстовом поле", "✅ Нужны ИИ-переформулировки, определение тона и проверка на плагиат", "✅ Вы студент, писатель или специалист, который пишет ежедневно и хочет стабильного качества"]$t47ci$::JSONB, faq = $t47fq$[{"q": "Может ли DeepL улучшить мои тексты?", "a": "DeepL Write (отдельный инструмент от DeepL Translate) улучшает тексты на английском и немецком, переформулируя предложения для ясности и стиля. Менее комплексен, чем Grammarly для проверки грамматики, но силён в переформулировках."}, {"q": "Grammarly хорош для перевода?", "a": "Grammarly не переводит между языками — работает только с текстами на английском (и базовая проверка для некоторых других языков). Для перевода подходит DeepL."}, {"q": "DeepL бесплатный?", "a": "DeepL предлагает бесплатный план с переводом текста до 5000 символов за запрос и 3 переводами документов в месяц. DeepL Pro начинается от $8.74/мес для неограниченного перевода текста."}, {"q": "Что точнее — DeepL или Google Переводчик?", "a": "DeepL стабильно превосходит Google Переводчик по точности и естественности, особенно для европейских языков. Google Переводчик поддерживает больше языков (100+ против 31 у DeepL), но качество DeepL для поддерживаемых языков выше."}]$t47fq$::JSONB WHERE slug = 'grammarly' AND lang = 'ru';
UPDATE tools SET choose_if = $t48ci$["✅ Активны в X (Twitter) и хотите ИИ, понимающий контекст соцсетей в реальном времени", "✅ Нужны актуальные новости и трендовые темы без ограничения по дате знаний", "✅ Хотите менее цензурированные ответы ИИ — у Grok меньше ограничений контента", "✅ Уже платите за X Premium и хотите ИИ в рамках подписки"]$t48ci$::JSONB, faq = $t48fq$[{"q": "Что такое Grok AI?", "a": "Grok — ИИ-ассистент xAI, встроенный в X (Twitter). Имеет доступ в реальном времени к постам X и трендовым темам, что уникально для разведки в соцсетях. Grok 3 (2025) — фронтирная модель, конкурирующая с GPT-4o по бенчмаркам рассуждений."}, {"q": "Grok бесплатный?", "a": "Grok входит в X Premium ($8/мес) и X Premium+ ($16/мес). Отдельное приложение Grok с расширенными функциями доступно за $30/мес. Полностью бесплатной версии нет."}, {"q": "Grok 3 лучше GPT-4?", "a": "Grok 3 конкурирует с GPT-4o по бенчмаркам рассуждений и математики и лидирует в некоторых задачах STEM. Для общего использования, кодирования и экосистемных функций GPT-4o всё ещё имеет преимущества. Главный дифференциатор Grok — доступ в реальном времени к X/Twitter."}, {"q": "Grok может генерировать изображения?", "a": "Да. Grok включает Aurora — модель генерации изображений. Качество сопоставимо с DALL-E 3. Grok более мягок к ограничениям на изображения по сравнению с другими ИИ-ассистентами."}]$t48fq$::JSONB WHERE slug = 'grok' AND lang = 'ru';
UPDATE tools SET choose_if = $t49ci$["✅ Пишете контент, который должен быть чётким, простым и читаемым — блоги, письма, лендинги", "✅ Хотите исключить наречия, пассивный залог и сложные предложения для более сильного текста", "✅ Нужен редактор без отвлечений, сосредоточенный исключительно на читаемости — без придирок к грамматике", "✅ Вы писатель, уже знающий грамматику и нуждающийся в структурной обратной связи"]$t49ci$::JSONB, faq = $t49fq$[{"q": "Что делает Hemingway Editor?", "a": "Hemingway Editor анализирует ваш текст на читаемость. Выделяет длинные предложения, пассивный залог, сложные слова и лишние наречия — с цветовой кодировкой по серьёзности. Присваивает оценку читаемости по уровню образования. Цель — чёткое, прямое и лёгкое для чтения письмо."}, {"q": "Hemingway Editor бесплатный?", "a": "Hemingway Editor имеет бесплатную веб-версию на hemingwayapp.com. Настольное приложение (Mac/Windows) — единоразовая покупка за $19.99. Подписки нет — платите один раз и используете постоянно."}, {"q": "Grammarly лучше Hemingway?", "a": "Они делают разные вещи. Grammarly проверяет грамматику, орфографию и стиль с подсказками в реальном времени. Hemingway фокусируется на структуре предложений и читаемости. Многие писатели используют оба: Grammarly для правильности, Hemingway для ясности."}, {"q": "Есть ли у Hemingway Editor ИИ-написание?", "a": "Hemingway Editor добавил функции ИИ-написания в 2023 году на базе GPT-4. Можно попросить ИИ переписать выделенные предложения, создать контент или улучшить фрагменты. ИИ — дополнение, основной продукт остаётся анализом читаемости."}]$t49fq$::JSONB WHERE slug = 'hemingway-editor' AND lang = 'ru';
UPDATE tools SET choose_if = $t50ci$["✅ Вы дата-сайентист или аналитик, которому нужны совместные Python и SQL ноутбуки с ИИ-помощью", "✅ Создаёте дата-приложения — интерактивные инструменты, где бизнес-пользователи изучают данные с фильтрами", "✅ Нужна платформа, где дата-команды и бизнес-стейкхолдеры могут работать в одном документе", "✅ Нужен ИИ, пишущий SQL и Python из естественного языка и объясняющий код"]$t50ci$::JSONB, faq = $t50fq$[{"q": "Что такое Hex?", "a": "Hex — коллаборативная дата-платформа, объединяющая SQL-ноутбуки, Python и no-code графики в одном рабочем пространстве. Дата-команды используют её для анализа данных и создания интерактивных дата-приложений. Hex Magic (ИИ) пишет SQL и Python из естественного языка и автоматически генерирует визуализации."}, {"q": "Looker Studio бесплатный?", "a": "Да. Looker Studio (ранее Google Data Studio) полностью бесплатен. Подключается к 800+ источникам данных, включая Google Analytics, BigQuery, Sheets, Ads. Ограничений на дашборды, отчёты или объём данных нет."}, {"q": "В чём разница между Looker Studio и Hex?", "a": "Looker Studio создаёт drag-and-drop визуальные дашборды — инструмент отчётности для бизнес-пользователей. Hex — дата-ноутбук и конструктор приложений для дата-команд, работающих в SQL и Python. Looker Studio — read-only визуальная отчётность, Hex — интерактивный анализ и вычисления."}, {"q": "Сколько стоит Hex?", "a": "У Hex есть бесплатный план для отдельных специалистов с 2 опубликованными приложениями. Plan Team — $24/пользователь/мес. Доступны Pro и Enterprise планы для крупных организаций."}]$t50fq$::JSONB WHERE slug = 'hex' AND lang = 'ru';
UPDATE tools SET choose_if = $t51ci$["✅ Нужен перевод видео с синхронизацией губ — HeyGen переводит видео на 175+ языков с синхронным движением губ", "✅ Создаёте маркетинговый, рекламный или персонализированный видеоконтент в масштабе", "✅ Нужны наиболее естественно выглядящие ИИ-аватары для контента, направленного на потребителей", "✅ Нужны потоковые аватары для взаимодействия с клиентами в реальном времени"]$t51ci$::JSONB, faq = $t51fq$[{"q": "В чём разница между HeyGen и Synthesia?", "a": "HeyGen лидирует по переводу видео (дублированию с синхронизацией губ на 175+ языках) и качеству аватаров. Synthesia лидирует по корпоративным функциям, соответствию требованиям и интеграции LMS для корпоративного обучения. HeyGen — для маркетинга, Synthesia — для L&D-команд."}, {"q": "Может ли HeyGen клонировать мой голос?", "a": "Да. HeyGen может клонировать ваш голос и создать ИИ-аватар, который выглядит и звучит как вы, из короткой записи. Используется для перевода видео — ваш аватар говорит на других языках вашим клонированным голосом."}, {"q": "Synthesia бесплатный?", "a": "Synthesia предлагает бесплатный план с 3 минутами видео в месяц. Платные планы начинаются от $29/мес (Starter, 10 минут) и $89/мес (Creator). Корпоративные цены — индивидуальные."}, {"q": "Сколько стоит HeyGen?", "a": "Plan Creator HeyGen начинается от $29/мес (4 минуты видео). Business — $89/мес (15 минут). Корпоративные цены — индивидуальные. Кредиты для перевода видео продаются отдельно."}]$t51fq$::JSONB WHERE slug = 'heygen' AND lang = 'ru';
UPDATE tools SET choose_if = $t52ci$["✅ Анализируете большие корпоративные документы и нужны точные цитаты с номерами страниц", "✅ Нужна команда аналитиков с общим доступом к документам и историей вопросов", "✅ Хотите интеграцию с корпоративными системами хранения документов", "✅ Нужен более структурированный интерфейс для профессионального анализа документов"]$t52ci$::JSONB, faq = $t52fq$[{"q": "NotebookLM vs Humata — для чего каждый?", "a": "Оба анализируют PDF-документы через ИИ. NotebookLM бесплатен и имеет уникальные функции (аудиообзоры). Humata ориентирован на корпоративное использование с точными цитатами и командным доступом."}, {"q": "NotebookLM полностью бесплатный?", "a": "Да. NotebookLM бесплатен с 50 источниками и 500 чатами на ноутбук. NotebookLM Plus ($19.99/мес) снимает ограничения и добавляет функции для команд."}, {"q": "Сколько стоит Humata?", "a": "Humata предлагает бесплатный план с 60 страницами в месяц. Student — $9.99/мес (200 страниц). Expert — $49/мес (неограниченно). Дороже NotebookLM, но с дополнительными корпоративными функциями."}, {"q": "NotebookLM поддерживает несколько документов?", "a": "Да. В один ноутбук можно добавить до 50 источников: PDF, веб-страницы, YouTube-видео, Google Docs. NotebookLM анализирует все источники вместе и отвечает, опираясь на них."}]$t52fq$::JSONB WHERE slug = 'humata' AND lang = 'ru';
UPDATE tools SET choose_if = $t53ci$["✅ Нужен точный рендеринг текста внутри изображений — логотипы, плакаты, дизайн футболок, типографика", "✅ Создаёте графические дизайн-активы, где разборчивый текст внутри изображения обязателен", "✅ Нужен щедрый бесплатный уровень — Ideogram предлагает бесплатные ежедневные генерации", "✅ Нужна чёткость следования промпту, которая надёжно производит то, что вы описываете"]$t53ci$::JSONB, faq = $t53fq$[{"q": "Что такое Ideogram AI?", "a": "Ideogram — генератор ИИ-изображений, оптимизированный для генерации текста внутри изображений. Превосходит в создании плакатов, логотипов, дизайна футболок и любых изображений, где разборчивый текст — часть визуала. Ideogram 2.0 (2024) также добавил сильный фотореализм."}, {"q": "Midjourney может генерировать текст в изображениях?", "a": "Midjourney V6 добавил улучшенную генерацию текста, но по-прежнему уступает в точности рендеринга текста Ideogram или DALL-E 3. Для изображений, где точность текста критична — знаки, логотипы, этикетки продуктов — Ideogram лучший выбор."}, {"q": "Ideogram бесплатный?", "a": "У Ideogram есть бесплатный план с 10 медленными генерациями в день. Basic plan — $7/мес, Plus — $16/мес, Pro — $48/мес. Бесплатный уровень щедр для периодического использования."}, {"q": "Midjourney лучше DALL-E 3?", "a": "По художественному качеству и эстетической привлекательности большинство пользователей оценивают Midjourney выше DALL-E 3. DALL-E 3 лучше по точности следования промпту и генерации текста. Midjourney V6 лидирует по фотореализму и творческим изображениям, DALL-E 3 — по буквальному следованию сложным описаниям."}]$t53fq$::JSONB WHERE slug = 'ideogram' AND lang = 'ru';
UPDATE tools SET choose_if = $t54ci$["✅ Управляете командой контент-маркетинга и нужен контроль голоса бренда во всём ИИ-выводе", "✅ Создаёте длинный контент — публикации в блогах, белые книги — с последовательным стилем бренда", "✅ Нужны корпоративные функции: права пользователей, командная совместная работа и SSO", "✅ Качество и согласованность бренда важнее стоимости для вашей организации"]$t54ci$::JSONB, faq = $t54fq$[{"q": "Jasper AI стоит своих денег в 2026 году?", "a": "Jasper стоит того для команд контента из 3+ человек, где критична согласованность бренда. Обучение голосу бренда и командные функции оправдывают более высокую цену. Для отдельных создателей Claude, ChatGPT или Writesonic предлагают сопоставимое качество написания по более низкой цене."}, {"q": "Для чего используется Writesonic?", "a": "Writesonic — ИИ-контент-платформа для маркетологов и бизнеса. Генерирует публикации в блогах, рекламные тексты, описания товаров и лендинги. Chatsonic (его чатбот) имеет доступ к Google Поиску для актуальной информации. Также генерирует ИИ-изображения через Photosonic."}, {"q": "Writesonic бесплатный?", "a": "У Writesonic есть бесплатный пробный период с 25 кредитами. Individual plan начинается от $16/мес, Small Team — $45/мес. Корпоративные планы — индивидуальные. В целом дешевле Jasper при сопоставимых функциях."}, {"q": "Есть ли у Jasper SEO-инструменты?", "a": "Jasper интегрируется с Surfer SEO для оптимизации контента. Эта комбинация — Jasper для написания, Surfer для оптимизации — популярна среди команд контент-маркетинга. Jasper сам по себе не включает SEO-анализ, Surfer нужно добавлять отдельно."}]$t54fq$::JSONB WHERE slug = 'jasper' AND lang = 'ru';
UPDATE tools SET choose_if = $t55ci$["✅ Хотите загрузить CSV или подключить данные и задавать вопросы на понятном языке для мгновенных ответов", "✅ Нужен анализ данных по запросу без построения и поддержки дашборда", "✅ Вы бизнес-пользователь, который хочет, чтобы ИИ выполнял анализ и объяснял результаты", "✅ Нужен статистический анализ, прогнозирование или преобразование данных через разговор"]$t55ci$::JSONB, faq = $t55fq$[{"q": "Что такое Julius AI?", "a": "Julius AI — инструмент разговорного анализа данных. Загружаете CSV-файлы, подключаете базы данных или Google Sheets, затем задаёте вопросы на обычном языке. Julius пишет и запускает анализ, генерирует графики и объясняет результаты на простом языке — без SQL или кода."}, {"q": "Julius AI бесплатный?", "a": "У Julius AI есть бесплатный план с ограниченным количеством сообщений в месяц. Plan Pro — $28/мес для неограниченных сообщений и расширенных функций. Предназначен для отдельных специалистов и небольших команд, регулярно анализирующих данные."}, {"q": "В чём разница между Julius AI и ChatGPT для данных?", "a": "Julius AI специально создан для анализа данных с постоянными загрузками файлов, выполнением кода и генерацией графиков, оптимизированными для задач с данными. ChatGPT с инструментом анализа данных делает аналогичные вещи, но более универсально. У Julius более чистый UX, ориентированный на данные."}, {"q": "Может ли Looker Studio анализировать данные с ИИ?", "a": "Looker Studio — инструмент визуализации и дашбордов: отображает данные, но не выполняет ИИ-анализ и не отвечает на вопросы естественного языка. Google добавляет ИИ-функции в Looker (корпоративный продукт), но сам Looker Studio в основном является инструментом отчётности без разговорного ИИ."}]$t55fq$::JSONB WHERE slug = 'julius-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t56ci$["✅ Нужна помощь по нескольким академическим предметам — не только математика, но и наука, история, письмо", "✅ Нужен сократовский репетитор, который направляет к ответу вопросами, а не просто решает задачу", "✅ Вы учитель, которому нужны ИИ-инструменты для планирования уроков, обратной связи и работы со студентами", "✅ Занимаетесь с учебной программой Khan Academy и хотите ИИ, интегрированный в эти уроки"]$t56ci$::JSONB, faq = $t56fq$[{"q": "Что такое Khanmigo?", "a": "Khanmigo — ИИ-репетитор Khan Academy на базе GPT-4. Использует сократовский метод — задаёт наводящие вопросы, а не даёт ответы — для понимания концепций студентами. Охватывает математику, естественные науки, историю и гуманитарные предметы. Бесплатен для студентов в США."}, {"q": "Photomath бесплатный?", "a": "Photomath бесплатен для базовых пошаговых решений. Photomath Plus ($9.99/мес или $69.99/год) добавляет анимированные видеообъяснения, несколько методов решения и доступ к эксперту по математике."}, {"q": "Khanmigo бесплатный?", "a": "Khanmigo бесплатен для студентов в США через Khan Academy. Для международных пользователей требуется пожертвование $4+/мес. Школы и районы могут получить доступ через программы Khan Academy для районов."}, {"q": "Может ли Photomath решать задачи со словами?", "a": "Да. Photomath может решать текстовые задачи — можно вводить или фотографировать текстовые математические задачи, а не только уравнения. Обрабатывает текстовые алгебраические задачи, но сложные многошаговые задачи на рассуждение могут потребовать более способного ИИ."}]$t56fq$::JSONB WHERE slug = 'khanmigo' AND lang = 'ru';
UPDATE tools SET choose_if = $t57ci$["✅ Нужен самый щедрый бесплатный уровень — 66 ежедневных кредитов для генерации видео бесплатно", "✅ Нужен нативный вывод 4K с покадровым управлением через раскадровку", "✅ Нужна встроенная генерация аудио с синхронизацией губ в одном пайплайне", "✅ Важен бюджет — Kling Pro начинается от $6.99/мес против $15/мес у Runway"]$t57ci$::JSONB, faq = $t57fq$[{"q": "Kling AI лучше Runway в 2026 году?", "a": "Зависит от приоритетов. Runway Gen-4.5 лидирует по качеству бенчмаркам и предлагает многомодельную подписку. Kling 3.0 предлагает лучшую ценность — больше бесплатных кредитов, нативное 4K и более низкую цену. Для профессионалов — Runway, для соотношения цена/качество — Kling."}, {"q": "Можно использовать Kling AI бесплатно?", "a": "Да. Kling AI предлагает 66 бесплатных кредитов ежедневно — самый щедрый бесплатный уровень среди качественных генераторов ИИ-видео. Бесплатный пробный период Runway даёт 125 одноразовых кредитов без обновления."}, {"q": "Что такое Runway Gen-4.5?", "a": "Runway Gen-4.5 — последняя видеомодель Runway, занимающая первое место в рейтингах text-to-video по состоянию на 2025 год. Доступна на всех платных планах Runway, а подписка также включает Veo 3.1, Kling 3.0, Seedance и FLUX."}, {"q": "Kling AI поддерживает 4K?", "a": "Да. Kling 3.0 (февраль 2026 года) поддерживает нативный вывод 4K с инструментом раскадровки для покадрового управления камерой и встроенной генерацией аудио с синхронизацией губ."}]$t57fq$::JSONB WHERE slug = 'kling-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t58ci$["✅ Фокусируетесь на фундаментальном анализе — доходы, финансовые коэффициенты, тенденции выручки и метрики компаний", "✅ Нужен Bloomberg-альтернативный терминал для фундаментальных данных за долю стоимости", "✅ Исследуете акции для долгосрочного инвестирования и нужны отчёты о доходах, балансы и денежные потоки", "✅ Нужны ИИ-сводки звонков о доходах и анализ финансовых документов"]$t58ci$::JSONB, faq = $t58fq$[{"q": "В чём разница между Koyfin и TradingView?", "a": "Koyfin — платформа фундаментального анализа: финансовые данные, доходы, метрики и исследования компаний. TradingView — платформа технического анализа и графиков: ценовые графики, индикаторы и торговое сообщество. Инвесторы используют Koyfin для фундаментального исследования, активные трейдеры — TradingView."}, {"q": "Koyfin бесплатный?", "a": "У Koyfin есть бесплатный план с ограниченным доступом к данным. Plan Plus — $19/мес, Pro — $59/мес. Значительно дешевле Bloomberg ($24 000/год) при охвате большинства потребностей индивидуальных инвесторов."}, {"q": "TradingView бесплатный?", "a": "У TradingView есть щедрый бесплатный план с до 3 индикаторами на графике и ограниченными оповещениями. Essential plan — $14.95/мес, Plus — $29.95/мес, Premium — $59.95/мес для большего числа индикаторов, оповещений и данных."}, {"q": "Можно ли использовать и Koyfin, и TradingView?", "a": "Многие инвесторы используют оба: Koyfin для фундаментального исследования (доходы, финансовые метрики, сравнение аналогов) и TradingView для технического анализа (ценовые графики, выбор точек входа/выхода). Они дополняют друг друга для инвесторов, учитывающих как фундаментальные, так и технические факторы."}]$t58fq$::JSONB WHERE slug = 'koyfin' AND lang = 'ru';
UPDATE tools SET choose_if = $t59ci$["✅ Нужна генерация изображений в реальном времени — рисуете, ИИ мгновенно дорабатывает", "✅ Хотите улучшить качество существующих изображений или фотографий", "✅ Нужна обучаемая персонализация стиля под ваш бренд или эстетику", "✅ Хотите бесплатный план с реальными возможностями для регулярного использования"]$t59ci$::JSONB, faq = $t59fq$[{"q": "Krea AI vs Midjourney — в чём разница?", "a": "Krea AI предлагает уникальную генерацию в реальном времени и усиление изображений. Midjourney V7 превосходит по художественному качеству и эстетике финальных результатов. Krea — для интерактивного процесса, Midjourney — для лучших результатов."}, {"q": "Krea AI бесплатный?", "a": "Да. Krea AI предлагает бесплатный план с ограниченными генерациями в реальном времени. Starter — $24/мес, Pro — $96/мес для профессиональных объёмов."}, {"q": "Что такое генерация в реальном времени в Krea?", "a": "Real-time generation — уникальная функция Krea: рисуете скетч или перемещаете слайдер, и ИИ мгновенно обновляет изображение. Это делает итерацию значительно быстрее, чем ожидание каждой генерации в Midjourney."}, {"q": "Krea AI улучшает существующие фотографии?", "a": "Да. Krea AI Enhance увеличивает разрешение и улучшает детализацию существующих изображений и фотографий с помощью ИИ. Это одна из ключевых функций платформы наряду с генерацией в реальном времени."}]$t59fq$::JSONB WHERE slug = 'krea-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t60ci$["✅ Создаёте игровые активы, персонажей или концепт-арт, требующие согласованности в множестве изображений", "✅ Хотите дообучать модели на собственных изображениях для последовательного стиля и персонажей", "✅ Нужны встроенные инструменты: редактор холста, удаление фона и генерация image-to-image", "✅ Нужен более щедрый бесплатный уровень — Leonardo предлагает 150 бесплатных токенов в день"]$t60ci$::JSONB, faq = $t60fq$[{"q": "Для чего используется Leonardo.ai?", "a": "Leonardo.ai — платформа генерации ИИ-изображений, популярная среди разработчиков игр, концепт-художников и дизайнеров. Предлагает дообучение на кастомных наборах изображений, редактор холста, генерацию движения и функции эталонных персонажей для поддержания согласованности в серии изображений."}, {"q": "Leonardo AI бесплатный?", "a": "У Leonardo.ai есть бесплатный план со 150 токенами в день (примерно 30 стандартных изображений). Членство Apprentice — $12/мес, Artisan — $30/мес, Maestro — $60/мес — с большим числом токенов и приоритетной генерацией."}, {"q": "Leonardo.ai лучше Stable Diffusion?", "a": "Leonardo.ai построен поверх Stable Diffusion, но добавляет кураторский платформенный опыт, дообученные модели, лучший UI и функции сообщества. Для пользователей, не желающих настраивать локальный Stable Diffusion, Leonardo предлагает аналогичные возможности с гораздо меньшей технической настройкой."}, {"q": "Что лучше для игровых активов — Leonardo или Midjourney?", "a": "Leonardo.ai в целом предпочтителен для производства игровых активов. Возможности дообучения обеспечивают согласованность персонажей и стилей в нескольких изображениях. Midjourney производит более качественные отдельные изображения, но не имеет дообучения для поддержания согласованной визуальной идентичности проекта."}]$t60fq$::JSONB WHERE slug = 'leonardo-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t61ci$["✅ Нужен личный ИИ-ассистент, автономно управляющий вашей электронной почтой, календарём и исследовательскими задачами", "✅ Создаёте ИИ-агентов для конкретных личных и бизнес-рабочих процессов без корпоративных требований Microsoft", "✅ Нужна подготовка встреч, составление писем и обновление CRM в автоматическом режиме", "✅ Нужны гибкие ИИ-агенты, подключающиеся к 5000+ приложений без привязки к Microsoft"]$t61ci$::JSONB, faq = $t61fq$[{"q": "Что такое Lindy AI?", "a": "Lindy — платформа ИИ-ассистентов, создающая личных и бизнес-агентов. Агенты могут управлять электронной почтой, подготавливать встречи, обновлять CRM, проводить исследования и обрабатывать клиентскую поддержку. Подключаете Lindy к своим приложениям (Gmail, Slack, Salesforce) и определяете рабочие процессы."}, {"q": "Lindy AI бесплатный?", "a": "У Lindy есть бесплатный план с 400 задачами в месяц. Платные планы начинаются от $49.99/мес для 5000 задач. Планы Teams и Enterprise предлагают более высокие лимиты задач и многопользовательские функции."}, {"q": "В чём разница между Lindy и Zapier?", "a": "Zapier автоматизирует фиксированные, основанные на правилах рабочие процессы между приложениями. Lindy использует ИИ для обработки переменных ситуаций — чтения писем, принятия решений, контекстного ответа. Zapier лучше для предсказуемой автоматизации, Lindy — когда задачи требуют суждения и естественного языка."}, {"q": "Copilot Studio — то же самое, что Microsoft Copilot?", "a": "Нет. Microsoft Copilot — ИИ-ассистент, встроенный в Windows и Microsoft 365. Copilot Studio — отдельная no-code платформа для создания кастомных ИИ-чатботов и агентов. Copilot Studio позволяет создать собственный Copilot для конкретных бизнес-сценариев."}]$t61fq$::JSONB WHERE slug = 'lindy' AND lang = 'ru';
UPDATE tools SET choose_if = $t62ci$["✅ Нужен полный пакет фирменного стиля: логотип, цветовая палитра, шрифты и руководство по бренду", "✅ Открываете бизнес и хотите профессиональный логотип от ИИ за несколько минут", "✅ Нужен логотип в векторных форматах (SVG, EPS) для печати и использования в большом масштабе", "✅ Нужны соответствующие брендовые активы: визитки, шаблоны для соцсетей, подписи для писем"]$t62ci$::JSONB, faq = $t62fq$[{"q": "Что такое Looka?", "a": "Looka — ИИ-сервис создания логотипов и фирменного стиля. Введите название компании и предпочтения, и Looka создаст десятки вариантов логотипов с помощью ИИ. Вы настраиваете выбранный логотип и скачиваете брендовые активы, включая векторные файлы, коды цветов и шрифты."}, {"q": "Looka бесплатный?", "a": "Looka позволяет генерировать и просматривать логотипы бесплатно. Для скачивания файлов высокого разрешения нужно платить: за один логотип ($65 базовый пакет) или подписка Brand Kit ($96/год) для постоянного доступа ко всем брендовым активам."}, {"q": "Может ли Canva создать профессиональный логотип?", "a": "Конструктор логотипов Canva может создавать логотипы с помощью ИИ, но для полноценного профессионального фирменного стиля с векторными файлами и руководством Looka более специализирован. Логотипы Canva подходят для простых случаев, Looka лучше, когда нужен полный брендовый пакет."}, {"q": "Логотип Looka уникален?", "a": "Looka генерирует логотипы с помощью шаблонов и ИИ-комбинирования, поэтому они не разрабатываются с нуля. Есть небольшой риск сходства с другими компаниями, использующими Looka. Для по-настоящему уникального логотипа рекомендуется дизайнер-человек. Для большинства малых предприятий результаты Looka достаточно профессиональны."}]$t62fq$::JSONB WHERE slug = 'looka' AND lang = 'ru';
UPDATE tools SET choose_if = $t63ci$["✅ Нужны бесплатные общедоступные дашборды, подключённые к Google Analytics, Ads, BigQuery или Sheets", "✅ Вы небольшая команда или одиночка, которая не может позволить себе корпоративные BI-цены", "✅ Создаёте клиентские отчёты, которыми нужно делиться без необходимости создавать аккаунт", "✅ Работаете преимущественно с данными Google и хотите нативную, бесшовную интеграцию"]$t63ci$::JSONB, faq = $t63fq$[{"q": "Looker Studio бесплатный?", "a": "Да. Looker Studio полностью бесплатен без ограничений на дашборды, отчёты или объём данных. Подключается к 800+ источникам данных. Есть платные функции Looker Studio Pro для корпоративного управления, но основной продукт бесплатен."}, {"q": "Сколько стоит Tableau?", "a": "Tableau Viewer — $15/пользователь/мес, Explorer — $42/пользователь/мес, Creator — $75/пользователь/мес. Корпоративные цены варьируются. Tableau значительно дороже альтернатив, но широко считается золотым стандартом для сложной корпоративной аналитики."}, {"q": "Looker Studio так же мощен, как Tableau?", "a": "Для большинства задач бизнес-отчётности Looker Studio достаточен. Tableau имеет преимущества для очень больших наборов данных, сложных вычислений, продвинутого статистического анализа и корпоративного управления. Looker Studio хорошо справляется с обычными BI-дашбордами, Tableau — для продвинутых дата-команд."}, {"q": "Что такое Tableau AI?", "a": "Tableau AI относится к функциям Einstein AI, встроенным в Tableau: запросы на естественном языке, ИИ-генерируемые инсайты и автоматическое обнаружение аномалий. Эти функции требуют лицензирования Tableau+ или Tableau с Salesforce Einstein."}]$t63fq$::JSONB WHERE slug = 'looker-studio' AND lang = 'ru';
UPDATE tools SET choose_if = $t64ci$["✅ Хотите описать приложение на обычном языке и мгновенно получить рабочий код ИИ", "✅ Вы разработчик или технический основатель, желающий выпускать MVP значительно быстрее", "✅ Нужно владение чистым React-кодом, который можно экспортировать и продолжать разрабатывать", "✅ Нужна тесная интеграция с GitHub и ИИ, итерирующий вашу кодовую базу"]$t64ci$::JSONB, faq = $t64fq$[{"q": "Что такое Lovable?", "a": "Lovable (ранее GPT Engineer) — конструктор ИИ-приложений, где вы описываете желаемое и он генерирует полноценное веб-приложение на React/TypeScript. В отличие от no-code инструментов, производит реальный код. Разработчики могут редактировать код напрямую или продолжать общаться с ИИ для внесения изменений."}, {"q": "Lovable бесплатный?", "a": "У Lovable есть бесплатный план с 5 сообщениями в день. Starter — $20/мес для 100 сообщений, Launch — $50/мес для 250, Scale — $100/мес для 500. Сообщения расходуются при генерации или изменении кода."}, {"q": "Lovable лучше Bubble для не-разработчиков?", "a": "Bubble в целом лучше для не-разработчиков, желающих создавать без написания кода. Lovable генерирует реальный код, который, несмотря на впечатляющий вид, может требовать знания разработчика для отладки и поддержки. Для нетехнических основателей визуальный редактор Bubble доступнее."}, {"q": "Может ли Lovable создавать full-stack приложения?", "a": "Да. Lovable может подключаться к Supabase для базы данных и авторизации, генерируя full-stack приложения с React-фронтендом и PostgreSQL-бэкендом. Популярен для быстрого создания SaaS-прототипов и MVP."}]$t64fq$::JSONB WHERE slug = 'lovable' AND lang = 'ru';
UPDATE tools SET choose_if = $t65ci$["✅ Нужен щедрый бесплатный уровень для генерации ИИ-видео — Dream Machine предлагает бесплатные ежедневные кредиты", "✅ Нужно плавное, физически точное движение и плавные движения камеры в созданном видео", "✅ Создаёте анимации image-to-video и хотите высококачественные результаты по низкой цене", "✅ Экспериментируете с ИИ-видео и хотите попробовать без платных обязательств"]$t65ci$::JSONB, faq = $t65fq$[{"q": "Что такое Luma Dream Machine?", "a": "Dream Machine — генератор text-to-video и image-to-video от Luma AI. Известен плавным, физически реалистичным движением. Бесплатный уровень позволяет ежедневно генерировать видео. Luma AI также создаёт Genie (3D-генерация) и строит ИИ-инфраструктуру для других продуктов."}, {"q": "Luma AI бесплатный?", "a": "У Luma Dream Machine есть бесплатный план с ограниченным числом генераций в месяц. Standard plan — $29.99/мес для большего числа генераций и более быстрой обработки. Pro — $99.99/мес для высокообъёмного использования."}, {"q": "Dream Machine лучше Sora?", "a": "Sora (OpenAI) и Dream Machine нацелены на разные сильные стороны. Sora производит более длинные, сложные видео с лучшей сюжетной связностью. Dream Machine производит отличные короткие клипы с плавным движением по более низкой цене и с бесплатным уровнем. Runway Gen-4.5 в целом считается текущим лидером по качеству."}, {"q": "Для чего профессионально используется Runway?", "a": "Runway используется кинематографистами, VFX-художниками и видеоредакторами для генерации ИИ-видео, удаления фона, видео-inpainting, ротоскопирования и отслеживания движения. Студии Universal и Paramount использовали инструменты Runway в производстве. Это профессиональный выбор в ИИ-видео."}]$t65fq$::JSONB WHERE slug = 'luma-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t66ci$["✅ Нужна визуальная автоматизация между сотнями разных SaaS-сервисов без ограничений Microsoft", "✅ Хотите создавать сложные сценарии с ветвлением, циклами и обработкой ошибок", "✅ Нужна доступная цена — Make значительно дешевле корпоративных планов Copilot Studio", "✅ Работаете с маркетинговыми или операционными процессами вне экосистемы Microsoft"]$t66ci$::JSONB, faq = $t66fq$[{"q": "Make и Microsoft Copilot Studio — одно и то же?", "a": "Нет, это совершенно разные инструменты. Make (бывший Integromat) — платформа автоматизации рабочих процессов между SaaS-сервисами. Copilot Studio — конструктор чат-ботов и ИИ-агентов от Microsoft. Make автоматизирует процессы, Copilot Studio строит разговорных агентов."}, {"q": "Make дешевле Copilot Studio?", "a": "Да. Make начинается от $9/мес (10 000 операций). Copilot Studio стоит от $200/мес за 25 000 сообщений и требует Microsoft 365 для полной интеграции. Make значительно доступнее для малого бизнеса."}, {"q": "Можно ли использовать Make с Microsoft?", "a": "Да. Make интегрируется с Microsoft 365, Teams, Outlook и SharePoint через готовые коннекторы. Для базовой автоматизации Microsoft-процессов Make работает хорошо. Copilot Studio нужен для разговорных интерфейсов."}, {"q": "Что выбрать между Make и Copilot Studio?", "a": "Make — если нужна автоматизация бизнес-процессов (данные из формы → CRM → уведомление). Copilot Studio — если нужен чат-бот или ИИ-агент в Teams/SharePoint. Это разные задачи."}]$t66fq$::JSONB WHERE slug = 'make' AND lang = 'ru';
UPDATE tools SET choose_if = $t67ci$["✅ Нужен автономный ИИ-агент, который выполняет полные задачи от вашего имени — не просто отвечает на вопросы", "✅ Нужен ИИ, который может просматривать веб, писать код и независимо выполнять многошаговые планы", "✅ Работаете над исследованием, анализом или автоматизацией задач, требующей независимого принятия решений", "✅ Нужен универсальный агентный ИИ, а не чатбот для конкретной платформы"]$t67ci$::JSONB, faq = $t67fq$[{"q": "Что такое Microsoft Copilot Studio?", "a": "Copilot Studio — платформа Microsoft без кода для создания кастомных ИИ-чатботов и агентов. Интегрируется с Microsoft 365, Teams, SharePoint и Power Platform. Организации используют её для создания HR-ботов, агентов клиентского сервиса и внутренних помощников по знаниям."}, {"q": "Что такое Manus AI?", "a": "Manus — автономный ИИ-агент, разработанный в Китае, который может независимо выполнять сложные задачи: просматривать веб, писать код, управлять файлами и реализовывать многошаговые планы. В отличие от чатботов, Manus совершает действия, а не просто отвечает на вопросы."}, {"q": "Copilot Studio бесплатный?", "a": "Copilot Studio требует подписки Microsoft 365. Включает 25 000 генеративных сообщений ИИ в месяц на тенант на платных планах. Доступны дополнительные пакеты сообщений. Модель ценообразования сложная — свяжитесь с Microsoft для корпоративного ценообразования."}, {"q": "Может ли Manus заменить человеческий труд?", "a": "Manus может автоматизировать многие рабочие процессы исследований, анализа и выполнения задач, ранее требовавшие человеческих усилий. Однако он лучше всего работает для чётко определённых задач с ясными целями. Сложные суждения, деликатные решения и творческая работа по-прежнему выигрывают от человеческого контроля."}]$t67fq$::JSONB WHERE slug = 'manus' AND lang = 'ru';
UPDATE tools SET choose_if = $t68ci$["✅ Используете WhatsApp, Instagram или Facebook и хотите ИИ-ассистента прямо там", "✅ Нужен бесплатный ИИ без лимитов — Meta AI работает на Llama 4 и доступен без подписки", "✅ Хотите генерацию изображений бесплатно через интерфейс социальных сетей", "✅ Нужен быстрый ответ внутри мессенджера без открытия отдельного приложения"]$t68ci$::JSONB, faq = $t68fq$[{"q": "Что такое Meta AI?", "a": "Meta AI — бесплатный ИИ-ассистент от Meta, встроенный в WhatsApp, Instagram, Facebook и Messenger. Работает на модели Llama 4. Позволяет отвечать на вопросы, генерировать изображения и помогать с задачами прямо в социальных сетях."}, {"q": "Meta AI бесплатный?", "a": "Да. Meta AI полностью бесплатен и доступен в WhatsApp, Instagram и Facebook без регистрации дополнительных аккаунтов."}, {"q": "Meta AI лучше ChatGPT?", "a": "ChatGPT значительно мощнее как самостоятельный инструмент — более продвинутые рассуждения, широкий набор функций и постоянная память. Meta AI выигрывает по удобству доступа: он прямо в WhatsApp, не нужно переключаться между приложениями."}, {"q": "Какая модель стоит за Meta AI?", "a": "Meta AI работает на Llama 4 — флагманской open-source модели Meta. Llama 4 поддерживает контекстное окно до 10 млн токенов и мультимодальность. Отдельные версии Llama 4 доступны для самостоятельного развёртывания."}]$t68fq$::JSONB WHERE slug = 'meta-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t69ci$["✅ Вы используете Microsoft 365 — Copilot встроен в Word, Excel, Teams, Outlook", "✅ Работаете в корпоративной среде с требованиями безопасности и соблюдения нормативов", "✅ Нужен ИИ-ассистент прямо в браузере Edge без дополнительных подписок", "✅ Хотите анализировать документы и электронные таблицы без переключения приложений"]$t69ci$::JSONB, faq = $t69fq$[{"q": "В чём разница между Microsoft Copilot и ChatGPT?", "a": "Microsoft Copilot встроен в экосистему Microsoft 365 (Word, Excel, Teams) и работает на основе GPT. ChatGPT — автономный продукт OpenAI с более широким набором функций: GPTs, Deep Research, Sora, Canvas. Copilot — выбор для корпоративных пользователей Microsoft, ChatGPT — для универсальных задач."}, {"q": "Microsoft Copilot бесплатный?", "a": "Microsoft Copilot доступен бесплатно через браузер Edge и сайт copilot.microsoft.com. Copilot Pro ($20/мес) добавляет приоритетный доступ к GPT-4o и интеграцию с Microsoft 365 приложениями."}, {"q": "Какой ИИ использует Microsoft Copilot?", "a": "Microsoft Copilot работает на основе моделей OpenAI, включая GPT-4o. Microsoft является крупным инвестором OpenAI и имеет эксклюзивный доступ к их технологиям для интеграции в продукты."}, {"q": "Лучше ли ChatGPT, чем Microsoft Copilot?", "a": "ChatGPT предлагает больше функций и более свежие возможности (Deep Research, Sora, Memory). Copilot выигрывает у пользователей Microsoft 365 благодаря глубокой интеграции в привычные приложения. Для корпоративного использования с Microsoft — Copilot, для универсальных задач — ChatGPT."}]$t69fq$::JSONB WHERE slug = 'microsoft-copilot' AND lang = 'ru';
UPDATE tools SET choose_if = $t70ci$["✅ Создаёте кастомные ИИ-чатботы для Microsoft Teams, SharePoint или корпоративных порталов", "✅ Организация работает на Microsoft 365 и нужен ИИ внутри существующих рабочих процессов", "✅ Нужен конструктор чатботов без кода с коннекторами Power Platform и соответствием требованиям", "✅ Нужно корпоративное управление: SSO, хранение данных, журналы аудита"]$t70ci$::JSONB, faq = $t70fq$[{"q": "Что такое Microsoft Copilot Studio?", "a": "Copilot Studio — платформа Microsoft без кода для создания кастомных ИИ-чатботов и агентов. Интегрируется с Microsoft 365, Teams, SharePoint и Power Platform. Организации используют её для создания HR-ботов, агентов клиентского сервиса и внутренних помощников по знаниям."}, {"q": "Что такое Manus AI?", "a": "Manus — автономный ИИ-агент, разработанный в Китае, который может независимо выполнять сложные задачи: просматривать веб, писать код, управлять файлами и реализовывать многошаговые планы. В отличие от чатботов, Manus совершает действия, а не просто отвечает на вопросы."}, {"q": "Copilot Studio бесплатный?", "a": "Copilot Studio требует подписки Microsoft 365. Включает 25 000 генеративных сообщений ИИ в месяц на тенант на платных планах. Доступны дополнительные пакеты сообщений. Модель ценообразования сложная — свяжитесь с Microsoft для корпоративного ценообразования."}, {"q": "Может ли Manus заменить человеческий труд?", "a": "Manus может автоматизировать многие рабочие процессы исследований, анализа и выполнения задач, ранее требовавшие человеческих усилий. Однако он лучше всего работает для чётко определённых задач с ясными целями. Сложные суждения, деликатные решения и творческая работа по-прежнему выигрывают от человеческого контроля."}]$t70fq$::JSONB WHERE slug = 'microsoft-copilot-studio' AND lang = 'ru';
UPDATE tools SET choose_if = $t71ci$["✅ Хотите максимально высокое художественное качество изображений с фирменной эстетикой Midjourney", "✅ Нужно активное сообщество, база промптов и культура /imagine", "✅ Создаёте концепт-арт, иллюстрации или визуальный контент для творческих проектов", "✅ Хотите стабильно высокое качество с минимальным количеством неудачных результатов"]$t71ci$::JSONB, faq = $t71fq$[{"q": "Flux vs Midjourney — что лучше?", "a": "Midjourney V7 превосходит по художественному качеству и эстетике. Flux (FLUX.1) превосходит по реализму фотографий, точному следованию тексту в изображении и возможности локального запуска. Выбор зависит от задачи: Midjourney для арта, Flux для реалистичного контента."}, {"q": "Flux бесплатный?", "a": "FLUX.1 [schnell] — самая быстрая версия — доступна бесплатно с открытой лицензией через Hugging Face и ComfyUI. FLUX.1 [dev] — для некоммерческого использования. FLUX.1 [pro] — через API с оплатой за использование."}, {"q": "Можно ли запустить Flux локально?", "a": "Да. Flux (от Black Forest Labs) — open-source модель, которую можно запустить локально через ComfyUI, Automatic1111 или Ollama. Требует мощной видеокарты (минимум 8GB VRAM для schnell)."}, {"q": "Midjourney имеет бесплатный план?", "a": "Нет. Midjourney убрал бесплатный пробный период. Минимальный план Basic — $10/мес (~200 изображений). Flux в версии schnell — бесплатен."}]$t71fq$::JSONB WHERE slug = 'midjourney' AND lang = 'ru';
UPDATE tools SET choose_if = $t72ci$["✅ Работаете с документами на европейских языках — Le Chat оптимизирован для них", "✅ Хотите европейский ИИ-ассистент с хранением данных в ЕС и соответствием GDPR", "✅ Нужна быстрая обработка больших документов — Mistral предлагает огромное контекстное окно", "✅ Используете open-source модели — модели Mistral можно развернуть локально"]$t72ci$::JSONB, faq = $t72fq$[{"q": "Что такое Mistral Le Chat?", "a": "Le Chat — бесплатный ИИ-ассистент от французской компании Mistral AI. Работает на собственных моделях Mistral (Mistral Large, Mixtral). Позиционируется как европейская альтернатива ChatGPT с акцентом на конфиденциальность и работу с европейскими языками."}, {"q": "Le Chat бесплатный?", "a": "Да, базовый Le Chat бесплатен. Pro-план ($19.99/мес) добавляет расширенный доступ, больший контекст и приоритетную обработку."}, {"q": "Mistral лучше ChatGPT?", "a": "По большинству бенчмарков ChatGPT (GPT-5.5) превосходит Mistral. Однако Mistral сильнее в работе с европейскими языками и соответствии нормам ЕС о конфиденциальности данных. Для пользователей в ЕС Le Chat — серьёзная альтернатива."}, {"q": "Можно ли использовать модели Mistral локально?", "a": "Да. Mistral публикует большинство своих моделей с открытым исходным кодом — их можно запустить локально через Ollama, LM Studio или через API. Это главное преимущество перед ChatGPT, который полностью закрыт."}]$t72fq$::JSONB WHERE slug = 'mistral-le-chat' AND lang = 'ru';
UPDATE tools SET choose_if = $t73ci$["✅ Хотите полное ИИ-планирование дня: Motion автоматически расставляет задачи в календаре", "✅ Управляете проектами и задачами в одном инструменте с ИИ-расстановкой приоритетов", "✅ Нужен план-менеджер + умный календарь в одном — без переключения инструментов", "✅ Хотите перепланирование задач в реальном времени при изменении расписания"]$t73ci$::JSONB, faq = $t73fq$[{"q": "Motion vs Reclaim.ai — в чём разница?", "a": "Motion — ИИ-планировщик задач и проектов: управляет задачами и автоматически планирует их в календаре. Reclaim.ai — умный помощник по расписанию: защищает время для важных дел в Google Календаре. Motion сложнее и дороже, Reclaim — проще и доступнее."}, {"q": "Motion стоит своих денег?", "a": "Motion стоит $34/мес (ежемесячно) или $19/мес (ежегодно). Пользователи, которым Motion подходит, отмечают значительный рост продуктивности. Для фрилансеров и специалистов с большим количеством задач — обоснованная инвестиция."}, {"q": "Reclaim.ai бесплатный?", "a": "Да. Reclaim.ai предлагает бесплатный план для 1 пользователя с базовой автоматизацией. Starter — $8/мес, Business — $12/мес. Motion не имеет бесплатного плана."}, {"q": "Работает ли Motion с Google Календарём?", "a": "Да. Motion интегрируется с Google Календарём и Outlook. Он читает существующие события и планирует задачи вокруг них. Reclaim.ai также работает с Google Календарём."}]$t73fq$::JSONB WHERE slug = 'motion' AND lang = 'ru';
UPDATE tools SET choose_if = $t74ci$["✅ Создаёте курсы электронного обучения, объясняющие видео или корпоративные тренинги с озвучкой", "✅ Нужен интерфейс студийного типа со встроенным видеоредактором для аватаров с синхронизацией губ", "✅ Нужны последовательные профессиональные голоса, оптимизированные для презентационного контента", "✅ Нужна командная совместная работа и несколько пользователей на одном аккаунте"]$t74ci$::JSONB, faq = $t74fq$[{"q": "ElevenLabs лучше Murf?", "a": "ElevenLabs производит более качественные, естественно звучащие голоса и имеет превосходное клонирование голоса. Murf лучше для электронного обучения и презентационных озвучек с интегрированной синхронизацией видео и командными функциями."}, {"q": "ElevenLabs может клонировать мой голос?", "a": "Да. ElevenLabs может клонировать ваш голос всего из 1 минуты чистой аудиозаписи. Мгновенное клонирование голоса доступно на плане Starter ($5/мес). Высококачественное клонирование требует плана Creator ($22/мес)."}, {"q": "Сколько стоит Murf AI?", "a": "Murf предлагает бесплатный план с 10 минутами генерации голоса. Plan Creator — $29/мес (2 часа/мес), Business — $99/мес (8 часов/мес), Enterprise — индивидуальные цены."}, {"q": "Какие языки поддерживает ElevenLabs?", "a": "ElevenLabs поддерживает 32+ языка, включая английский, испанский, французский, немецкий, хинди, арабский, китайский, японский и другие. Качество голоса варьируется в зависимости от языка — английский и основные европейские языки звучат наиболее естественно."}]$t74fq$::JSONB WHERE slug = 'murf-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t75ci$["✅ Технический пользователь, которому нужны гибкие рабочие процессы с полным контролем над логикой", "✅ Хотите self-hosted решение — n8n можно развернуть на собственном сервере", "✅ Нужна интеграция с сотнями сервисов без привязки к экосистеме Microsoft", "✅ Open-source подход важен — n8n Community Edition доступен бесплатно"]$t75ci$::JSONB, faq = $t75fq$[{"q": "Что такое n8n?", "a": "n8n — open-source платформа автоматизации рабочих процессов с визуальным редактором. Поддерживает 400+ интеграций, может работать self-hosted или в облаке. Позиционируется как мощная альтернатива Zapier/Make для технических пользователей."}, {"q": "n8n бесплатный?", "a": "n8n Community Edition полностью бесплатен при self-hosted установке. Облачный план от $24/мес. Microsoft Copilot Studio входит в Microsoft 365 или стоит от $200/мес за 25K сообщений."}, {"q": "В чём разница n8n и Copilot Studio?", "a": "n8n — универсальная платформа автоматизации для технических пользователей с акцентом на кастомные интеграции. Copilot Studio — конструктор корпоративных чат-ботов и агентов, глубоко интегрированный в Microsoft 365. Разные задачи."}, {"q": "n8n сложнее Zapier?", "a": "n8n требует больше технических знаний, чем Zapier, но предлагает значительно больше гибкости: JavaScript-код в узлах, self-hosting, сложная условная логика. Для разработчиков — мощный выбор."}]$t75fq$::JSONB WHERE slug = 'n8n' AND lang = 'ru';
UPDATE tools SET choose_if = $t76ci$["✅ Нужен простой инструмент для быстрой генерации изображений без сложных настроек", "✅ Хотите лёгкое введение в ИИ-генерацию без большого выбора параметров", "✅ Нужен базовый инструмент с минимальным порогом входа", "✅ Хотите быстро попробовать генерацию без регистрации сложных аккаунтов"]$t76ci$::JSONB, faq = $t76fq$[{"q": "Что такое Nano Banana?", "a": "Nano Banana — упрощённый ИИ-генератор изображений, ориентированный на простоту и доступность. Менее известен, чем крупные платформы, и предлагает базовые возможности генерации без сложной настройки."}, {"q": "Leonardo AI бесплатный?", "a": "Да. Leonardo AI предлагает бесплатный план с 150 токенами в день (~30 изображений). Aperion — $12/мес, Maestro — $30/мес. Это один из щедрейших бесплатных планов среди профессиональных генераторов."}, {"q": "Leonardo AI подходит для игровых ассетов?", "a": "Да, Leonardo AI особенно популярен в игровой индустрии. Платформа включает специализированные модели для персонажей, предметов, текстур и окружения. Функция 3D Texture Generation позволяет текстурировать 3D-модели."}, {"q": "Leonardo AI vs Midjourney — что выбрать?", "a": "Leonardo AI превосходит для игровых ассетов, LoRA-обучения и технического контента. Midjourney V7 лидирует по художественной эстетике. Leonardo AI щедрее в бесплатных кредитах. Для игровых разработчиков — Leonardo, для художников — Midjourney."}]$t76fq$::JSONB WHERE slug = 'nano-banana' AND lang = 'ru';
UPDATE tools SET choose_if = $t77ci$["✅ Нужен анализ ваших собственных документов — PDF, статей, заметок", "✅ Хотите ИИ, который понимает только ваши источники без внешней информации", "✅ Генерируете аудиообзоры (Audio Overview) из загруженных материалов", "✅ Организуете исследования — собираете источники и задаёте вопросы по ним"]$t77ci$::JSONB, faq = $t77fq$[{"q": "Perplexity vs NotebookLM — в чём разница?", "a": "Perplexity ищет в интернете и возвращает ответы со свежими источниками. NotebookLM анализирует только ваши загруженные документы. Perplexity для поиска информации, NotebookLM для анализа своих материалов."}, {"q": "NotebookLM бесплатный?", "a": "Да. NotebookLM бесплатен с неограниченными ноутбуками. NotebookLM Plus ($19.99/мес) добавляет больше аудиообзоров и приоритетный доступ. Perplexity бесплатен с 5 Pro-поисками в день; Perplexity Pro — $20/мес."}, {"q": "Что такое Audio Overview в NotebookLM?", "a": "NotebookLM может превращать загруженные документы в аудио-подкаст формата «два ведущих обсуждают тему». Это уникальная функция для изучения материалов в удобном формате."}, {"q": "Перплексити точнее Гугла?", "a": "Perplexity приводит источники для каждого утверждения, что упрощает проверку. Но как любой ИИ, он может ошибаться или галлюцинировать. Используйте для исследований, проверяйте критически важные факты."}]$t77fq$::JSONB WHERE slug = 'notebooklm' AND lang = 'ru';
UPDATE tools SET choose_if = $t78ci$["✅ Живёте в Notion и хотите ИИ-помощь с написанием, суммированием и вопросами по документам", "✅ Хотите задавать вопросы по всему рабочему пространству Notion с помощью ИИ", "✅ Создаёте письменный контент — заметки, документы, вики — и хотите ИИ для улучшения, перевода или суммирования", "✅ Опытный пользователь Notion, которому нужен ИИ, понимающий существующую базу знаний"]$t78ci$::JSONB, faq = $t78fq$[{"q": "В чём разница между Notion AI и Zapier AI?", "a": "Notion AI — ИИ-ассистент внутри Notion для создания и улучшения контента в вашем рабочем пространстве. Zapier AI ориентирован на автоматизацию — он использует ИИ для улучшения автоматизации рабочих процессов между приложениями. Notion AI — для работы со знаниями, Zapier AI — для автоматизации процессов."}, {"q": "Notion AI стоит своих денег?", "a": "Для активных пользователей Notion, которые регулярно пишут, Notion AI ($10/мес дополнительно) полезен для суммирования, перевода, переписывания и вопросов по документам. Если вам нужен ИИ-ассистент вне Notion, Claude или ChatGPT предлагают сопоставимые возможности за ту же цену."}, {"q": "Может ли Zapier AI заменить разработчика?", "a": "Zapier AI может автоматизировать многие задачи, ранее требовавшие участия разработчика: извлечение данных, классификацию и преобразование. Однако сложная кастомная логика по-прежнему требует программирования. Zapier AI снижает, но не устраняет потребность в технических ресурсах."}, {"q": "Есть ли у Notion автоматизация?", "a": "В Notion есть базовые встроенные автоматизации (триггеры кнопок, автоматизации баз данных). Для сложных межприложных рабочих процессов используйте Zapier или Make с интеграцией Notion. Notion AI обрабатывает контент, Zapier — внешние подключения к приложениям."}]$t78fq$::JSONB WHERE slug = 'notion-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t79ci$["✅ Хотите open-source ИИ-агент для кодирования в терминале с возможностью выбора модели", "✅ Нужен бесплатный агент, поддерживающий Claude, GPT, Gemini и другие модели", "✅ Хотите прозрачность: весь код открыт, можно изучить и модифицировать", "✅ Нужен легковесный терминальный агент без проприетарной привязки"]$t79ci$::JSONB, faq = $t79fq$[{"q": "OpenCode vs Claude Code — в чём разница?", "a": "Claude Code — официальный агент кодирования от Anthropic, работающий исключительно на Claude. OpenCode — open-source альтернатива с поддержкой множества провайдеров. Claude Code более отполирован, OpenCode более гибкий."}, {"q": "OpenCode бесплатный?", "a": "OpenCode как инструмент — бесплатный open-source. Оплачиваются только API-токены выбранной модели. Claude Code требует подписку на Anthropic (Max $100 или $200/мес) или API-ключ."}, {"q": "Claude Code лучше OpenCode?", "a": "Claude Code имеет преимущество благодаря прямому доступу к API Anthropic и глубокой оптимизации для моделей Claude. OpenCode предлагает гибкость выбора модели и полную прозрачность открытого кода."}, {"q": "Как установить OpenCode?", "a": "OpenCode устанавливается через npm: `npm install -g opencode-ai`. Требует Node.js и API-ключи выбранных провайдеров. Claude Code устанавливается через `npm install -g @anthropic-ai/claude-code`."}]$t79fq$::JSONB WHERE slug = 'opencode' AND lang = 'ru';
UPDATE tools SET choose_if = $t80ci$["✅ Нужна точная транскрипция встреч в реальном времени с разделением по спикерам", "✅ Работаете в Zoom, Google Meet или Teams и хотите автоматические конспекты встреч", "✅ Нужна интеграция с Salesforce или HubSpot для записи встреч по продажам в CRM", "✅ Хотите ИИ-чат с вашими транскрипциями — задавайте вопросы по записанным встречам"]$t80ci$::JSONB, faq = $t80fq$[{"q": "Otter.ai vs Fireflies.ai — в чём разница?", "a": "Оба транскрибируют встречи, но с разными акцентами. Otter.ai известен высокой точностью транскрипции в реальном времени и интеграцией с Salesforce. Fireflies.ai предлагает более широкую языковую поддержку, аналитику разговоров и больше CRM-интеграций."}, {"q": "Otter.ai бесплатный?", "a": "Да. Otter.ai предлагает бесплатный план с 600 минутами транскрипции в месяц и 3 импортами. Pro — $17/мес. Fireflies.ai также имеет бесплатный план с ограниченным хранилищем транскрипций."}, {"q": "Работает ли Otter.ai в Google Meet?", "a": "Да. Otter.ai интегрируется с Google Meet, Zoom и Teams. Автоматически входит в запланированные встречи и начинает транскрипцию."}, {"q": "Точность Fireflies.ai хороша?", "a": "Fireflies.ai обеспечивает хорошую точность транскрипции для большинства языков. Otter.ai традиционно лидирует по точности для английского языка. На акцентах и технической лексике оба могут ошибаться."}]$t80fq$::JSONB WHERE slug = 'otter-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t81ci$["✅ Нужен ИИ-поисковик с реальными источниками и свежими данными из интернета", "✅ Исследуете актуальные темы и хотите факты с ссылками на источники", "✅ Нужен Deep Research — глубокий анализ темы с десятками источников", "✅ Хотите быстрые ответы на вопросы без загрузки своих документов"]$t81ci$::JSONB, faq = $t81fq$[{"q": "Perplexity vs NotebookLM — в чём разница?", "a": "Perplexity ищет в интернете и возвращает ответы со свежими источниками. NotebookLM анализирует только ваши загруженные документы. Perplexity для поиска информации, NotebookLM для анализа своих материалов."}, {"q": "NotebookLM бесплатный?", "a": "Да. NotebookLM бесплатен с неограниченными ноутбуками. NotebookLM Plus ($19.99/мес) добавляет больше аудиообзоров и приоритетный доступ. Perplexity бесплатен с 5 Pro-поисками в день; Perplexity Pro — $20/мес."}, {"q": "Что такое Audio Overview в NotebookLM?", "a": "NotebookLM может превращать загруженные документы в аудио-подкаст формата «два ведущих обсуждают тему». Это уникальная функция для изучения материалов в удобном формате."}, {"q": "Перплексити точнее Гугла?", "a": "Perplexity приводит источники для каждого утверждения, что упрощает проверку. Но как любой ИИ, он может ошибаться или галлюцинировать. Используйте для исследований, проверяйте критически важные факты."}]$t81fq$::JSONB WHERE slug = 'perplexity' AND lang = 'ru';
UPDATE tools SET choose_if = $t82ci$["✅ Нужна немедленная помощь с математическими задачами: сфотографировал — получил решение с объяснением", "✅ Школьник или студент, которому нужна помощь с алгеброй, геометрией или математическим анализом", "✅ Хотите пошаговые объяснения математических решений, а не просто ответ", "✅ Нужен бесплатный инструмент для математики без подписки"]$t82ci$::JSONB, faq = $t82fq$[{"q": "Photomath vs Duolingo Max — это разные инструменты?", "a": "Да, полностью разные. Photomath — решатель математических задач по фото. Duolingo Max — премиум-уровень языкового приложения с ИИ. Photomath для математики, Duolingo для языков."}, {"q": "Photomath бесплатный?", "a": "Photomath бесплатен с базовыми решениями. Photomath Plus ($9.99/мес или $59.99/год) добавляет анимированные пошаговые объяснения. Duolingo Max — $30/мес или $168/год."}, {"q": "Duolingo Max стоит своих денег?", "a": "Duolingo Max добавляет Roleplay (ролевые сценарии с ИИ) и Explain My Answer (объяснения ошибок). Для серьёзного изучения языка — хорошее дополнение. Базовый Duolingo бесплатен и эффективен для начального уровня."}, {"q": "Что точнее — Photomath или ChatGPT для математики?", "a": "Оба хороши, но по-разному. Photomath специализируется на математике и пошаговых решениях — очень точен для школьного уровня. ChatGPT охватывает более широкий математический контекст, но может ошибаться в сложных задачах."}]$t82fq$::JSONB WHERE slug = 'photomath' AND lang = 'ru';
UPDATE tools SET choose_if = $t83ci$["✅ Нужно быстрое редактирование видео с помощью ИИ: добавление эффектов, анимация фотографий", "✅ Хотите простой интерфейс для быстрого создания коротких клипов из изображений", "✅ Нужна интеграция с соцсетями и упрощённый рабочий процесс публикации", "✅ Создаёте динамичный контент с эффектами Pika (Pikaffects) для TikTok/Instagram"]$t83ci$::JSONB, faq = $t83fq$[{"q": "Pika vs Kling AI — что лучше?", "a": "Kling AI 3.0 генерирует более реалистичное движение и поддерживает нативный 4K. Pika 2.5 проще в использовании и имеет уникальные эффекты (Pikaffects). Для профессионального качества — Kling, для простоты и творческих эффектов — Pika."}, {"q": "Pika бесплатный?", "a": "Pika предлагает бесплатный план с ограниченными генерациями. Pika Standard — $8/мес. Kling AI также имеет бесплатный уровень с 66 ежедневными кредитами — это щедрее, чем у многих конкурентов."}, {"q": "Какое видео длиннее генерирует Kling?", "a": "Kling AI 3.0 может генерировать клипы до 3 минут — это намного больше, чем большинство конкурентов (Runway и Pika: 4–10 секунд). Для длинных нарративных видео Kling превосходит конкурентов."}, {"q": "Почему Kling AI популярен?", "a": "Kling AI от китайской компании Kuaishou привлёк внимание благодаря высокому реализму движений и щедрому бесплатному плану. Kling 3.0 поддерживает 4K, длинные клипы и точное управление камерой по конкурентной цене."}]$t83fq$::JSONB WHERE slug = 'pika' AND lang = 'ru';
UPDATE tools SET choose_if = $t84ci$["✅ Команда совместно создаёт презентации в реальном времени — у Pitch лучший коллаборативный редактор", "✅ Питчуете инвесторов или клиентов и нужны профессиональные шаблоны с аналитикой вовлечённости зрителей", "✅ Нужны видеокомментарии и асинхронная обратная связь прямо на слайдах", "✅ Нужно управление брендом с заблокированными шаблонами для поддержания визуальной согласованности"]$t84ci$::JSONB, faq = $t84fq$[{"q": "Gamma подходит для питчей инвесторам?", "a": "Gamma может быстро создавать визуально привлекательные колоды для инвесторов, а обмен ссылками с аналитикой полезен. Однако профессиональные шаблоны Pitch, командная совместная работа и более детальная аналитика зрителей (время на слайде) делают его лучше для высокоставочных питчей."}, {"q": "Pitch бесплатный?", "a": "У Pitch есть бесплатный план для неограниченных колод с базовой совместной работой. Plan Pro — $25/мес для расширенной аналитики, собственных доменов и премиальных шаблонов. Бизнес-планы начинаются от $100/мес для крупных команд."}, {"q": "Есть ли у Gamma функции совместной работы?", "a": "Gamma поддерживает базовую совместную работу — общий доступ и комментарии. Однако совместное редактирование в реальном времени, как в Google Slides или Pitch, более ограничено. Для команд, активно совместно создающих презентации, Pitch предлагает более полноценный коллаборативный опыт."}, {"q": "Для чего используется Pitch?", "a": "Pitch — коллаборативная платформа презентаций для команд. Используется для питчей инвесторам, продажных колод, клиентских презентаций и корпоративных всеобщих собраний. Ключевые дифференциаторы: совместное редактирование в реальном времени, аналитика зрителей и видеообмен сообщениями на слайдах."}]$t84fq$::JSONB WHERE slug = 'pitch' AND lang = 'ru';
UPDATE tools SET choose_if = $t85ci$["✅ Нужна более высокая скорость генерации для рабочих процессов преобразования текста в речь с высоким объёмом", "✅ Нужен более доступный план для базовой генерации голоса без продвинутого клонирования", "✅ Создаёте подкасты и хотите встроенный хостинг подкастов", "✅ Нужны голоса потоковой передачи с сверхнизкой задержкой для разговорных ИИ-приложений в реальном времени"]$t85ci$::JSONB, faq = $t85fq$[{"q": "ElevenLabs лучше Play.ht?", "a": "ElevenLabs в целом производит более качественные и естественно звучащие голоса, а также превосходит по клонированию голоса. Play.ht предлагает более быструю генерацию и более низкие цены для базовых сценариев использования. Для работ, критичных к качеству, ElevenLabs лидирует."}, {"q": "Play.ht бесплатный?", "a": "Play.ht предлагает бесплатный план с 12 500 символами в месяц (примерно 10 минут аудио). Plan Creator начинается от $31.20/мес, Unlimited — от $49.50/мес. Корпоративные цены — индивидуальные."}, {"q": "Play.ht может клонировать голоса?", "a": "Да. Play.ht имеет функцию Instant Voice Clone, которая создаёт клон голоса из аудиосэмпла. Качество хорошее, но в целом оценивается ниже ElevenLabs по естественности на коротких образцах."}, {"q": "Для чего используется ElevenLabs?", "a": "ElevenLabs используется для ИИ-озвучки, озвучивания аудиокниг, производства подкастов, дублирования видео, клонирования голоса и создания голосовых ИИ-приложений. Его API широко используется разработчиками для создания разговорных продуктов с ИИ."}]$t85fq$::JSONB WHERE slug = 'playht' AND lang = 'ru';
UPDATE tools SET choose_if = $t86ci$["✅ Нужны нелинейные масштабируемые презентации, которые рассказывают визуальную историю иначе, чем слайды", "✅ Презентуете вживую и хотите кинетический эффект масштабирования для вовлечения аудитории", "✅ Есть существующие презентации Prezi и нужно работать в этом формате", "✅ Нужен стиль презентации, который явно выделяется среди стандартных слайд-колод"]$t86ci$::JSONB, faq = $t86fq$[{"q": "Prezi всё ещё актуален в 2026 году?", "a": "Prezi всё ещё используется и добавил ИИ-функции. Однако стиль масштабируемых презентаций стал менее модным, и более новые инструменты, такие как Gamma, превзошли его по качеству ИИ-генерации и современному дизайну. Главный отличительный признак Prezi — уникальный нелинейный формат."}, {"q": "Есть ли у Prezi ИИ?", "a": "Да. Prezi AI (запущен в 2023 году) может генерировать презентации из запросов и преобразовывать документы в презентации. Качество ИИ улучшилось, но в целом считается ниже Gamma по качеству дизайна."}, {"q": "Gamma бесплатный?", "a": "У Gamma есть бесплатный план с 400 кредитами ИИ — достаточно для нескольких полных презентаций. Plus — $10/мес, Pro — $20/мес для неограниченной генерации, аналитики и собственных доменов."}, {"q": "Что случилось с Prezi?", "a": "Prezi остаётся активным и прибыльным, но снизился с пика популярности 2012-2016 годов. Pivot к Prezi Video (презентация с наложениями на видеозвонках) и Prezi Design, добавлены ИИ-функции. По-прежнему имеет миллионы пользователей, особенно в образовании."}]$t86fq$::JSONB WHERE slug = 'prezi' AND lang = 'ru';
UPDATE tools SET choose_if = $t87ci$["✅ Нужен перефразировщик: хотите переписать текст с другим тоном или стилем", "✅ Пишете академические работы и нужен инструмент для парафраза без плагиата", "✅ Хотите суммаризатор и генератор цитат — QuillBot включает их в одном месте", "✅ Нужен бесплатный инструмент с достаточным функционалом без подписки"]$t87ci$::JSONB, faq = $t87fq$[{"q": "В чём разница QuillBot и Grammarly?", "a": "QuillBot специализируется на перефразировании — переписывает готовый текст с другим стилем. Grammarly фокусируется на проверке грамматики и улучшении написанного текста в реальном времени. QuillBot меняет то, что уже написано, Grammarly помогает писать правильно с первого раза."}, {"q": "QuillBot бесплатный?", "a": "Да. QuillBot предлагает бесплатный план с базовым перефразированием (ограниченные режимы) и суммаризатором. Premium ($9.95/мес) открывает все режимы, быстрее и без лимитов. Grammarly также бесплатен с базовой проверкой."}, {"q": "QuillBot хорош для академических работ?", "a": "Да, QuillBot популярен среди студентов для парафраза источников и перефразирования собственных текстов. Включает генератор цитат (APA, MLA). Однако злоупотребление перефразированием для обхода проверки на плагиат нарушает академические правила."}, {"q": "Можно ли использовать QuillBot и Grammarly вместе?", "a": "Да, и многие так делают: сначала пишут и проверяют в Grammarly, затем перефразируют части в QuillBot. Оба доступны как расширения браузера."}]$t87fq$::JSONB WHERE slug = 'quillbot' AND lang = 'ru';
UPDATE tools SET choose_if = $t88ci$["✅ Хотите защитить время для фокусной работы, привычек и встреч в Google Календаре", "✅ Нужна умная группировка встреч и автоматическая расстановка буферного времени", "✅ Нужна интеграция с Asana, Linear или Jira для синхронизации задач с календарём", "✅ Хотите более дешёвый инструмент — Reclaim.ai значительно доступнее Motion"]$t88ci$::JSONB, faq = $t88fq$[{"q": "Motion vs Reclaim.ai — в чём разница?", "a": "Motion — ИИ-планировщик задач и проектов: управляет задачами и автоматически планирует их в календаре. Reclaim.ai — умный помощник по расписанию: защищает время для важных дел в Google Календаре. Motion сложнее и дороже, Reclaim — проще и доступнее."}, {"q": "Motion стоит своих денег?", "a": "Motion стоит $34/мес (ежемесячно) или $19/мес (ежегодно). Пользователи, которым Motion подходит, отмечают значительный рост продуктивности. Для фрилансеров и специалистов с большим количеством задач — обоснованная инвестиция."}, {"q": "Reclaim.ai бесплатный?", "a": "Да. Reclaim.ai предлагает бесплатный план для 1 пользователя с базовой автоматизацией. Starter — $8/мес, Business — $12/мес. Motion не имеет бесплатного плана."}, {"q": "Работает ли Motion с Google Календарём?", "a": "Да. Motion интегрируется с Google Календарём и Outlook. Он читает существующие события и планирует задачи вокруг них. Reclaim.ai также работает с Google Календарём."}]$t88fq$::JSONB WHERE slug = 'reclaim-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t89ci$["✅ Нужна профессиональная генерация векторной графики, иконок и SVG из промпта", "✅ Создаёте брендинговые материалы с точным текстом и узнаваемым стилем", "✅ Нужны нативные SVG-файлы, а не растровые изображения в векторном виде", "✅ Хотите обучить платформу своему бренд-стилю для последовательного визуала"]$t89ci$::JSONB, faq = $t89fq$[{"q": "Recraft vs Canva — в чём разница?", "a": "Recraft специализируется на генерации векторной графики и брендинговых ассетов с поддержкой SVG. Canva — универсальный дизайн-инструмент с широким набором шаблонов и ИИ-функций для маркетинга. Recraft для профессионального визуала, Canva для всего остального."}, {"q": "Recraft бесплатный?", "a": "Recraft предлагает бесплатный план со 100 генерациями при регистрации. Pro — $20/мес. Canva бесплатен с базовыми функциями; Canva Pro — $15/мес."}, {"q": "Canva может генерировать векторную графику?", "a": "Canva Magic Media генерирует изображения, но в растровом формате (PNG, JPEG). Recraft создаёт настоящие SVG-файлы с путями. Для масштабируемой векторной графики нужен Recraft или Illustrator с Firefly."}, {"q": "Recraft подходит для логотипов?", "a": "Да. Recraft особенно силён в логотипах и иконках — нативная генерация SVG делает его лучше Midjourney для брендинга. Однако для сложных логотипов финальная доработка дизайнером по-прежнему рекомендуется."}]$t89fq$::JSONB WHERE slug = 'recraft' AND lang = 'ru';
UPDATE tools SET choose_if = $t90ci$["✅ Создаёте векторную графику, иконки и брендинговые материалы с нативной SVG-генерацией", "✅ Нужна точная типографика в изображениях — Recraft лидирует в рендеринге текста", "✅ Работаете над брендингом и нужен согласованный визуальный стиль через брендовый набор", "✅ Нужен бесплатный план с достаточным функционалом для регулярной работы"]$t90ci$::JSONB, faq = $t90fq$[{"q": "Что такое Recraft AI?", "a": "Recraft AI — генератор изображений, специализирующийся на векторной графике, иконках и брендинге. Уникальная особенность — нативная генерация SVG и точный рендеринг текста. Recraft V3 занял первое место в рейтинге text-to-image на Hugging Face Spaces в конце 2024 года."}, {"q": "Recraft лучше Midjourney для брендинга?", "a": "Для брендинга — да. Recraft генерирует настоящие SVG-файлы, точно рендерит текст и поддерживает брендовые стили. Midjourney лучше для художественных иллюстраций и концепт-арта. Для логотипов и иконок Recraft выигрывает."}, {"q": "Recraft AI бесплатный?", "a": "Да. Recraft предлагает бесплатный план со 100 генерациями при регистрации. Pro — $20/мес с неограниченной генерацией и дополнительными функциями."}, {"q": "Recraft поддерживает векторную графику?", "a": "Да, это главное отличие Recraft. Он может генерировать настоящие SVG-файлы с путями — а не просто растровые изображения, похожие на векторную графику. Это крайне полезно для иконок, логотипов и масштабируемых брендинговых материалов."}]$t90fq$::JSONB WHERE slug = 'recraft-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t91ci$["✅ Хотите создать ИИ-агентов и автономные рабочие процессы без привязки к Microsoft", "✅ Нужны агенты для исследования, написания контента, обработки лидов — не чат-боты", "✅ Хотите собственную команду ИИ-агентов с распределением задач между ними", "✅ Нужен инструмент с гибким набором инструментов для агентов: браузер, код, API"]$t91ci$::JSONB, faq = $t91fq$[{"q": "Что такое Relevance AI?", "a": "Relevance AI — платформа для создания ИИ-агентов и автономных рабочих процессов. Позволяет создавать агентов, которые выполняют задачи самостоятельно: исследуют данные, обрабатывают лиды, пишут контент. Ориентирована на отделы маркетинга, продаж и операций."}, {"q": "Relevance AI или Copilot Studio — что проще?", "a": "Оба инструмента ориентированы на no-code/low-code. Relevance AI проще для создания агентов общего назначения. Copilot Studio проще для корпоративных пользователей Microsoft, уже знакомых с Power Platform."}, {"q": "Сколько стоит Relevance AI?", "a": "Relevance AI предлагает бесплатный план с ограниченными кредитами. Платные планы от $19/мес для малого бизнеса до корпоративных тарифов. Microsoft Copilot Studio — от $200/мес за 25K сообщений."}, {"q": "Чем агенты Relevance AI отличаются от Copilot Studio?", "a": "Агенты Relevance AI автономны — они самостоятельно планируют и выполняют многоэтапные задачи (исследование + анализ + написание). Copilot Studio строит реактивных чат-ботов, которые отвечают на вопросы пользователей. Фундаментально разные архитектуры."}]$t91fq$::JSONB WHERE slug = 'relevance-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t92ci$["✅ Разрабатываете сайты на Webflow и нужны готовые компоненты, wireframes и sitemap", "✅ Веб-дизайнер, которому нужна библиотека компонентов + ИИ-генерация структуры сайта", "✅ Нужен быстрый способ создать полную структуру сайта из одного промпта", "✅ Хотите работать с Webflow/Figma — Relume интегрируется с обеими платформами"]$t92ci$::JSONB, faq = $t92fq$[{"q": "Relume vs Framer — в чём разница?", "a": "Relume — библиотека компонентов и инструмент wireframing для дизайнеров Webflow и Figma. Framer — полноценный конструктор сайтов с хостингом и ИИ-генерацией. Relume помогает проектировать, Framer помогает строить и публиковать."}, {"q": "Relume бесплатный?", "a": "Relume предлагает бесплатный план с ограниченным доступом к компонентам. Pro — $38/мес. Framer бесплатен для базовых сайтов с ограниченными страницами; платные планы от $15/мес."}, {"q": "С чем интегрируется Relume?", "a": "Relume экспортирует в Webflow (клонирование компонентов) и Figma (копирование UI-элементов). Это делает его полезным дополнением для дизайнеров, работающих на этих платформах."}, {"q": "Можно ли создать производственный сайт во Framer?", "a": "Да. Framer — полноценная платформа для создания сайтов с хостингом. Многие маркетинговые и портфолио-сайты работают на Framer. Для сложных веб-приложений он менее подходит, чем Webflow или кастомная разработка."}]$t92fq$::JSONB WHERE slug = 'relume' AND lang = 'ru';
UPDATE tools SET choose_if = $t93ci$["✅ Нужно быстро удалить фон с одного или нескольких изображений — специализированный инструмент точнее", "✅ Хотите API для массового удаления фона в своём приложении или рабочем процессе", "✅ Нужна максимальная точность на сложных объектах: волосы, мех, прозрачные объекты", "✅ Нужен быстрый результат без регистрации и создания дизайна"]$t93ci$::JSONB, faq = $t93fq$[{"q": "Remove.bg vs Canva — что точнее?", "a": "Remove.bg специализируется исключительно на удалении фона и, как правило, точнее на сложных объектах (волосы, мех). Canva Magic Eraser отлично работает для стандартных объектов и удобен как часть полного дизайн-процесса."}, {"q": "Remove.bg бесплатный?", "a": "Remove.bg бесплатен для просмотра результата в уменьшенном разрешении. Скачивание в полном разрешении — от $0.22 за изображение или подписка от $9/мес. Canva Pro ($15/мес) включает неограниченное удаление фона."}, {"q": "Есть ли API у Remove.bg?", "a": "Да. Remove.bg предлагает API для разработчиков — интеграция в приложения, e-commerce платформы и автоматизированные рабочие процессы. Canva не предоставляет публичный API для функций обработки изображений."}, {"q": "Canva умеет удалять фон?", "a": "Да. Canva Pro включает функцию Background Remover с одним кликом. Для большинства стандартных задач (продуктовые фото, портреты) качество достаточное. Для сложных случаев Remove.bg даёт лучший результат."}]$t93fq$::JSONB WHERE slug = 'remove-bg' AND lang = 'ru';
UPDATE tools SET choose_if = $t94ci$["✅ Нужна полная облачная IDE — кодируйте, запускайте и публикуйте прямо в браузере", "✅ Новичок в программировании и хотите среду разработки без установки чего-либо", "✅ Создаёте прототипы и хотите поделиться живым URL сразу после сборки", "✅ Нужен ИИ-агент (Replit Agent), который пишет и разворачивает приложение по описанию задачи"]$t94ci$::JSONB, faq = $t94fq$[{"q": "Что такое Replit?", "a": "Replit — облачная IDE с ИИ-функциями, включая Replit Agent (создаёт приложения из описания) и автодополнение кода. Не требует установки — код пишется, запускается и публикуется прямо в браузере. Особенно популярен среди студентов и прототипирования."}, {"q": "Replit бесплатный?", "a": "Replit предлагает бесплатный план для базового использования. Replit Core ($25/мес) добавляет расширенный ИИ, больше ресурсов и возможность публикации приложений. GitHub Copilot стоит $10/мес для индивидуальных разработчиков."}, {"q": "Replit или GitHub Copilot — что лучше для начинающих?", "a": "Replit значительно лучше для начинающих: не нужно устанавливать инструменты, настраивать среду или разбираться в git. Copilot — расширение для существующей IDE, требует базовых знаний разработки."}, {"q": "Может ли Replit заменить локальную IDE?", "a": "Для многих задач — да. Replit поддерживает 50+ языков программирования и работает в браузере. Для профессиональной разработки с кастомными расширениями, git workflow и локальной отладкой большинство предпочитает локальные IDE с Copilot."}]$t94fq$::JSONB WHERE slug = 'replit' AND lang = 'ru';
UPDATE tools SET choose_if = $t95ci$["✅ Строите внутренние инструменты: панели администратора, CRUD-интерфейсы, операционные приложения", "✅ Нужен полноценный конструктор приложений с базой данных, API и бизнес-логикой", "✅ Используете ИИ для генерации компонентов и автоматизации рабочих процессов внутри Retool", "✅ Нужна кастомная логика, которую обычные BI-инструменты не поддерживают"]$t95ci$::JSONB, faq = $t95fq$[{"q": "Retool vs Looker Studio — в чём разница?", "a": "Retool — конструктор внутренних приложений: создаёт операционные инструменты с CRUD-интерфейсами. Looker Studio — BI-инструмент для визуализации: создаёт аналитические дашборды. Retool строит приложения, Looker Studio строит отчёты."}, {"q": "Looker Studio бесплатный?", "a": "Да. Looker Studio полностью бесплатен от Google. Retool бесплатен до 5 пользователей с базовыми функциями; Business-план от $10/пользователь/мес."}, {"q": "Что такое Retool AI?", "a": "Retool AI — набор ИИ-компонентов внутри Retool: чат-интерфейсы, генерация кода, автоматизация с ИИ-агентами. Позволяет добавлять ИИ-функции во внутренние приложения без написания сложного кода."}, {"q": "Заменяет ли Retool разработку?", "a": "Retool сокращает время разработки внутренних инструментов в 10 раз, но требует технического пользователя. Для создания сложных приложений с нестандартной логикой всё равно нужен разработчик."}]$t95fq$::JSONB WHERE slug = 'retool-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t96ci$["✅ Аналитик или бизнес-пользователь, которому нужна умная таблица с прямыми интеграциями данных", "✅ Хотите создавать живые отчёты в знакомом интерфейсе электронных таблиц", "✅ Нужны интеграции с Stripe, Google Analytics, HubSpot без написания кода", "✅ Хотите делиться красивыми интерактивными таблицами с командой или клиентами"]$t96ci$::JSONB, faq = $t96fq$[{"q": "Rows vs Hex — что выбрать?", "a": "Rows — умная таблица: для бизнес-пользователей, которые хотят что-то лучше Google Sheets. Hex — аналитическая платформа: для аналитиков данных, работающих с SQL и Python. Rows ближе к Excel/Sheets, Hex ближе к Jupyter с командным функционалом."}, {"q": "Rows бесплатный?", "a": "Rows предлагает бесплатный план с ограниченными интеграциями и строками. Платные планы от $59/мес для команд. Hex имеет бесплатный план для 1 пользователя с 5 проектами."}, {"q": "Hex требует знания программирования?", "a": "Hex поддерживает SQL и Python — знание хотя бы одного поможет раскрыть весь потенциал. Встроенный ИИ может генерировать SQL по описанию задачи, что снижает порог входа."}, {"q": "Чем Rows отличается от Google Sheets?", "a": "Rows имеет нативные интеграции с 50+ сервисами (Stripe, Salesforce, Twitter), встроенные ИИ-функции и более красивый интерфейс для публичных таблиц. Google Sheets бесплатен и имеет более широкую экосистему расширений."}]$t96fq$::JSONB WHERE slug = 'rows' AND lang = 'ru';
UPDATE tools SET choose_if = $t97ci$["✅ Нужно высочайшее качество по бенчмаркам — Gen-4.5 занимает первое место в рейтингах text-to-video", "✅ Нужен доступ к нескольким моделям (Veo 3.1, Kling, Seedance, FLUX) в одной подписке", "✅ Критична согласованность персонажей и окружения в многоплановых последовательностях", "✅ Вы профессиональный создатель видео, которому нужен лучший доступный вывод"]$t97ci$::JSONB, faq = $t97fq$[{"q": "Kling AI лучше Runway в 2026 году?", "a": "Зависит от приоритетов. Runway Gen-4.5 лидирует по качеству бенчмаркам и предлагает многомодельную подписку. Kling 3.0 предлагает лучшую ценность — больше бесплатных кредитов, нативное 4K и более низкую цену. Для профессионалов — Runway, для соотношения цена/качество — Kling."}, {"q": "Можно использовать Kling AI бесплатно?", "a": "Да. Kling AI предлагает 66 бесплатных кредитов ежедневно — самый щедрый бесплатный уровень среди качественных генераторов ИИ-видео. Бесплатный пробный период Runway даёт 125 одноразовых кредитов без обновления."}, {"q": "Что такое Runway Gen-4.5?", "a": "Runway Gen-4.5 — последняя видеомодель Runway, занимающая первое место в рейтингах text-to-video по состоянию на 2025 год. Доступна на всех платных планах Runway, а подписка также включает Veo 3.1, Kling 3.0, Seedance и FLUX."}, {"q": "Kling AI поддерживает 4K?", "a": "Да. Kling 3.0 (февраль 2026 года) поддерживает нативный вывод 4K с инструментом раскадровки для покадрового управления камерой и встроенной генерацией аудио с синхронизацией губ."}]$t97fq$::JSONB WHERE slug = 'runway' AND lang = 'ru';
UPDATE tools SET choose_if = $t98ci$["✅ Нужно знать, поддерживает ли или опровергает ли другая статья цитируемую вами работу", "✅ Исследуете научную область и хотите понять консенсус по теме через цитирования", "✅ Пишете диссертацию и нужна проверка достоверности источников с контекстом цитирования", "✅ Хотите Smart Citations — видеть, как именно статья процитирована другими авторами"]$t98ci$::JSONB, faq = $t98fq$[{"q": "Scite vs Semantic Scholar — в чём разница?", "a": "Scite уникален тем, что показывает, как статья процитирована — поддерживающие, опровергающие или нейтральные упоминания. Semantic Scholar — бесплатный ИИ-поисковик по научным работам с суммаризацией. Scite для оценки доказательной базы, Semantic Scholar для широкого поиска."}, {"q": "Scite бесплатный?", "a": "Scite предлагает ограниченный бесплатный план. Полный доступ к Smart Citations стоит $20/мес или $144/год. Semantic Scholar полностью бесплатен."}, {"q": "Semantic Scholar лучше Google Scholar?", "a": "Semantic Scholar добавляет ИИ-функции: суммаризация, связанные работы, граф влияния. Google Scholar охватывает больше источников, включая патенты и диссертации. Для академических работ — Semantic Scholar, для широкого поиска — Google Scholar."}, {"q": "Scite работает с PubMed?", "a": "Да. Scite индексирует биомедицинские исследования, совместимые с PubMed, и показывает Smart Citations для медицинских статей. Это особенно ценно для медицинских исследователей, проверяющих консенсус по клиническим данным."}]$t98fq$::JSONB WHERE slug = 'scite' AND lang = 'ru';
UPDATE tools SET choose_if = $t99ci$["✅ Нужно высококачественное ИИ-видео по конкурентной цене с хорошим балансом качества и стоимости", "✅ Хотите попробовать ведущую китайскую ИИ-видеомодель от ByteDance", "✅ Нужен сильный конкурент для сравнения с Runway и Kling при выборе инструмента", "✅ Создаёте динамичные сцены с реалистичным движением объектов"]$t99ci$::JSONB, faq = $t99fq$[{"q": "Seedance vs Runway — что лучше?", "a": "Runway Gen-4.5 занимает верхние строки в большинстве лидербордов качества ИИ-видео. Seedance 2.0 от ByteDance — сильный конкурент с отличным соотношением цены и качества. Runway более зрелая платформа; Seedance может быть дешевле для сопоставимого качества."}, {"q": "Что такое Seedance 2.0?", "a": "Seedance 2.0 — ИИ-видеомодель от ByteDance (создатели TikTok). Специализируется на реалистичном движении и динамичных сценах. Доступен через API и ряд платформ."}, {"q": "Runway бесплатный?", "a": "Runway предлагает 125 вступительных кредитов. Standard — $15/мес, Pro — $35/мес. Стоимость генерации видео зависит от длины и качества."}, {"q": "Kling или Seedance — кто лучший конкурент Runway?", "a": "По состоянию на 2026 год Kling AI 3.0 и Seedance 2.0 оба конкурируют с Runway Gen-4.5. Kling превосходит в 4K-выводе и длинных клипах. Seedance силён в реалистичном движении. Runway сохраняет преимущество в профессиональных постпродакшн-функциях."}]$t99fq$::JSONB WHERE slug = 'seedance-2-0' AND lang = 'ru';
UPDATE tools SET choose_if = $t100ci$["✅ Нужен бесплатный поиск по 220+ миллионам научных работ", "✅ Используете ИИ-функции для суммаризации статей и поиска по тексту", "✅ Нужно найти влиятельные статьи по теме с графом цитирований", "✅ Создаёте персональный список литературы и управляете библиографией"]$t100ci$::JSONB, faq = $t100fq$[{"q": "Scite vs Semantic Scholar — в чём разница?", "a": "Scite уникален тем, что показывает, как статья процитирована — поддерживающие, опровергающие или нейтральные упоминания. Semantic Scholar — бесплатный ИИ-поисковик по научным работам с суммаризацией. Scite для оценки доказательной базы, Semantic Scholar для широкого поиска."}, {"q": "Scite бесплатный?", "a": "Scite предлагает ограниченный бесплатный план. Полный доступ к Smart Citations стоит $20/мес или $144/год. Semantic Scholar полностью бесплатен."}, {"q": "Semantic Scholar лучше Google Scholar?", "a": "Semantic Scholar добавляет ИИ-функции: суммаризация, связанные работы, граф влияния. Google Scholar охватывает больше источников, включая патенты и диссертации. Для академических работ — Semantic Scholar, для широкого поиска — Google Scholar."}, {"q": "Scite работает с PubMed?", "a": "Да. Scite индексирует биомедицинские исследования, совместимые с PubMed, и показывает Smart Citations для медицинских статей. Это особенно ценно для медицинских исследователей, проверяющих консенсус по клиническим данным."}]$t100fq$::JSONB WHERE slug = 'semantic-scholar' AND lang = 'ru';
UPDATE tools SET choose_if = $t101ci$["✅ Нужен SEO-анализ: исследование ключевых слов, аудит сайта, анализ конкурентов", "✅ Управляете органическим трафиком и нужны данные для SEO-стратегии", "✅ Нужен полный маркетинговый комбайн: SEO + PPC + контент + мониторинг ссылок", "✅ Работаете в SEO-агентстве и нужны профессиональные данные для клиентских отчётов"]$t101ci$::JSONB, faq = $t101fq$[{"q": "Semrush vs Copy.ai — это сравнение разных инструментов?", "a": "Да. Semrush — SEO-платформа для анализа данных, исследования ключевых слов и аудита сайтов. Copy.ai — ИИ-генератор контента для написания текстов. Они решают разные задачи, хотя оба используются в контент-маркетинге."}, {"q": "Semrush бесплатный?", "a": "Semrush предлагает ограниченный бесплатный план (10 запросов в день). Pro план — от $139.95/мес. Copy.ai бесплатен с ограниченными словами; платные планы от $49/мес."}, {"q": "Нужны ли оба инструмента?", "a": "Для контент-маркетинга — да: Semrush находит ключевые слова и темы для контента, Copy.ai помогает его написать быстро. Многие маркетинговые команды используют оба в связке."}, {"q": "Есть ли у Semrush функции ИИ-написания?", "a": "Да. Semrush добавил ContentShake AI — инструмент для написания SEO-статей, который использует данные ключевых слов Semrush. Это более специализированный инструмент, чем Copy.ai, но дороже."}]$t101fq$::JSONB WHERE slug = 'semrush' AND lang = 'ru';
UPDATE tools SET choose_if = $t102ci$["✅ Нужны бесплатные профессиональные шаблоны для Google Slides или PowerPoint", "✅ Предпочитаете самостоятельно наполнять шаблон, а не генерировать слайды ИИ", "✅ Нужно широкое разнообразие дизайнов для учёбы, бизнеса или мероприятий", "✅ Хотите отредактировать шаблон в Google Slides без нового инструмента"]$t102ci$::JSONB, faq = $t102fq$[{"q": "Slidesgo vs Gamma — что лучше?", "a": "Slidesgo даёт шаблоны для самостоятельного создания презентаций в Google Slides/PowerPoint. Gamma генерирует всю презентацию по описанию с помощью ИИ. Slidesgo для тех, кто хочет контроль над дизайном, Gamma — для тех, кто хочет скорость."}, {"q": "Slidesgo бесплатный?", "a": "Slidesgo предлагает сотни бесплатных шаблонов. Premium ($5.99/мес) открывает все шаблоны и функции. Gamma бесплатен с ограниченными ИИ-генерациями; Pro — $10/мес."}, {"q": "Gamma заменяет PowerPoint?", "a": "Gamma создаёт интерактивные документы-презентации, которые лучше работают в браузере. Для традиционных слайдов в корпоративной среде PowerPoint остаётся стандартом. Gamma отлично подходит для питчей и онлайн-презентаций."}, {"q": "Можно ли использовать шаблоны Slidesgo в Canva?", "a": "Да. У Slidesgo есть отдельная коллекция шаблонов для Canva, помимо Google Slides и PowerPoint. Это удобно для пользователей Canva, которым нужен более широкий выбор дизайнов."}]$t102fq$::JSONB WHERE slug = 'slidesgo' AND lang = 'ru';
UPDATE tools SET choose_if = $t103ci$["✅ Школьник, которому нужна быстрая помощь с домашними заданиями — просто сфотографировать задачу", "✅ Хотите объяснения по фото вопроса: математика, биология, история, химия", "✅ Нужен бесплатный мобильный инструмент без подписки для разных предметов", "✅ Предпочитаете получить объяснение концепции, а не пошаговое решение"]$t103ci$::JSONB, faq = $t103fq$[{"q": "Socratic vs Khanmigo — что выбрать школьнику?", "a": "Socratic (Google) — быстрый: фотографируй задачу, получи объяснение. Khanmigo — более глубокий: ведёт Сократовский диалог, не давая ответы сразу. Для быстрой помощи — Socratic, для понимания материала — Khanmigo."}, {"q": "Socratic бесплатный?", "a": "Да. Socratic by Google полностью бесплатен на iOS и Android. Khanmigo — $9/мес. Это главное преимущество Socratic для учеников."}, {"q": "Socratic даёт ответы или объяснения?", "a": "Socratic акцентирует объяснения концепций, а не просто ответы. При фотографировании задачи он показывает, как подойти к решению. Однако уровень детализации ниже, чем у Khanmigo с его диалоговым форматом."}, {"q": "Khanmigo безопаснее для учеников, чем ChatGPT?", "a": "Да. Khanmigo разработан с учётом безопасности для детей: не даёт готовые ответы, не отклоняется от учебных тем, соответствует COPPA. ChatGPT мощнее, но менее защищён от неучебного использования."}]$t103fq$::JSONB WHERE slug = 'socratic-by-google' AND lang = 'ru';
UPDATE tools SET choose_if = $t104ci$["✅ Строите клиентский портал, справочник или простое веб-приложение на основе Airtable или Google Sheets", "✅ Нужен самый простой способ превратить spreadsheet в рабочее приложение без кода", "✅ Хотите запустить за часы, а не дни — Softr идеален для MVP на базе существующих данных", "✅ Нужны порталы для клиентов, справочники сотрудников или простые маркетплейсы"]$t104ci$::JSONB, faq = $t104fq$[{"q": "Softr vs Bubble — что проще?", "a": "Softr значительно проще: берёт данные из Airtable/Google Sheets и превращает в приложение за часы. Bubble мощнее, но требует больше времени на освоение — его возможности ближе к реальной разработке."}, {"q": "Softr бесплатный?", "a": "Softr предлагает бесплатный план с ограниченными записями и пользователями. Starter — $59/мес. Bubble также имеет бесплатный план; Starter — $32/мес. Оба с ростом тарифов при масштабировании."}, {"q": "Можно ли создать SaaS на Softr?", "a": "Для простых SaaS-продуктов — да. Softr поддерживает авторизацию, платежи (Stripe) и управление контентом. Для сложных приложений со своей базой данных и нестандартной логикой Bubble предоставляет больше гибкости."}, {"q": "Softr или Bubble — что выбрать для стартапа?", "a": "Для быстрого MVP на основе Airtable — Softr. Для полноценного масштабируемого продукта — Bubble. Некоторые стартапы начинают с Softr для проверки гипотезы, затем перестраиваются на Bubble или кастомную разработку."}]$t104fq$::JSONB WHERE slug = 'softr' AND lang = 'ru';
UPDATE tools SET choose_if = $t105ci$["✅ Хотите слушать статьи, документы и книги вслух — это ваш личный слуховой ридер", "✅ Нужно преобразование любого контента в аудио для потребления в формате подкаста", "✅ Импортируете веб-страницы, PDF и книги и слушаете их голосом Speechify", "✅ Нужна скорость воспроизведения (до 4.5x) для быстрого усвоения контента"]$t105ci$::JSONB, faq = $t105fq$[{"q": "Speechify vs ElevenLabs — в чём разница?", "a": "Speechify — читалка вслух: для личного потребления контента. ElevenLabs — студия синтеза речи: для создания аудиоконтента и разработки приложений. Speechify слушает чужой контент, ElevenLabs создаёт свой."}, {"q": "Speechify бесплатный?", "a": "Speechify предлагает бесплатный план с базовыми голосами. Premium ($139/год) открывает лучшие голоса и более высокую скорость. ElevenLabs бесплатен с 10 000 символов в месяц."}, {"q": "ElevenLabs лучше Speechify для создания подкастов?", "a": "Для создания подкастов — ElevenLabs. Для прослушивания подкастов и статей — Speechify. ElevenLabs создаёт реалистичный синтез для производства, Speechify воспроизводит контент для личного потребления."}, {"q": "Может ли Speechify клонировать голос?", "a": "Да. Speechify Voice Studio включает клонирование голоса. Однако ElevenLabs предлагает лучшее качество клонирования с меньшим количеством образцов и более естественным результатом."}]$t105fq$::JSONB WHERE slug = 'speechify' AND lang = 'ru';
UPDATE tools SET choose_if = $t106ci$["✅ Хотите бесплатную генерацию изображений без ограничений — Stable Diffusion работает локально", "✅ Нужен полный контроль: свои модели, LoRA, ControlNet, тонкая настройка", "✅ Нужна NSFW-генерация или специфические стили без ограничений платформы", "✅ Строите продукт на базе ИИ-генерации изображений и нужен бесплатный API"]$t106ci$::JSONB, faq = $t106fq$[{"q": "Midjourney vs Stable Diffusion — какое качество лучше?", "a": "Midjourney V7 стабильно выдаёт более высокое художественное качество «из коробки». Stable Diffusion с правильными моделями и настройками может приближаться, но требует значительно больше технических знаний."}, {"q": "Stable Diffusion полностью бесплатный?", "a": "Да, Stable Diffusion — open-source модель. Базовые версии бесплатны через Automatic1111 или ComfyUI локально. Требует GPU (6–8GB VRAM) для комфортной работы. Облачные сервисы на его основе (DreamStudio) имеют платные тарифы."}, {"q": "Как сложно настроить Stable Diffusion?", "a": "Базовая установка занимает 1–2 часа для технически грамотного пользователя. Установка расширений (ControlNet, LoRA) добавляет сложность. Существуют упрощённые интерфейсы (Invoke AI, Fooocus), которые проще в настройке."}, {"q": "Можно ли коммерчески использовать изображения Stable Diffusion?", "a": "Stable Diffusion 3.5 имеет коммерческую лицензию для бизнеса с доходом до $1M в год. Более крупным компаниям нужна Enterprise-лицензия. Изображения Midjourney требуют Pro-план для коммерческого использования."}]$t106fq$::JSONB WHERE slug = 'stable-diffusion' AND lang = 'ru';
UPDATE tools SET choose_if = $t107ci$["✅ Хотите быстро генерировать законченные песни из текстового описания", "✅ Вы casual-создатель, которому нужны полные песни с вокалом за секунды", "✅ Нужен простой интерфейс — описываете песню, получаете песню", "✅ Нужна наиболее широко используемая ИИ-музыкальная платформа с крупнейшим сообществом"]$t107ci$::JSONB, faq = $t107fq$[{"q": "Suno или Udio — что лучше?", "a": "Suno лучше для быстрой генерации полных песен — быстрее и удобнее. Udio в целом производит более высокое качество звука, но имеет ограничения на скачивание в некоторых регионах. Оба конкурентоспособны, Suno лидирует по удобству использования и размеру сообщества."}, {"q": "Suno бесплатный?", "a": "Suno предлагает бесплатный план с 50 кредитами в день (около 10 песен). Plan Pro — $8/мес, Premier — $24/мес для большего количества кредитов, прав на коммерческое использование и приоритетной генерации."}, {"q": "Можно ли продавать музыку, созданную в Suno?", "a": "Да, на платных планах. Suno Pro и Premier предоставляют права на коммерческое использование сгенерированной музыки. Бесплатный план не разрешает коммерческое использование. Всегда проверяйте актуальные условия, так как лицензирование ИИ-музыки продолжает развиваться."}, {"q": "Что такое Udio AI?", "a": "Udio — инструмент генерации ИИ-музыки, создающий песни из текстовых запросов. Запущен в 2024 году и известен особенно высоким качеством звука. Udio столкнулся с юридическими претензиями от крупных звукозаписывающих лейблов относительно обучающих данных."}]$t107fq$::JSONB WHERE slug = 'suno' AND lang = 'ru';
UPDATE tools SET choose_if = $t108ci$["✅ Фокус — написание SEO-оптимизированных статей с подсказками по ключевым словам в реальном времени", "✅ Нужен инструмент для оптимизации конкретной страницы и улучшения существующего контента", "✅ Хотите встроенный ИИ-редактор, который подсказывает структуру и термины во время написания", "✅ Ограниченный бюджет на SEO-инструменты — Surfer SEO дешевле полных планов Semrush"]$t108ci$::JSONB, faq = $t108fq$[{"q": "Surfer SEO vs Semrush — что выбрать?", "a": "Surfer SEO специализируется на оптимизации контента: показывает, как улучшить страницу, чтобы она ранжировалась лучше. Semrush — полноценная SEO-платформа с исследованием ключевых слов, анализом конкурентов, аудитом и PPC. Surfer — инструмент контент-маркетолога, Semrush — инструмент SEO-стратега."}, {"q": "Surfer SEO дешевле Semrush?", "a": "Да. Surfer SEO Essential — $89/мес, Scale — $129/мес. Semrush Pro — $139.95/мес, Guru — $249.95/мес. Surfer дешевле, но охватывает меньше задач."}, {"q": "Нужны ли оба — Surfer и Semrush?", "a": "Многие SEO-специалисты используют Semrush для исследования ключевых слов и анализа конкурентов, а Surfer — для оптимизации конкретных статей. Они хорошо дополняют друг друга."}, {"q": "Surfer SEO помогает с написанием контента?", "a": "Да. Surfer SEO включает ИИ-редактор Surfer AI, который генерирует SEO-статьи по ключевому слову. Он также даёт рекомендации в реальном времени при написании вручную."}]$t108fq$::JSONB WHERE slug = 'surferseo' AND lang = 'ru';
UPDATE tools SET choose_if = $t109ci$["✅ Создаёте корпоративное обучение, вводные инструктажи или видео по соблюдению нормативов в корпоративном масштабе", "✅ Организации нужна строгая безопасность данных, соответствие SOC 2 и корпоративный SSO", "✅ Нужна проверенная платформа с сотнями профессиональных вариантов аватаров", "✅ Нужна совместимая с SCORM интеграция LMS для электронного обучения"]$t109ci$::JSONB, faq = $t109fq$[{"q": "В чём разница между HeyGen и Synthesia?", "a": "HeyGen лидирует по переводу видео (дублированию с синхронизацией губ на 175+ языках) и качеству аватаров. Synthesia лидирует по корпоративным функциям, соответствию требованиям и интеграции LMS для корпоративного обучения. HeyGen — для маркетинга, Synthesia — для L&D-команд."}, {"q": "Может ли HeyGen клонировать мой голос?", "a": "Да. HeyGen может клонировать ваш голос и создать ИИ-аватар, который выглядит и звучит как вы, из короткой записи. Используется для перевода видео — ваш аватар говорит на других языках вашим клонированным голосом."}, {"q": "Synthesia бесплатный?", "a": "Synthesia предлагает бесплатный план с 3 минутами видео в месяц. Платные планы начинаются от $29/мес (Starter, 10 минут) и $89/мес (Creator). Корпоративные цены — индивидуальные."}, {"q": "Сколько стоит HeyGen?", "a": "Plan Creator HeyGen начинается от $29/мес (4 минуты видео). Business — $89/мес (15 минут). Корпоративные цены — индивидуальные. Кредиты для перевода видео продаются отдельно."}]$t109fq$::JSONB WHERE slug = 'synthesia' AND lang = 'ru';
UPDATE tools SET choose_if = $t110ci$["✅ У вас ребёнок 6-14 лет и нужна платформа с игровым математическим мышлением", "✅ Хотите развить у ребёнка критическое мышление и решение задач, а не просто запоминание", "✅ Нужны групповые математические игры, которые учат сотрудничеству", "✅ Ищете более мотивирующую замену традиционной математике с высокой вовлечённостью"]$t110ci$::JSONB, faq = $t110fq$[{"q": "Synthesis vs Khanmigo — в чём разница?", "a": "Synthesis (от SpaceX Education) — обучающая игровая платформа по математике для детей с акцентом на проблемное мышление. Khanmigo — ИИ-репетитор Khan Academy с Сократовским подходом для более широкого круга предметов. Synthesis — игры, Khanmigo — репетиторство."}, {"q": "Synthesis бесплатный?", "a": "Synthesis предлагает бесплатный пробный период. Подписка — около $35/мес. Khanmigo — $9/мес как дополнение к бесплатной Khan Academy."}, {"q": "Khanmigo даёт ответы на домашние задания?", "a": "Нет намеренно. Khanmigo использует Сократовский метод — задаёт наводящие вопросы, чтобы ученик пришёл к ответу самостоятельно. Цель — понимание, а не списывание."}, {"q": "Для какого возраста Synthesis?", "a": "Synthesis ориентирован на детей 6-14 лет (классы 1-8). Платформа использует командные головоломки и математические игры, разработанные для SpaceX-школы. Khanmigo подходит для более широкого возрастного диапазона."}]$t110fq$::JSONB WHERE slug = 'synthesis' AND lang = 'ru';
UPDATE tools SET choose_if = $t111ci$["✅ Вы корпоративный аналитик, которому нужно продвинутое моделирование данных и сложные вычисления", "✅ У вас очень большие наборы данных, требующие оптимизированного движка Tableau для производительности", "✅ Нужен сложный статистический анализ, кастомные экстракты данных и управляемый доступ", "✅ Вы в зрелой в области данных организации, где Tableau — установленный стандарт"]$t111ci$::JSONB, faq = $t111fq$[{"q": "Looker Studio бесплатный?", "a": "Да. Looker Studio полностью бесплатен без ограничений на дашборды, отчёты или объём данных. Подключается к 800+ источникам данных. Есть платные функции Looker Studio Pro для корпоративного управления, но основной продукт бесплатен."}, {"q": "Сколько стоит Tableau?", "a": "Tableau Viewer — $15/пользователь/мес, Explorer — $42/пользователь/мес, Creator — $75/пользователь/мес. Корпоративные цены варьируются. Tableau значительно дороже альтернатив, но широко считается золотым стандартом для сложной корпоративной аналитики."}, {"q": "Looker Studio так же мощен, как Tableau?", "a": "Для большинства задач бизнес-отчётности Looker Studio достаточен. Tableau имеет преимущества для очень больших наборов данных, сложных вычислений, продвинутого статистического анализа и корпоративного управления. Looker Studio хорошо справляется с обычными BI-дашбордами, Tableau — для продвинутых дата-команд."}, {"q": "Что такое Tableau AI?", "a": "Tableau AI относится к функциям Einstein AI, встроенным в Tableau: запросы на естественном языке, ИИ-генерируемые инсайты и автоматическое обнаружение аномалий. Эти функции требуют лицензирования Tableau+ или Tableau с Salesforce Einstein."}]$t111fq$::JSONB WHERE slug = 'tableau-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t112ci$["✅ Хотите ИИ-сигналы торговли и паттерны с прогнозами точности для акций", "✅ Нужны ИИ-роботы для автоматической торговли без написания кода", "✅ Хотите торговые идеи от ИИ, а не самостоятельный технический анализ", "✅ Нужна оценка риска и вероятности успеха для каждого сигнала"]$t112ci$::JSONB, faq = $t112fq$[{"q": "Tickeron vs TradingView — в чём разница?", "a": "Tickeron — ИИ-торговая платформа с автоматическими сигналами и роботами. TradingView — профессиональная платформа для графиков с инструментами технического анализа. Tickeron предлагает ИИ-рекомендации, TradingView — инструменты для самостоятельного анализа."}, {"q": "Tickeron бесплатный?", "a": "Tickeron предлагает ограниченный бесплатный план. Платные планы от $90/мес. TradingView бесплатен с базовыми функциями; Essential — $12.95/мес."}, {"q": "Насколько точны ИИ-сигналы Tickeron?", "a": "Tickeron публикует исторические показатели точности для своих паттернов и сигналов. Важно понимать: прошлая точность не гарантирует будущих результатов. Используйте сигналы как один из факторов, не как единственный источник торговых решений."}, {"q": "TradingView имеет ИИ-функции?", "a": "TradingView добавил ИИ-скринеры и ИИ-функции в Pine Script. Но основная сила — инструменты ручного технического анализа и сообщество. Tickeron более специализирован на автоматических ИИ-сигналах."}]$t112fq$::JSONB WHERE slug = 'tickeron' AND lang = 'ru';
UPDATE tools SET choose_if = $t113ci$["✅ Активно торгуете и нужны профессиональные графики, технические индикаторы и скринеры", "✅ Хотите доступ к огромному сообществу трейдеров и публичным торговым идеям", "✅ Нужна торговля прямо из платформы через подключённого брокера", "✅ Анализируете криптовалюты, форекс и акции в одном месте"]$t113ci$::JSONB, faq = $t113fq$[{"q": "TradingView vs Finchat — для кого каждый?", "a": "TradingView — для технических трейдеров и тех, кто анализирует графики. Finchat — для фундаментальных инвесторов, изучающих финансовую отчётность компаний. Это разные инструменты для разных стилей инвестирования."}, {"q": "TradingView бесплатный?", "a": "TradingView имеет бесплатный план с ограниченными индикаторами и алертами. Essential — $12.95/мес, Plus — $24.95/мес, Premium — $49.95/мес. Finchat предлагает бесплатный план с базовыми данными; Pro — $22/мес."}, {"q": "Что такое Finchat?", "a": "Finchat — ИИ-финансовый аналитик с доступом к 750 000+ KPI из отчётности публичных компаний. Задайте вопрос на естественном языке — получите данные из 10-K, 10-Q и звонков с аналитиками с ссылками на источники."}, {"q": "Можно ли торговать через TradingView?", "a": "Да. TradingView интегрируется с рядом брокеров (Interactive Brokers, Alpaca и другими), позволяя торговать прямо из интерфейса. Это уникальная функция, которой нет у большинства чисто аналитических платформ."}]$t113fq$::JSONB WHERE slug = 'tradingview' AND lang = 'ru';
UPDATE tools SET choose_if = $t114ci$["✅ Приоритет — качество звука и музыкальная детализация, а не скорость", "✅ Вы музыкант, который хочет больше контроля над стемами и музыкальной структурой", "✅ Создаёте инструментальную или жанровую музыку, где важны нюансы качества", "✅ Хотите генерировать короткие высококачественные музыкальные клипы для создания длинных треков"]$t114ci$::JSONB, faq = $t114fq$[{"q": "Suno или Udio — что лучше?", "a": "Suno лучше для быстрой генерации полных песен — быстрее и удобнее. Udio в целом производит более высокое качество звука, но имеет ограничения на скачивание в некоторых регионах. Оба конкурентоспособны, Suno лидирует по удобству использования и размеру сообщества."}, {"q": "Suno бесплатный?", "a": "Suno предлагает бесплатный план с 50 кредитами в день (около 10 песен). Plan Pro — $8/мес, Premier — $24/мес для большего количества кредитов, прав на коммерческое использование и приоритетной генерации."}, {"q": "Можно ли продавать музыку, созданную в Suno?", "a": "Да, на платных планах. Suno Pro и Premier предоставляют права на коммерческое использование сгенерированной музыки. Бесплатный план не разрешает коммерческое использование. Всегда проверяйте актуальные условия, так как лицензирование ИИ-музыки продолжает развиваться."}, {"q": "Что такое Udio AI?", "a": "Udio — инструмент генерации ИИ-музыки, создающий песни из текстовых запросов. Запущен в 2024 году и известен особенно высоким качеством звука. Udio столкнулся с юридическими претензиями от крупных звукозаписывающих лейблов относительно обучающих данных."}]$t114fq$::JSONB WHERE slug = 'udio' AND lang = 'ru';
UPDATE tools SET choose_if = $t115ci$["✅ Не являетесь дизайнером и хотите создать прототип приложения или сайта из описания", "✅ Нужно превратить скетч или скриншот в редактируемый прототип за секунды", "✅ Быстрое прототипирование идеи для демонстрации стейкхолдерам без найма дизайнера", "✅ Хотите простой инструмент без крутого порога входа, присущего Figma"]$t115ci$::JSONB, faq = $t115fq$[{"q": "Что такое Uizard?", "a": "Uizard — ИИ-инструмент прототипирования, позволяющий не-дизайнерам создавать макеты приложений и сайтов. Умеет преобразовывать скетчи и скриншоты в редактируемые прототипы, генерировать дизайны по текстовым описаниям."}, {"q": "Uizard заменяет Figma?", "a": "Нет. Uizard — для быстрого прототипирования и не-дизайнеров. Figma — для профессионального производственного дизайна. Uizard идеален для демонстрации концепции, Figma — для финального продукта."}, {"q": "Uizard бесплатный?", "a": "Uizard предлагает бесплатный план с ограниченными проектами и генерациями ИИ. Starter — $12/мес, Pro — $29/мес. Figma имеет бесплатный план для индивидуальных пользователей."}, {"q": "Figma AI может генерировать дизайны из текста?", "a": "Да. Figma AI (функция Make Design, 2024) генерирует макеты из текстовых описаний. Однако это дополнение к существующему рабочему процессу Figma, а не замена навыков дизайна."}]$t115fq$::JSONB WHERE slug = 'uizard' AND lang = 'ru';
UPDATE tools SET choose_if = $t116ci$["✅ Нужен ИИ-ассистент для анализа рыночных трендов и торговых идей", "✅ Хотите видеть инсайты по акциям на основе технического и фундаментального анализа в едином чате", "✅ Нужна простая платформа для быстрого исследования отдельных акций", "✅ Хотите ИИ-объяснения рыночных движений без глубокого погружения в данные"]$t116ci$::JSONB, faq = $t116fq$[{"q": "Uptrends AI vs Koyfin — что выбрать?", "a": "Uptrends AI — ИИ-ориентированный инструмент для получения быстрых инсайтов по рынку. Koyfin — полноценная финансовая платформа с глубокими данными по акциям, экономике и портфелю. Uptrends проще и доступнее, Koyfin мощнее для серьёзного анализа."}, {"q": "Koyfin бесплатный?", "a": "Koyfin предлагает щедрый бесплатный план с базовыми графиками и данными. Plus — $49/мес, Pro — $99/мес для профессиональных данных. Uptrends AI также имеет бесплатный план с ограниченными запросами."}, {"q": "Koyfin заменяет Bloomberg?", "a": "Для независимых инвесторов и небольших фондов — частично да. Koyfin охватывает многие функции Bloomberg по доле цены. Для профессиональной торговли с мгновенными данными и терминальным доступом Bloomberg по-прежнему лидирует."}, {"q": "Что такое Uptrends AI?", "a": "Uptrends AI — ИИ-платформа для инвесторов, предоставляющая анализ акций, рыночные тренды и торговые идеи через разговорный интерфейс. Позиционируется как ИИ-ассистент для принятия инвестиционных решений."}]$t116fq$::JSONB WHERE slug = 'uptrends-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t117ci$["✅ Нужна ИИ-генерация полных UI-экранов и прототипов с нуля из промпта", "✅ Хотите специализированный UX-инструмент с акцентом на пользовательские потоки и wireframes", "✅ Не хватает дизайнерских навыков для Figma, но нужны профессионально выглядящие макеты", "✅ Нужна быстрая генерация вариантов дизайна для A/B тестирования"]$t117ci$::JSONB, faq = $t117fq$[{"q": "Что такое UXPilot?", "a": "UXPilot — ИИ-инструмент для UX-дизайна, генерирующий wireframes, UI-экраны и прототипы по текстовым описаниям. Специализируется на быстром создании пользовательских потоков и макетов без глубоких дизайнерских навыков."}, {"q": "UXPilot или Figma AI — что выбрать стартапу?", "a": "Для стартапа без дизайнеров UXPilot позволяет быстро создать прототипы. Figma AI требует понимания Figma. Многие стартапы используют UXPilot для генерации идей, затем доводят их в Figma."}, {"q": "UXPilot экспортирует в Figma?", "a": "Да. UXPilot позволяет экспортировать дизайны в Figma для дальнейшего редактирования и уточнения. Это типичный рабочий процесс: генерация в UXPilot, финальная полировка в Figma."}, {"q": "Сколько стоит UXPilot?", "a": "UXPilot предлагает бесплатный пробный период. Платные планы от $20/мес. Figma бесплатен для индивидуальных дизайнеров, Figma Pro — $15/мес/редактор."}]$t117fq$::JSONB WHERE slug = 'uxpilot' AND lang = 'ru';
UPDATE tools SET choose_if = $t118ci$["✅ Создаёте React/Next.js UI-компоненты из текстовых описаний без написания кода", "✅ Фронтенд-разработчик или дизайнер, которому нужен быстрый способ создания прототипов интерфейсов", "✅ Деплоите на Vercel и хотите мгновенную интеграцию с платформой", "✅ Хотите получить готовый, стилизованный код компонента за секунды"]$t118ci$::JSONB, faq = $t118fq$[{"q": "Что такое v0 by Vercel?", "a": "v0 — ИИ-инструмент от Vercel для генерации React/Next.js UI-компонентов по текстовым описаниям. Выдаёт готовый код на основе shadcn/ui и Tailwind CSS. Идеален для быстрого прототипирования интерфейсов."}, {"q": "v0 бесплатный?", "a": "v0 предлагает ограниченное бесплатное использование. Платные планы от $10/мес с большим количеством запросов. Cursor стоит $20/мес за Pro."}, {"q": "v0 vs Cursor — что выбрать?", "a": "v0 отлично подходит для генерации UI-компонентов и прототипирования фронтенда. Cursor — универсальный ИИ-редактор для всей разработки. Многие используют оба: v0 для создания интерфейсов, Cursor для их доработки и работы с бэкендом."}, {"q": "Работает ли v0 только с Next.js?", "a": "v0 оптимизирован для React/Next.js, но может генерировать компоненты и для других фреймворков. Интеграция с Vercel обеспечивает мгновенный деплой созданных компонентов."}]$t118fq$::JSONB WHERE slug = 'v0-by-vercel' AND lang = 'ru';
UPDATE tools SET choose_if = $t119ci$["✅ Создаёте маркетинговый сайт, портфолио или контентный сайт — не приложение", "✅ Нужен точный контроль над дизайном и профессиональная CMS", "✅ Важна быстрая загрузка страниц и SEO-оптимизированный вывод (Webflow генерирует чистый HTML/CSS)", "✅ Хотите лучший визуальный конструктор в no-code пространстве"]$t119ci$::JSONB, faq = $t119fq$[{"q": "В чём разница между Bubble и Webflow?", "a": "Bubble — конструктор no-code приложений: для создания веб-приложений с базами данных, логикой и пользовательскими взаимодействиями. Webflow — конструктор сайтов с фокусом на дизайн и CMS. Bubble строит приложения, Webflow строит сайты."}, {"q": "Bubble подходит для SaaS?", "a": "Да. Bubble — одна из самых популярных платформ для создания SaaS-продуктов без кода. Он управляет авторизацией пользователей, базами данных, рабочими процессами и интеграцией API. Многие финансируемые стартапы используют Bubble как основную платформу."}, {"q": "Есть ли у Webflow база данных?", "a": "У Webflow есть CMS для структурированного контента (статьи блога, каталог товаров). Это не полноценная база данных приложения — для пользовательских данных, транзакций или сложной логики нужен Bubble или собственный бэкенд."}, {"q": "Что дешевле — Bubble или Webflow?", "a": "Стартовый план Webflow бесплатный. У Bubble тоже есть бесплатный план. Платные планы сопоставимы: Webflow Core от $29/мес, Bubble Starter от $32/мес. Стоимость масштабируется по-разному."}]$t119fq$::JSONB WHERE slug = 'webflow' AND lang = 'ru';
UPDATE tools SET choose_if = $t120ci$["✅ Нужны быстрые диаграммы, mind maps, flowcharts и wireframes для мозговых штурмов", "✅ Хотите ИИ-генерацию flowcharts и схем из текстового описания", "✅ Проводите встречи, где нужна совместная визуализация идей в реальном времени", "✅ Не дизайнер, но нужны аккуратные схемы процессов и пользовательских потоков"]$t120ci$::JSONB, faq = $t120fq$[{"q": "Whimsical vs Figma — в чём разница?", "a": "Whimsical специализируется на диаграммах, mind maps, flowcharts и быстрых wireframes. Figma — профессиональный UI/UX дизайн-инструмент для создания интерфейсов продуктов. Whimsical для визуализации идей, Figma для дизайна продуктов."}, {"q": "Whimsical бесплатный?", "a": "Да. Whimsical предлагает бесплатный план с неограниченными файлами и ограниченными ИИ-генерациями. Pro — $10/пользователь/мес. Figma имеет бесплатный план для индивидуалов."}, {"q": "Whimsical подходит для UX-дизайна?", "a": "Whimsical отлично подходит для wireframing на начальной стадии и пользовательских потоков. Для финального дизайна с компонентами и handoff — Figma. Многие UX-дизайнеры используют Whimsical для планирования, Figma для исполнения."}, {"q": "Какие ИИ-функции есть у Whimsical?", "a": "Whimsical AI генерирует flowcharts, mind maps и диаграммы из текстовых описаний. Достаточно написать процесс словами — AI создаёт визуальную схему."}]$t120fq$::JSONB WHERE slug = 'whimsical-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t121ci$["✅ Нужна транскрипция аудио/видео-файлов локально без отправки в облако", "✅ Хотите бесплатную точную транскрипцию без лимитов — Whisper от OpenAI open-source", "✅ Строите приложение с функцией речи в текст и нужен надёжный API", "✅ Транскрибируете контент на одном из 99 языков с автоопределением"]$t121ci$::JSONB, faq = $t121fq$[{"q": "Whisper vs Otter.ai — в чём разница?", "a": "Whisper — open-source модель транскрипции от OpenAI, которую запускают локально или через API. Otter.ai — коммерческий продукт для транскрипции встреч в реальном времени с командными функциями. Whisper — технология, Otter — готовый сервис."}, {"q": "Whisper бесплатный?", "a": "Whisper как модель полностью бесплатен с открытым исходным кодом. API OpenAI ($0.006/мин) — платный. Для запуска локально (через WhisperX, faster-whisper) — бесплатно без лимитов. Otter.ai — бесплатен с 600 мин/мес."}, {"q": "Насколько точен Whisper?", "a": "Whisper Large V3 — одна из точнейших моделей транскрипции для большинства языков. На чистой речи английского — точность 95%+. На акцентах и шумных записях точность снижается, но остаётся высокой."}, {"q": "Можно ли запустить Whisper локально?", "a": "Да. Whisper устанавливается через pip и работает на CPU (медленно) или GPU (быстро). faster-whisper — оптимизированная версия, в 4x быстрее оригинала. Для конфиденциальных записей локальный запуск — лучший выбор."}]$t121fq$::JSONB WHERE slug = 'whisper' AND lang = 'ru';
UPDATE tools SET choose_if = $t122ci$["✅ Хотите более автономный ИИ-редактор, который самостоятельно планирует и выполняет задачи через Cascade", "✅ Нужен быстрый и отзывчивый интерфейс без задержек, характерных для тяжёлых расширений", "✅ Ищете альтернативу Cursor по более низкой цене — Windsurf Pro дешевле", "✅ Хотите попробовать инструмент от Cognition (создателей Devin) с новым подходом к агентному кодированию"]$t122ci$::JSONB, faq = $t122fq$[{"q": "Windsurf лучше Cursor?", "a": "Windsurf предлагает более автономный опыт через Cascade (агент, который самостоятельно планирует изменения). Cursor считается более зрелым с лучшей поддержкой контекста кодовой базы. Оба на уровне друг друга по функциональности — выбор зависит от предпочтений рабочего процесса."}, {"q": "Что такое Windsurf Cascade?", "a": "Cascade — флагманская агентная система Windsurf. В отличие от обычных ИИ-автодополнений, Cascade понимает контекст всего проекта и самостоятельно планирует и выполняет многошаговые изменения кода без постоянного ввода промптов."}, {"q": "Windsurf дешевле Cursor?", "a": "Windsurf Pro стоит $15/мес против $20/мес у Cursor Pro. Оба предлагают бесплатные планы с ограниченным использованием ИИ-функций."}, {"q": "Windsurf — это от Cognition?", "a": "Да. Windsurf был приобретён Cognition (создателями Devin — первого ИИ-разработчика). Это означает доступ к передовым разработкам в области агентного кодирования. Продукт переименован, но доступен как windsurf.com."}]$t122fq$::JSONB WHERE slug = 'windsurf' AND lang = 'ru';
UPDATE tools SET choose_if = $t123ci$["✅ Нужна универсальная платформа: ИИ-писатель, чатбот (Chatsonic) и генерация изображений", "✅ Нужно более доступное ИИ-написание — планы Writesonic начинаются ниже Jasper", "✅ Создаёте высокообъёмный контент быстро без строгих требований к голосу бренда", "✅ Нужна встроенная интеграция с Google Поиском для фактически точного, актуального контента"]$t123ci$::JSONB, faq = $t123fq$[{"q": "Jasper AI стоит своих денег в 2026 году?", "a": "Jasper стоит того для команд контента из 3+ человек, где критична согласованность бренда. Обучение голосу бренда и командные функции оправдывают более высокую цену. Для отдельных создателей Claude, ChatGPT или Writesonic предлагают сопоставимое качество написания по более низкой цене."}, {"q": "Для чего используется Writesonic?", "a": "Writesonic — ИИ-контент-платформа для маркетологов и бизнеса. Генерирует публикации в блогах, рекламные тексты, описания товаров и лендинги. Chatsonic (его чатбот) имеет доступ к Google Поиску для актуальной информации. Также генерирует ИИ-изображения через Photosonic."}, {"q": "Writesonic бесплатный?", "a": "У Writesonic есть бесплатный пробный период с 25 кредитами. Individual plan начинается от $16/мес, Small Team — $45/мес. Корпоративные планы — индивидуальные. В целом дешевле Jasper при сопоставимых функциях."}, {"q": "Есть ли у Jasper SEO-инструменты?", "a": "Jasper интегрируется с Surfer SEO для оптимизации контента. Эта комбинация — Jasper для написания, Surfer для оптимизации — популярна среди команд контент-маркетинга. Jasper сам по себе не включает SEO-анализ, Surfer нужно добавлять отдельно."}]$t123fq$::JSONB WHERE slug = 'writesonic' AND lang = 'ru';
UPDATE tools SET choose_if = $t124ci$["✅ Загружаете YouTube-лекции и хотите интерактивно изучать видеоконтент с ИИ-ассистентом", "✅ Студент, которому нужно быстро усвоить видеолекции через вопросы и тесты", "✅ Хотите автоматически генерированные конспекты, карточки и тесты по видео", "✅ Учитесь с нескольких источников и хотите персональную учебную траекторию"]$t124ci$::JSONB, faq = $t124fq$[{"q": "YouLearn vs NotebookLM — в чём разница?", "a": "YouLearn специализируется на обучении по видео: анализирует YouTube и загруженные видео, создаёт конспекты и тесты. NotebookLM фокусируется на текстовых документах (PDF, заметки). YouLearn для видеообучения, NotebookLM для анализа документов."}, {"q": "YouLearn бесплатный?", "a": "YouLearn предлагает ограниченный бесплатный план. Pro-план для полного функционала. NotebookLM полностью бесплатен от Google с более щедрыми ограничениями."}, {"q": "NotebookLM поддерживает YouTube?", "a": "Да. NotebookLM может добавлять YouTube-видео как источники и транскрибировать их. Однако YouLearn более специализирован для обучения по видео с карточками и тестами."}, {"q": "Для чего лучше всего YouLearn?", "a": "YouLearn идеален для студентов, изучающих курсы на YouTube или Coursera. Загружаете видео, получаете автоматические конспекты, задаёте вопросы и проходите тесты по материалу — всё в одном месте."}]$t124fq$::JSONB WHERE slug = 'youlearn' AND lang = 'ru';
UPDATE tools SET choose_if = $t125ci$["✅ Хотите автоматизировать рабочие процессы между разными приложениями — не просто создавать контент", "✅ Нужен ИИ для классификации, извлечения или преобразования данных как части более широкой автоматизации", "✅ Подключаете 7000+ приложений и хотите ИИ как один шаг в многоприложном рабочем процессе", "✅ Создаёте автоматизированные процессы, которые выполняются без ручного вмешательства"]$t125ci$::JSONB, faq = $t125fq$[{"q": "В чём разница между Notion AI и Zapier AI?", "a": "Notion AI — ИИ-ассистент внутри Notion для создания и улучшения контента в вашем рабочем пространстве. Zapier AI ориентирован на автоматизацию — он использует ИИ для улучшения автоматизации рабочих процессов между приложениями. Notion AI — для работы со знаниями, Zapier AI — для автоматизации процессов."}, {"q": "Notion AI стоит своих денег?", "a": "Для активных пользователей Notion, которые регулярно пишут, Notion AI ($10/мес дополнительно) полезен для суммирования, перевода, переписывания и вопросов по документам. Если вам нужен ИИ-ассистент вне Notion, Claude или ChatGPT предлагают сопоставимые возможности за ту же цену."}, {"q": "Может ли Zapier AI заменить разработчика?", "a": "Zapier AI может автоматизировать многие задачи, ранее требовавшие участия разработчика: извлечение данных, классификацию и преобразование. Однако сложная кастомная логика по-прежнему требует программирования. Zapier AI снижает, но не устраняет потребность в технических ресурсах."}, {"q": "Есть ли у Notion автоматизация?", "a": "В Notion есть базовые встроенные автоматизации (триггеры кнопок, автоматизации баз данных). Для сложных межприложных рабочих процессов используйте Zapier или Make с интеграцией Notion. Notion AI обрабатывает контент, Zapier — внешние подключения к приложениям."}]$t125fq$::JSONB WHERE slug = 'zapier-ai' AND lang = 'ru';
UPDATE tools SET choose_if = $t126ci$["✅ Хотите максимально быстрый редактор кода — Zed написан на Rust и значительно быстрее VS Code", "✅ Нужна мощная совместная работа в реальном времени: несколько разработчиков редактируют один файл", "✅ Хотите минималистичный редактор с ИИ-функциями без тяжёлой экосистемы VS Code", "✅ Разрабатываете на Mac и нужна нативная производительность без лагов"]$t126ci$::JSONB, faq = $t126fq$[{"q": "Zed vs Cursor — что быстрее?", "a": "Zed значительно быстрее запускается и работает — он написан на Rust, нативно многопоточный. Cursor базируется на VS Code (Electron) и тяжелее. Для скорости редактора — Zed, для ИИ-функционала — Cursor."}, {"q": "Zed бесплатный?", "a": "Да. Zed полностью бесплатен с открытым исходным кодом. ИИ-функции (Zed AI) бесплатны с ограничениями; платный доступ для более высоких лимитов. Cursor — $20/мес за Pro."}, {"q": "Есть ли у Zed ИИ-функции?", "a": "Да. Zed AI включает автодополнение кода, встроенный чат с Claude/GPT и агентный режим для многофайловых задач. Функционал активно развивается и приближается к Cursor по возможностям."}, {"q": "Расширения VS Code работают в Zed?", "a": "Нет. Zed не использует формат расширений VS Code. У Zed своя экосистема плагинов, которая пока меньше. Если вы зависите от специфических расширений VS Code — учтите это при переходе."}]$t126fq$::JSONB WHERE slug = 'zed' AND lang = 'ru';
COMMIT;